const n=JSON.parse(`[{"paragraphs":["テレビや[雑誌](ざっし)では、よく「[血液](けつえき)[型](がた)[性格](せいかく)[判断](はんだん)」が[取](と)り[上](あ)げられます。これは、[血液](けつえき)[型](がた)によって[性格](せいかく)が[決](き)まっている、[言](い)い[換](か)えれば、[血液](けつえき)[型](がた)がわかれば[大体](だいたい)の[性格](せいかく)もわかるという（50）です。その[血液](けつえき)[型](がた)[性格](せいかく)[判断](はんだん)によると、[人](ひと)の[性格](せいかく)は、A[型](がた)、B[型](がた)、O[型](がた)、AB[型](がた)の[血液](けつえき)[型](がた)ごとに[決](き)まっているのだそうです。","しかし、この[世界](せかい)には[何](なん)[十](じゅう)[億](おく)[人](にん)もの[人](ひと)が（51a）、[人](ひと)の[性格](せいかく)をたった4[種類](しゅるい)に[分類](ぶんるい)することが（51b）。[血液](けつえき)[型](がた)は[親](おや)から[子](こ)への[遺伝](いでん)によって、4[種類](しゅるい)のうち、どの[型](かた)になるかが[決](き)まります。つまり、（52a）は[生](う)まれてから[死](し)ぬまで、[変](か)わることはほぼありません。[一方](いっぽう)、（52b）はどうでしょうか。（52c）に[関](かん)して[言](い)えば、[子](こ)どものときは[我慢](がまん)が[苦手](にがて)だった[子](こ)が、[成長](せいちょう)とともに[我慢](がまん)できるようになるといったことも[少](すく)なくないでしょう。","また、ある[調査](ちょうさ)によると、[自分](じぶん)の[血液](けつえき)[型](がた)がどんな[性格](せいかく)かということを[聞](き)いて、[知](し)らないうちに[自分](じぶん)の[性格](せいかく)がその[性格](せいかく)に[近](ちか)づいてしまっているということもあるそうです。「[私](わたし)はA[型](がた)だから、こういう[性格](せいかく)なんだ」という[思](おも)い[込](こ)みで、[性格](せいかく)が[作](つく)られている[可能](かのう)[性](せい)も[否定](ひてい)できないというのです。（53）、[性格](せいかく)と[血液](けつえき)[型](がた)に[関係](かんけい)はあると[言](い)えるかもしれませんが、それは[血液](けつえき)[型](がた)で[性格](せいかく)が[決](き)まるということではありません。こう[考](かんが)えると、やはり、[血液](けつえき)[型](がた)によって[性格](せいかく)がたった4[種類](しゅるい)に[分](わ)けられるとは（54）。"],"questions":[{"no":50,"options":["[点](てん)","もの","[場合](ばあい)","[結果](けっか)"],"answer":1,"grammar":"~というものだ","grammar_vi":"Là cái gọi là ~, tức là ~ (giải thích khái niệm)","sentence":"これは、[血液](けつえき)[型](がた)によって[性格](せいかく)が[決](き)まっている、[言](い)い[換](か)えれば、[血液](けつえき)[型](がた)がわかれば[大体](だいたい)の[性格](せいかく)もわかるという**もの**です。","sentence_vi":"Đây là quan điểm cho rằng tính cách được quyết định bởi nhóm máu, nói cách khác, nếu biết nhóm máu thì có thể hiểu được phần nào tính cách."},{"no":51,"options":["いるわけですから／できたのではないかと[考](かんが)えます","いるわけですから／できるのかと[疑問](ぎもん)に[思](おも)います","いるからこそ／[疑問](ぎもん)に[思](おも)われなかったのです","いるからこそ／できなかったのだと[考](かんが)えられます"],"answer":1,"grammar":"Thể thường+わけだから","grammar_vi":"Vì (dĩ nhiên) ~ nên ~ (nêu căn cứ hợp lý)","sentence":"しかし、この[世界](せかい)には[何](なん)[十](じゅう)[億](おく)[人](にん)もの[人](ひと)が**いるわけですから**、[人](ひと)の[性格](せいかく)をたった4[種類](しゅるい)に[分類](ぶんるい)することが**できるのかと[疑問](ぎもん)に[思](おも)います**。","sentence_vi":"Tuy nhiên, vì trên thế giới này có hàng tỷ người, nên tôi nghi ngờ liệu có thể phân loại tính cách con người chỉ thành 4 loại hay không."},{"no":52,"options":["[性格](せいかく)／[血液](けつえき)[型](がた)／[血液](けつえき)[型](がた)","[性格](せいかく)／[血液](けつえき)[型](がた)／[性格](せいかく)","[血液](けつえき)[型](がた)／[性格](せいかく)／[性格](せいかく)","[血液](けつえき)[型](がた)／[性格](せいかく)／[血液](けつえき)[型](がた)"],"answer":2,"grammar":"Nに関して言えば","grammar_vi":"Nói về ~ thì","sentence":"つまり、**[血液](けつえき)[型](がた)**は[生](う)まれてから[死](し)ぬまで、[変](か)わることはほぼありません。\\n[一方](いっぽう)、**[性格](せいかく)**はどうでしょうか。\\n**[性格](せいかく)**に[関](かん)して[言](い)えば、[子](こ)どものときは[我慢](がまん)が[苦手](にがて)だった[子](こ)が、[成長](せいちょう)とともに[我慢](がまん)できるようになるといったことも[少](すく)なくないでしょう。","sentence_vi":"Tức là, nhóm máu hầu như không thay đổi từ khi sinh ra đến khi chết. Còn tính cách thì sao? Nói về tính cách, cũng không ít trường hợp một đứa trẻ hồi nhỏ không chịu đựng giỏi lớn lên lại có thể chịu đựng được."},{"no":53,"options":["それが[本当](ほんとう)ならば","それと[比](くら)べても","そうあるべきなので","それが[前提](ぜんてい)でなかったら"],"answer":0,"grammar":"Thể thường+なら","grammar_vi":"Nếu ~ thì ~ (dựa trên điều vừa nghe)","sentence":"**それが[本当](ほんとう)ならば**、[性格](せいかく)と[血液](けつえき)[型](がた)に[関係](かんけい)はあると[言](い)えるかもしれませんが、それは[血液](けつえき)[型](がた)で[性格](せいかく)が[決](き)まるということではありません。","sentence_vi":"Nếu điều đó là thật thì có lẽ có thể nói tính cách và nhóm máu có liên quan, nhưng điều đó không có nghĩa là nhóm máu quyết định tính cách."},{"no":54,"options":["[言](い)われてこなかったのです","[言](い)われていないのでしょう","[言](い)えないことはないのです","[言](い)えないのではないでしょうか"],"answer":3,"grammar":"~とは言えないのではないでしょうか","grammar_vi":"Chẳng phải có thể nói là không ~ sao? (nêu nhận định nhẹ nhàng)","sentence":"こう[考](かんが)えると、やはり、[血液](けつえき)[型](がた)によって[性格](せいかく)がたった4[種類](しゅるい)に[分](わ)けられるとは**[言](い)えないのではないでしょうか**。","sentence_vi":"Nghĩ như vậy thì rốt cuộc, chẳng phải có thể nói là không thể chia tính cách thành chỉ 4 loại theo nhóm máu sao."}],"translation_vi":"Trên truyền hình và tạp chí, thường xuyên có những bài viết về \\"phân tích tính cách theo nhóm máu\\". Đây là quan điểm cho rằng tính cách được quyết định bởi nhóm máu, nói cách khác, nếu biết nhóm máu thì có thể hiểu được phần nào tính cách. Theo phân tích tính cách theo nhóm máu này, tính cách con người được quyết định theo từng nhóm máu A, B, O, AB.\\n\\nTuy nhiên, vì trên thế giới này có hàng tỷ người, nên tôi nghi ngờ liệu có thể phân loại tính cách con người chỉ thành 4 loại hay không. Nhóm máu được quyết định bởi di truyền từ cha mẹ sang con, thuộc một trong 4 loại. Tức là, nhóm máu hầu như không thay đổi từ khi sinh ra đến khi chết. Còn tính cách thì sao? Nói về tính cách, cũng không ít trường hợp một đứa trẻ hồi nhỏ không chịu đựng giỏi lớn lên lại có thể chịu đựng được.\\n\\nNgoài ra, theo một cuộc khảo sát, có trường hợp khi nghe nói nhóm máu của mình có tính cách như thế nào, thì không biết từ lúc nào tính cách của bản thân lại dần tiến gần tới tính cách đó. Người ta nói rằng không thể phủ nhận khả năng tính cách đang được hình thành bởi suy nghĩ cố định kiểu \\"Mình nhóm máu A nên tính cách là như thế\\". Nếu điều đó là thật thì có lẽ có thể nói tính cách và nhóm máu có liên quan, nhưng điều đó không có nghĩa là nhóm máu quyết định tính cách. Nghĩ như vậy thì rốt cuộc, chẳng phải có thể nói là không thể chia tính cách thành chỉ 4 loại theo nhóm máu sao."},{"paragraphs":["[春](はる)が[訪](おとず)れ、[過](す)ごしやすい[季節](きせつ)になりました。しかし[最近](さいきん)、（50）[花粉](かふん)[症](しょう)に[悩](なや)まされる[人](ひと)が[増](ふ)えています。[春](はる)は[花粉](かふん)[症](しょう)の[季節](きせつ)でもあるのです。","[花粉](かふん)[症](しょう)とは[何](なに)でしょうか。[花粉](かふん)[症](しょう)は[花粉](かふん)に[対](たい)するアレルギー[反応](はんのう)で、アレルギー[体質](たいしつ)の[人](ひと)は[花粉](かふん)[症](しょう)になりやすいといわれています。[花粉](かふん)は[体](からだ)にとって[有害](ゆうがい)なものではありません。しかし、[花粉](かふん)[症](しょう)になりやすい[人](ひと)の[体](からだ)に[花粉](かふん)が[入](はい)ると、[体](からだ)は[花粉](かふん)を[侵入](しんにゅう)[者](しゃ)だと[思](おも)って、[花粉](かふん)に[対](たい)してガードマンのような[働](はたら)きをする「[抗体](こうたい)」を[作](つく)り[出](だ)します。この「[抗体](こうたい)」が[蓄積](ちくせき)されて[一定](いってい)の[水準](すいじゅん)になると、[花粉](かふん)を[追](お)い[出](だ)すためにくしゃみや[鼻水](はなみず)などのアレルギー[症状](しょうじょう)が[現](あらわ)れます。そのくしゃみや[鼻水](はなみず)によって[花粉](かふん)を[追](お)い[出](だ)そうとするのです。（51）、[花粉](かふん)に[対](たい)して[体](からだ)が[過剰](かじょう)に[反応](はんのう)して[症状](しょうじょう)が[出](で)るのが[花粉](かふん)[症](しょう)というわけです。","[花粉](かふん)が[多](おお)く[飛](と)ぶ[季節](きせつ)を[快適](かいてき)に[過](す)ごすために、[花粉](かふん)[症](しょう)の[人](ひと)は[規則正](きそくただ)しい[生活](せいかつ)をして、[体調](たいちょう)[管理](かんり)に[努](つと)め、とにかく[花粉](かふん)に[接](せっ)しないようにしなければなりません。[外出](がいしゅつ)[時](じ)には、マスクやメガネで[花粉](かふん)が[体](からだ)に[入](はい)るのを[防](ふせ)ぎ、[帰宅](きたく)[時](じ)には[服](ふく)に[付](つ)いた[花粉](かふん)を[落](お)としてから、[家](いえ)に（52）。","[実](じつ)は、[今](いま)[花粉](かふん)[症](しょう)ではない[人](ひと)も、[今後](こんご)[症状](しょうじょう)が[現](あらわ)れる[可能](かのう)[性](せい)があります。[花粉](かふん)[症](しょう)にならないようにするためには、[花粉](かふん)[症](しょう)の[人](ひと)と[同](おな)じようになるべく[花粉](かふん)に[接](せっ)しないことが[重要](じゅうよう)です。[生活](せいかつ)[空間](くうかん)に[花粉](かふん)を[持](も)ち[込](こ)まないようにしてください。いつ[誰](だれ)が[花粉](かふん)[症](しょう)になっても[不思議](ふしぎ)ではありません。[誰](だれ)も[自分](じぶん)には[関係](かんけい)がないとは[言](い)えないもの、それが（53）です。[花粉](かふん)[症](しょう)の[人](ひと)もそうではない[人](ひと)も、[春](はる)は[過](す)ごし[方](かた)に[少](すこ)し（54）。"],"questions":[{"no":50,"options":["そういう","それの","この[季節](きせつ)に","この[夏](なつ)に"],"answer":2,"grammar":"この+N(chỉ thị)","grammar_vi":"N này (chỉ điều đang nói đến)","sentence":"しかし[最近](さいきん)、**この[季節](きせつ)に**[花粉](かふん)[症](しょう)に[悩](なや)まされる[人](ひと)が[増](ふ)えています。","sentence_vi":"Tuy nhiên gần đây, số người khổ sở vì bệnh dị ứng phấn hoa vào mùa này đang tăng lên."},{"no":51,"options":["このように","いっぽうで","ちなみに","それどころか"],"answer":0,"grammar":"このように","grammar_vi":"Như vậy, theo cách này (tổng kết điều vừa nói)","sentence":"**このように**、[花粉](かふん)に[対](たい)して[体](からだ)が[過剰](かじょう)に[反応](はんのう)して[症状](しょうじょう)が[出](で)るのが[花粉](かふん)[症](しょう)というわけです。","sentence_vi":"Như vậy, việc cơ thể phản ứng quá mức với phấn hoa và xuất hiện triệu chứng chính là dị ứng phấn hoa."},{"no":52,"options":["[入](はい)ってあげるのでしょう","[入](い)れてあげましょう","[入](い)れるのでしょう","[入](はい)りましょう"],"answer":3,"grammar":"Vましょう","grammar_vi":"Hãy cùng ~ (rủ rê, đề nghị)","sentence":"[外出](がいしゅつ)[時](じ)には、マスクやメガネで[花粉](かふん)が[体](からだ)に[入](はい)るのを[防](ふせ)ぎ、[帰宅](きたく)[時](じ)には[服](ふく)に[付](つ)いた[花粉](かふん)を[落](お)としてから、[家](いえ)に**[入](はい)りましょう**。","sentence_vi":"Khi ra ngoài, hãy dùng khẩu trang và kính để ngăn phấn hoa vào cơ thể, khi về nhà thì phủi sạch phấn hoa bám trên quần áo rồi hãy vào nhà."},{"no":53,"options":["[規則](きそく)","[有害](ゆうがい)","[花粉](かふん)[症](しょう)","[抗体](こうたい)"],"answer":2,"grammar":"~、それが~だ","grammar_vi":"~, chính đó là ~ (nhấn mạnh điều vừa nêu)","sentence":"[誰](だれ)も[自分](じぶん)には[関係](かんけい)がないとは[言](い)えないもの、それが**[花粉](かふん)[症](しょう)**です。","sentence_vi":"Không ai có thể nói điều này không liên quan đến mình — đó chính là dị ứng phấn hoa."},{"no":54,"options":["[気](き)をつけてみたらどうでしょうか","[気](き)をつけた[方](ほう)がいいのでしょうか","[気](き)をつけているそうです","[気](き)をつければよかったです"],"answer":0,"grammar":"Vたらどうですか","grammar_vi":"Hay là ~ thì sao? (gợi ý)","sentence":"[花粉](かふん)[症](しょう)の[人](ひと)もそうではない[人](ひと)も、[春](はる)は[過](す)ごし[方](かた)に[少](すこ)し**[気](き)をつけてみたらどうでしょうか**。","sentence_vi":"Dù là người bị dị ứng phấn hoa hay không, vào mùa xuân hãy thử chú ý hơn một chút đến cách sinh hoạt thì sao?"}],"translation_vi":"Mùa xuân đến, đã trở thành mùa dễ sống. Tuy nhiên gần đây, số người khổ sở vì bệnh dị ứng phấn hoa vào mùa này đang tăng lên. Mùa xuân cũng là mùa của dị ứng phấn hoa.\\n\\nDị ứng phấn hoa là gì? Dị ứng phấn hoa là phản ứng dị ứng đối với phấn hoa, và người có cơ địa dị ứng được cho là dễ bị dị ứng phấn hoa. Phấn hoa vốn không có hại cho cơ thể. Nhưng khi phấn hoa xâm nhập vào cơ thể người dễ bị dị ứng phấn hoa, cơ thể coi phấn hoa là kẻ xâm nhập và tạo ra \\"kháng thể\\" hoạt động như người bảo vệ chống lại phấn hoa. Khi kháng thể này tích tụ đến một mức nhất định, các triệu chứng dị ứng như hắt hơi, chảy nước mũi xuất hiện để đẩy phấn hoa ra ngoài. Cơ thể cố gắng tống phấn hoa ra bằng hắt hơi và nước mũi. Như vậy, việc cơ thể phản ứng quá mức với phấn hoa và xuất hiện triệu chứng chính là dị ứng phấn hoa.\\n\\nĐể trải qua mùa phấn hoa bay nhiều một cách thoải mái, người bị dị ứng phấn hoa phải sống điều độ, chăm sóc sức khỏe và tuyệt đối tránh tiếp xúc với phấn hoa. Khi ra ngoài, hãy dùng khẩu trang và kính để ngăn phấn hoa vào cơ thể, khi về nhà thì phủi sạch phấn hoa bám trên quần áo rồi hãy vào nhà.\\n\\nThực ra, ngay cả người hiện chưa bị dị ứng phấn hoa cũng có khả năng xuất hiện triệu chứng trong tương lai. Để không bị dị ứng phấn hoa, điều quan trọng là cũng giống như người bị dị ứng, phải cố gắng tránh tiếp xúc với phấn hoa. Hãy cố gắng đừng mang phấn hoa vào không gian sống. Không có gì lạ khi bất cứ ai, vào bất cứ lúc nào, cũng có thể bị dị ứng phấn hoa. Không ai có thể nói điều này không liên quan đến mình — đó chính là dị ứng phấn hoa. Dù là người bị dị ứng phấn hoa hay không, vào mùa xuân hãy thử chú ý hơn một chút đến cách sinh hoạt thì sao?","title":"[花粉](かふん)[症](しょう)とうまく[付](つ)き[合](あ)う"},{"paragraphs":["[鉄道](てつどう)ファンとは、[鉄道](てつどう)が[好](す)きで[鉄道](てつどう)に[関](かん)することを[趣味](しゅみ)にしている[人](ひと)たちのことだ。[鉄道](てつどう)ファンは[単](たん)に「[鉄](てつ)」と[言](い)われたりもする。[日本](にほん)では、これまでは「[鉄](てつ)」といえば[男性](だんせい)だと[思](おも)われていたが、[近年](きんねん)は[女性](じょせい)のファンが[急増](きゅうぞう)しているらしい。","ところで、[彼](かれ)ら[鉄道](てつどう)ファンたちは（50）[趣味](しゅみ)を[楽](たの)しんでいるのだろうか。[一言](ひとこと)で[鉄道](てつどう)ファンといってもその[趣味](しゅみ)の[内容](ないよう)は[多種](たしゅ)[多様](たよう)だ。そして、[電車](でんしゃ)に[乗](の)るのが[好](す)きな「[鉄](てつ)」は「[乗](の)り[鉄](てつ)」というように、それぞれその[内容](ないよう)に[対応](たいおう)した[呼](よ)び[名](な)がある。「[乗](の)り[鉄](てつ)」（51）、[写真](しゃしん)を[撮](と)るのが[好](す)きな「[撮](と)り[鉄](てつ)」、[車両](しゃりょう)や[鉄道](てつどう)がある[風景](ふうけい)を[描](えが)く「[描](えが)き[鉄](てつ)」、[鉄道](てつどう)の[模型](もけい)が[好](す)きな「[模型](もけい)[鉄](てつ)」などだ。","ある40[代](だい)の「[乗](の)り[鉄](てつ)」の[女性](じょせい)は[鉄道](てつどう)の[魅力](みりょく)を（52）[語](かた)る。「[窓](まど)の[外](そと)の[風景](ふうけい)をながめていると[旅](たび)の[気分](きぶん)が[味](あじ)わえるし、[車](くるま)と[違](ちが)って[座](すわ)っているだけで[目的](もくてき)[地](ち)に[着](つ)けるのがいい」。「[模型](もけい)[鉄](てつ)」である30[代](だい)の[男性](だんせい)は、[模型](もけい)の[魅力](みりょく)について「[車両](しゃりょう)の[形](かたち)を[見](み)ているだけでうっとり。[本物](ほんもの)は[買](か)えないけど[模型](もけい)なら[買](か)えるし」と[説明](せつめい)する。","また、[最近](さいきん)[急増](きゅうぞう)している[女性](じょせい)ファンには「ママ[鉄](てつ)」も[多](おお)い。[電車](でんしゃ)を[見](み)たがる[子](こ)どもを[連](つ)れて[電車](でんしゃ)を[見](み)に[行](い)くうち、[自分](じぶん)も[鉄道](てつどう)ファンになってしまったという[人](ひと)たちだ。（53）の[特徴](とくちょう)は、[他](た)の「[鉄](てつ)」とは[異](こと)なり、ホームではなく、[電車](でんしゃ)が[見](み)えるところにある[公園](こうえん)やレストランなど、[子](こ)どもと[一緒](いっしょ)にゆっくり[過](す)ごせる[場所](ばしょ)で[電車](でんしゃ)を[見](み)るという[点](てん)である。","[鉄道](てつどう)ファンにはいろいろなタイプがあり、[楽](たの)しみ[方](かた)も（54）。"],"questions":[{"no":50,"options":["それほど","どのように","それでも","どちらの"],"answer":1,"grammar":"Từ nghi vấn+thể thường+のか","grammar_vi":"~ tại sao/như thế nào/gì (câu hỏi lồng)","sentence":"ところで、[彼](かれ)ら[鉄道](てつどう)ファンたちは**どのように**[趣味](しゅみ)を[楽](たの)しんでいるのだろうか。","sentence_vi":"Mà này, những người hâm mộ đường sắt đó thưởng thức sở thích của mình như thế nào nhỉ?"},{"no":51,"options":["にかわって","によって","のうえ","のほか"],"answer":3,"grammar":"Nのほかに","grammar_vi":"Ngoài ~ ra còn ~","sentence":"「[乗](の)り[鉄](てつ)」**のほか**、[写真](しゃしん)を[撮](と)るのが[好](す)きな「[撮](と)り[鉄](てつ)」、[車両](しゃりょう)や[鉄道](てつどう)がある[風景](ふうけい)を[描](えが)く「[描](えが)き[鉄](てつ)」、[鉄道](てつどう)の[模型](もけい)が[好](す)きな「[模型](もけい)[鉄](てつ)」などだ。","sentence_vi":"Ngoài \\"nori-tetsu\\", còn có \\"tori-tetsu\\" thích chụp ảnh, \\"kaki-tetsu\\" vẽ tranh phong cảnh có tàu, \\"mokei-tetsu\\" thích mô hình tàu hỏa, v.v."},{"no":52,"options":["こう","そう","[同様](どうよう)に","[以上](いじょう)のように"],"answer":0,"grammar":"こう(chỉ thị)","grammar_vi":"Như thế này, theo cách này (chỉ điều sắp nêu)","sentence":"ある40[代](だい)の「[乗](の)り[鉄](てつ)」の[女性](じょせい)は[鉄道](てつどう)の[魅力](みりょく)を**こう**[語](かた)る。","sentence_vi":"Một phụ nữ ngoài 40 tuổi thuộc nhóm \\"nori-tetsu\\" kể về sức hấp dẫn của tàu hỏa như thế này."},{"no":53,"options":["[鉄道](てつどう)ファン","[女性](じょせい)ファン","[彼女](かのじょ)たち","[大人](おとな)たち"],"answer":2,"grammar":"彼ら/彼女たち","grammar_vi":"Họ (đại từ chỉ nhóm người vừa nhắc đến)","sentence":"**[彼女](かのじょ)たち**の[特徴](とくちょう)は、[他](た)の「[鉄](てつ)」とは[異](こと)なり、ホームではなく、[電車](でんしゃ)が[見](み)えるところにある[公園](こうえん)やレストランなど、[子](こ)どもと[一緒](いっしょ)にゆっくり[過](す)ごせる[場所](ばしょ)で[電車](でんしゃ)を[見](み)るという[点](てん)である。","sentence_vi":"Đặc điểm của họ là khác với các \\"tetsu\\" khác, họ không ngắm tàu ở sân ga mà ở những nơi có thể thong thả bên con như công viên, nhà hàng nhìn thấy tàu."},{"no":54,"options":["さまざまだ","さまざまだと[言](い)われた","さまざまである[点](てん)だ","さまざまだと[思](おも)われている"],"answer":0,"grammar":"Nはさまざまだ","grammar_vi":"~ đa dạng, nhiều kiểu khác nhau","sentence":"[鉄道](てつどう)ファンにはいろいろなタイプがあり、[楽](たの)しみ[方](かた)も**さまざまだ**。","sentence_vi":"Người hâm mộ đường sắt có nhiều kiểu khác nhau, cách thưởng thức cũng đa dạng."}],"translation_vi":"Người hâm mộ đường sắt là những người thích tàu hỏa và coi những điều liên quan đến tàu hỏa là sở thích. Họ đôi khi được gọi đơn giản là \\"tetsu\\" (sắt). Ở Nhật, trước đây nói đến \\"tetsu\\" người ta thường nghĩ đó là nam giới, nhưng gần đây dường như số người hâm mộ nữ đang tăng nhanh.\\n\\nVậy những người hâm mộ đường sắt ấy thưởng thức sở thích của mình như thế nào? Dù nói chung là người hâm mộ đường sắt, nội dung sở thích của họ rất đa dạng. Và \\"tetsu\\" thích đi tàu thì gọi là \\"nori-tetsu\\", mỗi nhóm đều có tên gọi tương ứng với sở thích của mình. Ngoài \\"nori-tetsu\\", còn có \\"tori-tetsu\\" thích chụp ảnh, \\"kaki-tetsu\\" vẽ tranh phong cảnh có toa tàu hay đường sắt, \\"mokei-tetsu\\" thích mô hình tàu hỏa, v.v.\\n\\nMột phụ nữ ngoài 40 tuổi thuộc nhóm \\"nori-tetsu\\" kể về sức hấp dẫn của tàu hỏa như thế này: \\"Ngắm phong cảnh ngoài cửa sổ là có thể cảm nhận cảm giác đi du lịch, và khác với ô tô, chỉ cần ngồi là đến được nơi cần đến, thế là tuyệt.\\" Một người đàn ông ngoài 30 tuổi thuộc nhóm \\"mokei-tetsu\\" giải thích về sức hấp dẫn của mô hình: \\"Chỉ ngắm hình dáng toa tàu thôi là đã mê rồi. Đồ thật không mua nổi nhưng mô hình thì mua được.\\"\\n\\nNgoài ra, trong số những người hâm mộ nữ đang tăng nhanh gần đây cũng có nhiều \\"mama-tetsu\\". Họ là những người dẫn con nhỏ thích xem tàu đi xem tàu, rồi trong lúc đó chính mình cũng trở thành người hâm mộ đường sắt. Đặc điểm của họ là khác với các \\"tetsu\\" khác, họ không ngắm tàu ở sân ga mà ở những nơi có thể thong thả bên con như công viên, nhà hàng nhìn thấy tàu.\\n\\nNgười hâm mộ đường sắt có nhiều kiểu khác nhau, cách thưởng thức cũng đa dạng.","title":"[日本](にほん)の[鉄道](てつどう)ファン"},{"paragraphs":["もし[家](いえ)を[建](た)てるなら、どんな[家](いえ)がいいですか。もちろん[長](なが)く[住](す)める[家](いえ)がいいですよね。[日本](にほん)で[町](まち)を[見渡](みわた)してみると、[頑丈](がんじょう)そうな[建物](たてもの)が[並](なら)んでいます。ところが、ある[調査](ちょうさ)によると[日本](にほん)の[家](いえ)の[平均](へいきん)[寿命](じゅみょう)は、[英国](えいこく)77[年](ねん)、[米国](べいこく)55[年](ねん)に[比](くら)べて[短](みじか)く30[年](ねん)ほどだそうです。（50）[結果](けっか)になったのでしょうか。[原因](げんいん)の[一](ひと)つに、[戦後](せんご)の[日本](にほん)の[特殊](とくしゅ)な[住宅](じゅうたく)[事情](じじょう)があるようです。[第](だい)[二](に)[次](じ)[世界](せかい)[大戦](たいせん)[後](ご)、[日本](にほん)では、[家](いえ)[不足](ふそく)が[深刻](しんこく)だったため、[質](しつ)より[量](りょう)を[優先](ゆうせん)させて[家](いえ)が[作](つく)られました。しかし、[経済](けいざい)が[成長](せいちょう)して[生活](せいかつ)に[余裕](よゆう)が[生](う)まれると、[人々](ひとびと)はより[質](しつ)の[高](たか)い[家](いえ)を[求](もと)めるようになります。そこで、それまでの[家](いえ)は[次々](つぎつぎ)に（51）そうです。その[結果](けっか)、[町](まち)には、[今](いま)のような[頑丈](がんじょう)そうな[質](しつ)の[高](たか)い[住宅](じゅうたく)が[立](た)ち[並](なら)ぶことになったのです。","また、[日本人](にほんじん)の[住宅](じゅうたく)[観](かん)も[原因](げんいん)として（52）。[日本](にほん)には、[家](いえ)はそこに[住](す)む[家族](かぞく)に[合](あ)わせて[建](た)てるという[考](かんが)え[方](かた)があります。たとえば、[将来](しょうらい)[子供](こども)が[生](う)まれ[家族](かぞく)が[増](ふ)えることを[考](かんが)えて[建](た)てた[家](いえ)も、[子供](こども)が[成人](せいじん)して[独立](どくりつ)してしまうと、[夫婦](ふうふ)[二](に)[人](にん)だけの[生活](せいかつ)には[合](あ)わなくなります。そのため、[年](とし)をとった[夫婦](ふうふ)のためには[住](す)むのに[適](てき)した[家](いえ)へと[建](た)て[替](か)えるのです。そんなふうに[家族](かぞく)の[形](かたち)が[変](か)わったとき、[今](いま)まで[住](す)んでいた[家](いえ)を[建](た)て[替](か)えることも[少](すく)なくないそうです。","（53）、[日本](にほん)では[家](いえ)を[建](た)て[替](か)えることが[多](おお)いために、[家](いえ)の[平均](へいきん)[寿命](じゅみょう)が[短](みじか)いという[調査](ちょうさ)[結果](けっか)になったのだと[思](おも)います。[平均](へいきん)[寿命](じゅみょう)30[年](ねん)というのは、30[年](ねん)で[壊](こわ)れてしまうという[意味](いみ)ではないのです。もし[皆](みな)さんが、[自分](じぶん)のために、[家族](かぞく)のために、[日本](にほん)で[家](いえ)を[建](た)てるなら……どんな（54）。"],"questions":[{"no":50,"options":["なぜこのような","なぜあのような","[果](はた)してどのような","はたしてそのような"],"answer":0,"grammar":"このような+N","grammar_vi":"N như thế này (chỉ điều vừa nêu ở trước)","sentence":"なぜ**このような**[結果](けっか)になったのでしょうか。","sentence_vi":"Tại sao lại ra kết quả như vậy?"},{"no":51,"options":["[建](た)て[替](か)えていく","[建](た)て[替](か)えさせていた","[建](た)て[替](か)えさせられている","[建](た)て[替](か)えられていった"],"answer":3,"grammar":"Vられていく","grammar_vi":"Dần dần bị/được ~ (diễn ra liên tục)","sentence":"そこで、それまでの[家](いえ)は[次々](つぎつぎ)に**[建](た)て[替](か)えられていった**そうです。","sentence_vi":"Vì thế, nghe nói những ngôi nhà cho đến lúc đó lần lượt bị xây lại."},{"no":52,"options":["[思](おも)われます","わかります","[考](かんが)えられます","[調](しら)べられます"],"answer":2,"grammar":"~として考えられる","grammar_vi":"Có thể xem là ~ (nguyên nhân...)","sentence":"また、[日本人](にほんじん)の[住宅](じゅうたく)[観](かん)も[原因](げんいん)として**[考](かんが)えられます**。","sentence_vi":"Ngoài ra, quan niệm về nhà ở của người Nhật cũng có thể được xem là một nguyên nhân."},{"no":53,"options":["ところで","つまり","なぜなら","もちろん"],"answer":1,"grammar":"つまり","grammar_vi":"Tức là, nói cách khác","sentence":"**つまり**、[日本](にほん)では[家](いえ)を[建](た)て[替](か)えることが[多](おお)いために、[家](いえ)の[平均](へいきん)[寿命](じゅみょう)が[短](みじか)いという[調査](ちょうさ)[結果](けっか)になったのだと[思](おも)います。","sentence_vi":"Tức là, tôi nghĩ vì ở Nhật người ta hay xây lại nhà nên mới có kết quả khảo sát là tuổi thọ trung bình của nhà ngắn."},{"no":54,"options":["[家](いえ)を[建](た)てたのですか","[家](いえ)に[住](す)めたのですか","[家](いえ)を[建](た)てますか","[家](いえ)に[住](す)めますか"],"answer":2,"grammar":"どんなNを~か(hỏi người đọc)","grammar_vi":"Bạn sẽ ~ N như thế nào? (đặt câu hỏi cho người đọc)","sentence":"もし[皆](みな)さんが、[自分](じぶん)のために、[家族](かぞく)のために、[日本](にほん)で[家](いえ)を[建](た)てるなら……どんな**[家](いえ)を[建](た)てますか**。","sentence_vi":"Nếu các bạn xây nhà ở Nhật vì bản thân, vì gia đình... thì các bạn sẽ xây ngôi nhà như thế nào?"}],"translation_vi":"Nếu xây nhà, bạn muốn ngôi nhà như thế nào? Tất nhiên là ngôi nhà có thể ở lâu dài phải không. Nhìn quanh các thành phố ở Nhật, thấy những tòa nhà trông rất kiên cố san sát. Thế nhưng, theo một cuộc khảo sát, tuổi thọ trung bình của nhà ở Nhật chỉ khoảng 30 năm, ngắn hơn so với 77 năm ở Anh và 55 năm ở Mỹ. Tại sao lại ra kết quả như vậy? Một trong những nguyên nhân dường như là tình hình nhà ở đặc thù của Nhật sau chiến tranh. Sau Thế chiến thứ hai, ở Nhật tình trạng thiếu nhà rất nghiêm trọng nên nhà được xây ưu tiên số lượng hơn chất lượng. Tuy nhiên, khi kinh tế tăng trưởng và cuộc sống dư dả hơn, người ta bắt đầu tìm những ngôi nhà chất lượng cao hơn. Vì thế, nghe nói những ngôi nhà cho đến lúc đó lần lượt bị xây lại. Kết quả là thành phố có những ngôi nhà chất lượng cao, kiên cố như bây giờ.\\n\\nNgoài ra, quan niệm về nhà ở của người Nhật cũng có thể được xem là một nguyên nhân. Ở Nhật có quan niệm rằng nhà được xây phù hợp với gia đình sống trong đó. Chẳng hạn, ngôi nhà được xây với tính đến việc tương lai con cái ra đời, gia đình đông thêm, nhưng khi con cái trưởng thành và ra ở riêng thì không còn phù hợp với cuộc sống chỉ của hai vợ chồng. Vì vậy, người ta xây lại thành ngôi nhà phù hợp cho vợ chồng lớn tuổi. Nghe nói khi hình thái gia đình thay đổi như vậy, việc xây lại ngôi nhà đang ở cũng không hiếm.\\n\\nTức là, tôi nghĩ vì ở Nhật người ta hay xây lại nhà nên mới có kết quả khảo sát là tuổi thọ trung bình của nhà ngắn. Tuổi thọ trung bình 30 năm không có nghĩa là nhà bị hỏng sau 30 năm. Nếu các bạn xây nhà ở Nhật vì bản thân, vì gia đình... thì các bạn sẽ xây ngôi nhà như thế nào?","title":"[日本](にほん)の[家](いえ)の[寿命](じゅみょう)"},{"paragraphs":["[飲食店](いんしょくてん)には、[夜](よる)だけでなく[昼](ひる)も[営業](えいぎょう)して、ランチメニューを[出](だ)しているところも[多](おお)い。このランチメニュー、たいていは[夜](よる)に[比](くら)べると[手](て)ごろな[価格](かかく)に[設定](せってい)されている。（50）、[夜](よる)はパスタだけで1,200[円](えん)ぐらいする[店](みせ)でも[昼](ひる)はパスタにスープとサラダがついて980[円](えん)といったものや、[夜](よる)はコース[料理](りょうり)が5,000[円](えん)[以上](いじょう)する[店](みせ)でも[昼](ひる)は1,000[円](えん)[前後](ぜんご)になるといったものだ。","この[昼](ひる)と[夜](よる)の[価格](かかく)[差](さ)は[一体](いったい)、[何](なに)によるものなのだろうか。[安](やす)いからといって、[料理](りょうり)[人](じん)が[手](て)を[抜](ぬ)いているとか、[安](やす)い[材料](ざいりょう)を[使](つか)っているとか、そういったことは（51）ない。[味](あじ)が[落](お)ちれば[悪](わる)い[評判](ひょうばん)が[立](た)ち、[夜](よる)の[営業](えいぎょう)にも[悪影響](あくえいきょう)を[与](あた)えてしまう。","ランチメニューを[安](やす)くできる[理由](りゆう)は[単純](たんじゅん)[明快](めいかい)だ。[飲食店](いんしょくてん)に[限](かぎ)らず、[店](みせ)を[経営](けいえい)していくためには、[材料](ざいりょう)[費](ひ)、[光熱](こうねつ)[費](ひ)、[店員](てんいん)の[給料](きゅうりょう)などさまざまなコストがかかるが、そのコストをおさえられれば、[商品](しょうひん)の[価格](かかく)を[下](さ)げても[利益](りえき)は[上](あ)げることができる。（52）、メニューをいくつかに[絞](しぼ)るという[方法](ほうほう)で、コストをおさえている[店](みせ)が[多](おお)い。メニューが[少](すく)なければ、[準備](じゅんび)や[調理](ちょうり)に[時間](じかん)がかからず、[多](おお)くの[料理](りょうり)[人](じん)を[働](はたら)かせる[必要](ひつよう)もない。そのため、[安](やす)くすることができると（53）。","コストをおさえて、[安](やす)いランチメニューでも[飲食店](いんしょくてん)は[利益](りえき)を[上](あ)げている。また、[安](やす)くておいしいランチを[食](た)べた[客](きゃく)が[店](みせ)を[気](き)に[入](い)り、[夜](よる)も[店](みせ)を[訪](おとず)れる[可能](かのう)[性](せい)もある。[飲食店](いんしょくてん)にとって、[利益](りえき)が[上](あ)げられ、さらに[客](きゃく)も[獲得](かくとく)できるランチは、「おいしい」（54）。"],"questions":[{"no":50,"options":["ただし","それに","あるいは","たとえば"],"answer":3,"grammar":"たとえば","grammar_vi":"Ví dụ, chẳng hạn","sentence":"**たとえば**、[夜](よる)はパスタだけで1,200[円](えん)ぐらいする[店](みせ)でも[昼](ひる)はパスタにスープとサラダがついて980[円](えん)といったものや、[夜](よる)はコース[料理](りょうり)が5,000[円](えん)[以上](いじょう)する[店](みせ)でも[昼](ひる)は1,000[円](えん)[前後](ぜんご)になるといったものだ。","sentence_vi":"Ví dụ, có quán buổi tối riêng món mì Ý đã khoảng 1.200 yên nhưng buổi trưa mì Ý kèm súp và salad chỉ 980 yên, hay quán buổi tối món set từ 5.000 yên trở lên nhưng buổi trưa chỉ khoảng 1.000 yên."},{"no":51,"options":["[意外](いがい)では","[間違](まちが)いでは","だから","もちろん"],"answer":3,"grammar":"もちろん~ない","grammar_vi":"Dĩ nhiên là không ~","sentence":"[安](やす)いからといって、[料理](りょうり)[人](じん)が[手](て)を[抜](ぬ)いているとか、[安](やす)い[材料](ざいりょう)を[使](つか)っているとか、そういったことは**もちろん**ない。","sentence_vi":"Dù rẻ nhưng tất nhiên không có chuyện đầu bếp làm ẩu hay dùng nguyên liệu rẻ tiền."},{"no":52,"options":["[次](つぎ)の[場合](ばあい)","その[店](みせ)の[場合](ばあい)","ランチの[場合](ばあい)","[夜](よる)の[営業](えいぎょう)の[場合](ばあい)"],"answer":2,"grammar":"Nの場合","grammar_vi":"Trong trường hợp ~ thì","sentence":"**ランチの[場合](ばあい)**、メニューをいくつかに[絞](しぼ)るという[方法](ほうほう)で、コストをおさえている[店](みせ)が[多](おお)い。","sentence_vi":"Trong trường hợp bữa trưa, nhiều quán giảm chi phí bằng cách thu hẹp thực đơn chỉ còn vài món."},{"no":53,"options":["いうわけだ","いう[点](てん)か","いうくらい","いうからか"],"answer":0,"grammar":"~というわけだ","grammar_vi":"Nghĩa là vậy, có nghĩa là ~ (kết luận, giải thích)","sentence":"そのため、[安](やす)くすることができると**いうわけだ**。","sentence_vi":"Vì vậy, họ có thể bán giá rẻ — đó là lý do."},{"no":54,"options":["ランチではあったか","ランチなのである","ランチなのではないだろう","ランチではないのではないか"],"answer":1,"grammar":"Nなのである","grammar_vi":"Chính là ~ (nhấn mạnh, khẳng định)","sentence":"[飲食店](いんしょくてん)にとって、[利益](りえき)が[上](あ)げられ、さらに[客](きゃく)も[獲得](かくとく)できるランチは、「おいしい」**ランチなのである**。","sentence_vi":"Đối với nhà hàng, bữa trưa vừa tạo ra lợi nhuận vừa thu hút thêm khách chính là bữa trưa \\"hấp dẫn\\"."}],"translation_vi":"Nhiều nhà hàng không chỉ mở cửa buổi tối mà cả buổi trưa và phục vụ thực đơn bữa trưa. Thực đơn bữa trưa này thường được định giá hợp lý hơn so với buổi tối. Ví dụ, có quán buổi tối riêng món mì Ý đã khoảng 1.200 yên nhưng buổi trưa mì Ý kèm súp và salad chỉ 980 yên, hay quán buổi tối món set từ 5.000 yên trở lên nhưng buổi trưa chỉ khoảng 1.000 yên.\\n\\nSự chênh lệch giá giữa trưa và tối này rốt cuộc là do đâu? Dù rẻ nhưng tất nhiên không có chuyện đầu bếp làm ẩu hay dùng nguyên liệu rẻ tiền. Vì nếu chất lượng giảm sẽ có tiếng xấu và ảnh hưởng xấu đến cả việc kinh doanh buổi tối.\\n\\nLý do có thể bán thực đơn bữa trưa rẻ rất đơn giản. Không chỉ nhà hàng, để kinh doanh một cửa hàng cần nhiều chi phí như nguyên liệu, điện nước, lương nhân viên, nhưng nếu giảm được chi phí thì dù hạ giá sản phẩm vẫn có thể có lãi. Trong trường hợp bữa trưa, nhiều quán giảm chi phí bằng cách thu hẹp thực đơn chỉ còn vài món. Nếu thực đơn ít, việc chuẩn bị và nấu nướng không tốn thời gian, cũng không cần nhiều đầu bếp. Vì vậy, họ có thể bán giá rẻ.\\n\\nNhờ giảm chi phí, nhà hàng vẫn có lãi dù bán thực đơn bữa trưa rẻ. Ngoài ra, khách đã ăn bữa trưa rẻ mà ngon sẽ thích quán và có khả năng quay lại cả buổi tối. Đối với nhà hàng, bữa trưa vừa tạo ra lợi nhuận vừa thu hút thêm khách chính là bữa trưa \\"hấp dẫn\\".","title":"ランチメニューはなぜ[安](やす)い？"},{"paragraphs":["[冬](ふゆ)の[寒](さむ)さも[緩](ゆる)み、[春](はる)の[陽気](ようき)が[感](かん)じられるようになってきました。[春](はる)は[花](はな)の[季節](きせつ)。サクラをはじめ、ウメやモモなど[多](おお)くの[木々](きぎ)が[花](はな)を[咲](さ)かせます。","ところで、これらの[花](はな)は、なぜ[春](はる)に[一斉](いっせい)に[咲](さ)くのでしょう。[花](はな)なんて[暖](あたた)かくなれば[咲](さ)くものだと（50）。[確](たし)かに、[気温](きおん)の[上昇](じょうしょう)も[重要](じゅうよう)です。ただ、[皆](みな)さんは、[春](はる)に[花](はな)を[咲](さ)かせる[木](き)がいつその[準備](じゅんび)をしているかご[存](ぞん)じですか。（51）、[開花](かいか)する[前](まえ)の[年](とし)の[夏](なつ)には、すでに[花](はな)となる[芽](め)（[花芽](かが)）が[作](つく)られ、[花](はな)を[咲](さ)かせる[準備](じゅんび)ができているのです。そう[考](かんが)えると、[春](はる)まで[待](ま)って[一斉](いっせい)に[咲](さ)くというのは[不思議](ふしぎ)ではありませんか。[一体](いったい)どういう[仕組](しく)みなのでしょう。","サクラやウメなどの[木](き)は[夏](なつ)に、[成長](せいちょう)を[抑](おさ)える[休眠](きゅうみん)[物質](ぶっしつ)を[葉](は)で[作](つく)ります。それが[花芽](かが)にたまると、[葉](は)が[落](お)ち、[花芽](かが)は「[休眠](きゅうみん)」という[期間](きかん)に[入](はい)ります。（52）[花芽](かが)は[成長](せいちょう)しません。[休眠](きゅうみん)から[目覚](めざ)めるには、[一定](いってい)の[低温](ていおん)[期間](きかん)を[経験](けいけん)することが[必要](ひつよう)です。「[一定](いってい)の[低温](ていおん)[期間](きかん)」とはどれくらいかというと、それは[花](はな)によって[違](ちが)うことがわかっています。","[例](たと)えば、サクラのソメイヨシノでは、5[度](ど)[前後](ぜんご)の[気温](きおん)が[約](やく)900[時間](じかん)（53）。そして[休眠](きゅうみん)から[目覚](めざ)めると、[成長](せいちょう)を[抑](おさ)えていた[休眠](きゅうみん)[物質](ぶっしつ)が[減](へ)り[始](はじ)めます。それがなくなると[成長](せいちょう)が[再開](さいかい)し、[春](はる)になって、[1日](ついたち)の[平均](へいきん)[気温](きおん)が12〜13[度](ど)になると[開花](かいか)するのです。","[春](はる)に[一斉](いっせい)に[咲](さ)く[花](はな)の[仕組](しく)み、（54）。[冬](ふゆ)の[間](ま)、[私](わたし)たちは[寒](さむ)さが[去](さ)るのを[待](ま)つばかりですが、[春](はる)に[咲](さ)く[花](はな)のためには、その[寒](さむ)さは[必要](ひつよう)なものなのです。"],"questions":[{"no":50,"options":["[思](おも)うせいです","[思](おも)うかもしれません","[思](おも)うほどです","[思](おも)うことにしました"],"answer":1,"grammar":"Thể thường+かもしれない","grammar_vi":"Có lẽ ~, biết đâu ~","sentence":"[花](はな)なんて[暖](あたた)かくなれば[咲](さ)くものだと**[思](おも)うかもしれません**。","sentence_vi":"Có thể bạn nghĩ rằng hoa thì cứ ấm lên là nở."},{"no":51,"options":["また","こうして","[実](じつ)は","[一方](いっぽう)"],"answer":2,"grammar":"実は","grammar_vi":"Thực ra là, sự thật là","sentence":"**[実](じつ)は**、[開花](かいか)する[前](まえ)の[年](とし)の[夏](なつ)には、すでに[花](はな)となる[芽](め)（[花芽](かが)）が[作](つく)られ、[花](はな)を[咲](さ)かせる[準備](じゅんび)ができているのです。","sentence_vi":"Thực ra, vào mùa hè của năm trước khi nở, mầm sẽ thành hoa (hoa nha) đã được hình thành và sẵn sàng nở hoa."},{"no":52,"options":["この[期間](きかん)は","あの[期間](きかん)では","これくらいの[期間](きかん)では","あれくらいの[期間](きかん)は"],"answer":0,"grammar":"この+N(chỉ thị)","grammar_vi":"N này (chỉ điều đang nói đến)","sentence":"**この[期間](きかん)は**[花芽](かが)は[成長](せいちょう)しません。","sentence_vi":"Trong giai đoạn này, mầm hoa không phát triển."},{"no":53,"options":["[必要](ひつよう)かどうか[調査](ちょうさ)されます","[必要](ひつよう)かどうか[明](あき)らかになります","[必要](ひつよう)だとされています","[必要](ひつよう)だと[気](き)づかされます"],"answer":2,"grammar":"~とされている","grammar_vi":"Được cho là ~, được coi là ~","sentence":"[例](たと)えば、サクラのソメイヨシノでは、5[度](ど)[前後](ぜんご)の[気温](きおん)が[約](やく)900[時間](じかん)**[必要](ひつよう)だとされています**。","sentence_vi":"Ví dụ, với hoa anh đào Somei Yoshino, người ta cho rằng cần khoảng 900 giờ ở nhiệt độ quanh 5 độ."},{"no":54,"options":["ご[存](ぞん)じでしょうか","ご[存](ぞん)じだったのですね","おわかりいただけるのですね","おわかりいただけましたか"],"answer":3,"grammar":"お+V_ます_+いただけましたか","grammar_vi":"Quý vị đã ~ được chưa ạ? (kính ngữ, hỏi lại)","sentence":"[春](はる)に[一斉](いっせい)に[咲](さ)く[花](はな)の[仕組](しく)み、**おわかりいただけましたか**。","sentence_vi":"Quý vị đã hiểu cơ chế các loài hoa nở đồng loạt vào mùa xuân chưa ạ?"}],"translation_vi":"Cái lạnh mùa đông đã dịu bớt, có thể cảm nhận không khí ấm áp của mùa xuân. Mùa xuân là mùa hoa. Nhiều loài cây như anh đào, mơ, đào nở hoa.\\n\\nNhưng tại sao những loài hoa này lại nở đồng loạt vào mùa xuân? Có thể bạn nghĩ rằng hoa thì cứ ấm lên là nở. Đúng là nhiệt độ tăng cũng quan trọng. Nhưng bạn có biết những cây nở hoa vào mùa xuân đã chuẩn bị từ khi nào không? Thực ra, vào mùa hè của năm trước khi nở, mầm sẽ thành hoa (hoa nha) đã được hình thành và sẵn sàng nở hoa. Nghĩ như vậy, việc chờ đến mùa xuân rồi nở đồng loạt chẳng phải rất kỳ lạ sao? Rốt cuộc cơ chế đó là gì?\\n\\nCác cây như anh đào, mơ vào mùa hè tạo ra ở lá chất ngủ đông ức chế sự phát triển. Khi chất đó tích tụ ở mầm hoa, lá rụng và mầm hoa bước vào giai đoạn gọi là \\"ngủ đông\\". Trong giai đoạn này, mầm hoa không phát triển. Để thức dậy từ giấc ngủ đông, cần trải qua một thời gian lạnh nhất định. Người ta biết rằng \\"thời gian lạnh nhất định\\" dài bao lâu thì tùy theo từng loài hoa.\\n\\nVí dụ, với hoa anh đào Somei Yoshino, người ta cho rằng cần khoảng 900 giờ ở nhiệt độ quanh 5 độ. Và khi tỉnh khỏi giấc ngủ đông, chất ngủ đông đang ức chế sự phát triển bắt đầu giảm. Khi nó hết, sự phát triển tiếp tục, và vào mùa xuân, khi nhiệt độ trung bình ngày đạt 12–13 độ thì hoa nở.\\n\\nQuý vị đã hiểu cơ chế các loài hoa nở đồng loạt vào mùa xuân chưa ạ? Suốt mùa đông, chúng ta chỉ biết chờ cái lạnh qua đi, nhưng đối với những loài hoa nở vào mùa xuân, cái lạnh đó là điều cần thiết.","title":"サクラが[春](はる)に[咲](さ)く[不思議](ふしぎ)"},{"paragraphs":["[日本](にほん)[食](しょく)というと[米](べい)の[印象](いんしょう)が[強](つよ)く、[私](わたし)は、[日本人](にほんじん)は[米](こめ)を[一日](いちにち)[三](さん)[食](しょく)[食](た)べていると[思](おも)っていた。ところが[日本](にほん)に[来](き)てみると、（50）ので[驚](おどろ)いた。","ある[調査](ちょうさ)によると、1960[年](ねん)の[日本](にほん)の[米](べい)の[消費](しょうひ)[量](りょう)は[一人](ひとり)[当](あ)たり[年間](ねんかん)[約](やく)120キロだったが、2010[年](ねん)は[約](やく)60キロだったという。この50[年](ねん)で[米](べい)の[消費](しょうひ)[量](りょう)が[半減](はんげん)したわけだ。けれども、50[年](ねん)で[一日](いちにち)の[食事](しょくじ)の[回数](かいすう)や[総量](そうりょう)が[半減](はんげん)する（51）。では、どのような[事情](じじょう)で[米](べい)の[消費](しょうひ)[量](りょう)が[半減](はんげん)したのか。","それにはいくつか（52）があるようだ。その[中](なか)で[私](わたし)が[取](と)り[上](あ)げたいのは、[食](しょく)の[多様](たよう)[化](か)だ。1965[年](ねん)ごろから[日本](にほん)では[様々](さまざま)な[食物](しょくもつ)を[輸入](ゆにゅう)するようになり、[米](べい)[以外](いがい)にパンなどを[主食](しゅしょく)としてよく[食](た)べるようになった。また、1960[年](ねん)から2010[年](ねん)の50[年](ねん)で、[肉](にく)の[消費](しょうひ)[量](りょう)は[約](やく)5[倍](ばい)に、[乳製品](にゅうせいひん)は[約](やく)4[倍](ばい)に[増](ふ)えた。こうした[変化](へんか)の[中](なか)で、[相対](そうたい)[的](てき)に[米](こめ)の[消費](しょうひ)[量](りょう)が[減少](げんしょう)したのだろう。","[食](しょく)の[多様](たよう)[化](か)[自体](じたい)は、[食卓](しょくたく)が[豊](ゆた)かになるのだし[悪](わる)いことではない。（53）、[食](しょく)の[多様](たよう)[化](か)に[伴](ともな)う[問題](もんだい)も[起](お)きているようだ。[日本](にほん)では[昔](むかし)から[米](べい)や[野菜](やさい)がよく[食](た)べられてきたため、[日本人](にほんじん)の[体](からだ)はそれらの[消化](しょうか)に[適](てき)しており、[肉](にく)や[乳製品](にゅうせいひん)の[消化](しょうか)が[苦手](にがて)だという。[食](しょく)の[変化](へんか)によって[病気](びょうき)になる[人](ひと)も[増](ふ)えているそうだ。[日本人](にほんじん)が[守](まも)ってきた[伝統](でんとう)[的](てき)な[食](しょく)[文化](ぶんか)は、[日本人](にほんじん)の[健康](けんこう)を[支](ささ)えていたのだ。","[私](わたし)の[国](くに)の[食](しょく)[文化](ぶんか)も[私](わたし)たちの[健康](けんこう)を[支](ささ)えてくれていたのだろうか。[日本](にほん)に[来](き)て、その[土地](とち)に[生](い)きる[人](ひと)と[食](しょく)[文化](ぶんか)とのつながりについて（54）。"],"questions":[{"no":50,"options":["これではなかった","それではなかった","そうではなかった","こうでもなかった"],"answer":2,"grammar":"そうではない","grammar_vi":"Không phải như vậy (そう chỉ điều đã nêu ở trước)","sentence":"ところが[日本](にほん)に[来](き)てみると、**そうではなかった**ので[驚](おどろ)いた。","sentence_vi":"Thế nhưng khi đến Nhật, tôi ngạc nhiên vì không phải như vậy."},{"no":51,"options":["とは[思](おも)えない","としか[思](おも)えない","とも[思](おも)われる","とさえ[思](おも)う"],"answer":0,"grammar":"Thể thường+とは思えない","grammar_vi":"Không thể nghĩ rằng ~","sentence":"けれども、50[年](ねん)で[一日](いちにち)の[食事](しょくじ)の[回数](かいすう)や[総量](そうりょう)が[半減](はんげん)する**とは[思](おも)えない**。","sentence_vi":"Tuy nhiên, tôi không nghĩ rằng trong 50 năm số bữa ăn một ngày hay tổng lượng ăn lại giảm đi một nửa."},{"no":52,"options":["[条件](じょうけん)","[証拠](しょうこ)","[基礎](きそ)","[理由](りゆう)"],"answer":3,"grammar":"いくつか","grammar_vi":"Vài ~, một vài ~","sentence":"それにはいくつか**[理由](りゆう)**があるようだ。","sentence_vi":"Có vẻ có vài lý do cho việc đó."},{"no":53,"options":["[理由](りゆう)","そのうえ","だが","そこで"],"answer":2,"grammar":"だが","grammar_vi":"Nhưng, tuy nhiên (nối hai câu đối lập)","sentence":"**だが**、[食](しょく)の[多様](たよう)[化](か)に[伴](ともな)う[問題](もんだい)も[起](お)きているようだ。","sentence_vi":"Tuy nhiên, dường như cũng đang xảy ra những vấn đề đi kèm với sự đa dạng hóa ăn uống."},{"no":54,"options":["[考](かんが)えたのだろう","[考](かんが)えさせられた","[考](かんが)えさせていたのだろう","[考](かんが)えられていた"],"answer":1,"grammar":"Vさせられる(nhận ra)","grammar_vi":"Bị khiến cho (nhận ra, cảm thấy) ~","sentence":"[日本](にほん)に[来](き)て、その[土地](とち)に[生](い)きる[人](ひと)と[食](しょく)[文化](ぶんか)とのつながりについて**[考](かんが)えさせられた**。","sentence_vi":"Đến Nhật, tôi đã được khiến phải suy nghĩ về mối liên hệ giữa con người sống ở vùng đất đó và văn hóa ẩm thực."}],"translation_vi":"Nhắc đến món ăn Nhật là ấn tượng về gạo rất mạnh, và tôi đã nghĩ người Nhật ăn gạo ba bữa một ngày. Thế nhưng khi đến Nhật, tôi ngạc nhiên vì không phải như vậy.\\n\\nTheo một cuộc khảo sát, lượng gạo tiêu thụ của Nhật năm 1960 là khoảng 120 kg mỗi người mỗi năm, nhưng năm 2010 là khoảng 60 kg. Tức là trong 50 năm lượng gạo tiêu thụ đã giảm một nửa. Tuy nhiên, tôi không nghĩ rằng trong 50 năm số bữa ăn một ngày hay tổng lượng ăn lại giảm đi một nửa. Vậy lượng gạo tiêu thụ giảm một nửa là do hoàn cảnh nào?\\n\\nCó vẻ có vài lý do cho việc đó. Trong số đó, điều tôi muốn nêu là sự đa dạng hóa trong ăn uống. Từ khoảng năm 1965, Nhật bắt đầu nhập khẩu nhiều loại thực phẩm, và ngoài gạo, bánh mì cũng được ăn thường xuyên như món chính. Ngoài ra, trong 50 năm từ 1960 đến 2010, lượng thịt tiêu thụ tăng khoảng 5 lần, sản phẩm từ sữa tăng khoảng 4 lần. Trong những thay đổi đó, có lẽ lượng gạo tiêu thụ giảm một cách tương đối.\\n\\nBản thân sự đa dạng hóa ăn uống làm bàn ăn phong phú hơn nên không phải điều xấu. Tuy nhiên, dường như cũng đang xảy ra những vấn đề đi kèm với sự đa dạng hóa ăn uống. Ở Nhật từ xưa gạo và rau được ăn nhiều, nên cơ thể người Nhật phù hợp với việc tiêu hóa chúng và kém tiêu hóa thịt, sản phẩm từ sữa. Nghe nói số người mắc bệnh vì thay đổi ăn uống cũng tăng. Văn hóa ẩm thực truyền thống mà người Nhật gìn giữ đã nâng đỡ sức khỏe của họ.\\n\\nVăn hóa ẩm thực ở đất nước tôi có phải cũng đã nâng đỡ sức khỏe của chúng tôi không? Đến Nhật, tôi đã được khiến phải suy nghĩ về mối liên hệ giữa con người sống ở vùng đất đó và văn hóa ẩm thực.","title":"[日本](にほん)における[米食](べいしょく)の[変化](へんか)"},{"paragraphs":["[今日](きょう)も[新宿](しんじゅく)[駅前](えきまえ)でティッシュをもらった。[小](ちい)さな[袋](ふくろ)の[中](なか)に10[枚](まい)ほどのティッシュが[入](はい)っていて、ポケットなどに[入](い)れて[持](も)ち[歩](ある)けるポケットティッシュだ。[新宿](しんじゅく)や[渋谷](しぶや)などの[大](おお)きな[駅](えき)を[出](で)て[少](すこ)し[歩](ある)くと、ポケットティッシュを[配](くば)っている[人](ひと)にあちこちで（50）。[彼](かれ)らが[配](くば)るのは、ティッシュでもあり[広告](こうこく)でもある。[受](う)け[取](と)ったティッシュの[袋](ふくろ)には、[旅行](りょこう)[会社](かいしゃ)の[名前](なまえ)が[印刷](いんさつ)されていたり、[美容院](びよういん)や[居酒屋](いざかや)の[広告](こうこく)の[紙](かみ)が[入](はい)っていたりする。[最初](さいしょ)は[無料](むりょう)で[配](くば)っているとは[知](し)らなかったので、[渡](わた)されたときは[驚](おどろ)いた。","ティッシュペーパーが[日本](にほん)で[使](つか)われるようになったのは、1950[年代](ねんだい)。その[十](じゅう)[数](すう)[年](ねん)[後](ご)、（51）が[広告](こうこく)[宣伝](せんでん)[用](よう)に[配](くば)るためのポケットティッシュを[開発](かいはつ)した。そして、1970[年](ねん)ごろにそれを[道](みち)で[配](くば)り[始](はじ)めた[会社](かいしゃ)があり、それ[以来](いらい)、ポケットティッシュを[道](みち)で[配](くば)ることが[定着](ていちゃく)していったらしい。[確](たし)かに、ポケットティッシュは[優](すぐ)れた[宣伝](せんでん)グッズだ。まず、[道](みち)で[直接](ちょくせつ)[配](くば)るから、[歩](ある)いている[人](ひと)の[性別](せいべつ)・[年齢](ねんれい)を[見](み)て、[渡](わた)すことができる。[個人](こじん)[情報](じょうほう)を[集](あつ)めなくても、[宣伝](せんでん)したい[相手](あいて)に[宣伝](せんでん)できる[効果](こうか)[的](てき)な（52）。また、ティッシュなら[実用](じつよう)[的](てき)で、ちらしだけよりも[受](う)け[取](と)ってもらいやすいし、[使](つか)うたびに[広告](こうこく)を[見](み)てもらえるという[利点](りてん)もある。（53）、[私](わたし)はポケットティッシュの[広告](こうこく)を[見](み)て[行動](こうどう)を[起](お)こしたことはない。もらう[広告](こうこく)には[全](まった)く[興味](きょうみ)がないが、[無料](むりょう)だからついもらってしまい、たまっていく[一方](いっぽう)だ。だから、[帰国](きこく)したらこの[宣伝](せんでん)[方法](ほうほう)を[友達](ともだち)に（54）。"],"questions":[{"no":50,"options":["[出会](であ)う","[出合](であ)ったのか","[出会](であ)うこともあった","[出会](であ)うはずだった"],"answer":0,"grammar":"Vる(tình huống thường xảy ra)","grammar_vi":"Thể hiện tại: nói điều thường xảy ra khi ~","sentence":"[新宿](しんじゅく)や[渋谷](しぶや)などの[大](おお)きな[駅](えき)を[出](で)て[少](すこ)し[歩](ある)くと、ポケットティッシュを[配](くば)っている[人](ひと)にあちこちで**[出会](であ)う**。","sentence_vi":"Ra khỏi những ga lớn như Shinjuku, Shibuya và đi bộ một chút, chỗ nào cũng bắt gặp người đang phát khăn giấy bỏ túi."},{"no":51,"options":["その[会社](かいしゃ)","ある[会社](かいしゃ)","[彼](かれ)らの[会社](かいしゃ)","こういう[会社](かいしゃ)"],"answer":1,"grammar":"ある+N","grammar_vi":"Một N nào đó (không nói rõ cụ thể)","sentence":"その[十](じゅう)[数](すう)[年](ねん)[後](ご)、**ある[会社](かいしゃ)**が[広告](こうこく)[宣伝](せんでん)[用](よう)に[配](くば)るためのポケットティッシュを[開発](かいはつ)した。","sentence_vi":"Hơn chục năm sau đó, một công ty nào đó đã phát triển khăn giấy bỏ túi để phát làm quảng cáo."},{"no":52,"options":["[方法](ほうほう)にするべきだ","[方法](ほうほう)だと[言](い)える","[方法](ほうほう)になりかねない","[方法](ほうほう)があるに[違](ちが)いない"],"answer":1,"grammar":"~と言える","grammar_vi":"Có thể nói là ~","sentence":"[個人](こじん)[情報](じょうほう)を[集](あつ)めなくても、[宣伝](せんでん)したい[相手](あいて)に[宣伝](せんでん)できる[効果](こうか)[的](てき)な**[方法](ほうほう)だと[言](い)える**。","sentence_vi":"Có thể nói đây là phương pháp hiệu quả, không cần thu thập thông tin cá nhân vẫn quảng cáo được cho đối tượng muốn quảng cáo."},{"no":53,"options":["むしろ","[要](よう)するに","したがって","とはいえ"],"answer":3,"grammar":"とはいえ(liên từ)","grammar_vi":"Tuy nói vậy, dù vậy (nối câu đối lập)","sentence":"**とはいえ**、[私](わたし)はポケットティッシュの[広告](こうこく)を[見](み)て[行動](こうどう)を[起](お)こしたことはない。","sentence_vi":"Tuy vậy, tôi chưa bao giờ hành động sau khi xem quảng cáo trên khăn giấy bỏ túi."},{"no":54,"options":["[紹介](しょうかい)されたわけだ","[紹介](しょうかい)したからだ","[紹介](しょうかい)しようと[思](おも)う","[紹介](しょうかい)されたのだと[思](おも)う"],"answer":2,"grammar":"Vよう+と思う","grammar_vi":"Định ~, nghĩ là sẽ ~","sentence":"だから、[帰国](きこく)したらこの[宣伝](せんでん)[方法](ほうほう)を[友達](ともだち)に**[紹介](しょうかい)しようと[思](おも)う**。","sentence_vi":"Vì vậy, khi về nước tôi định giới thiệu cách quảng cáo này cho bạn bè."}],"translation_vi":"Hôm nay tôi lại nhận khăn giấy trước ga Shinjuku. Trong túi nhỏ có khoảng 10 tờ khăn giấy, là loại khăn giấy bỏ túi mang theo trong túi áo. Ra khỏi những ga lớn như Shinjuku, Shibuya và đi bộ một chút, chỗ nào cũng bắt gặp người đang phát khăn giấy bỏ túi. Thứ họ phát vừa là khăn giấy vừa là quảng cáo. Trên túi khăn giấy nhận được có in tên công ty du lịch, hoặc có tờ quảng cáo của tiệm làm tóc, quán nhậu bên trong. Lúc đầu tôi không biết họ phát miễn phí nên khi được đưa tôi rất ngạc nhiên.\\n\\nGiấy khăn bắt đầu được dùng ở Nhật vào thập niên 1950. Hơn chục năm sau đó, một công ty nào đó đã phát triển khăn giấy bỏ túi để phát làm quảng cáo. Rồi vào khoảng năm 1970 có công ty bắt đầu phát nó trên đường, và từ đó việc phát khăn giấy bỏ túi trên đường trở thành thông lệ. Quả thật, khăn giấy bỏ túi là món quảng cáo tuyệt vời. Trước hết, vì phát trực tiếp ngoài đường nên có thể nhìn giới tính, độ tuổi của người đi đường rồi mới đưa. Có thể nói đây là phương pháp hiệu quả, không cần thu thập thông tin cá nhân vẫn quảng cáo được cho đối tượng muốn quảng cáo. Ngoài ra, nếu là khăn giấy thì thiết thực, dễ được nhận hơn chỉ phát tờ rơi, và còn có lợi thế là mỗi lần dùng lại được xem quảng cáo. Tuy vậy, tôi chưa bao giờ hành động sau khi xem quảng cáo trên khăn giấy bỏ túi. Tôi hoàn toàn không hứng thú với quảng cáo nhận được, nhưng vì miễn phí nên lỡ nhận, và chúng cứ chất đống. Vì vậy, khi về nước tôi định giới thiệu cách quảng cáo này cho bạn bè.","title":"ポケットティッシュ"},{"paragraphs":["[質問](しつもん)：[田舎](いなか)にキャンプに[行](い)ったとき、[夜空](よぞら)には[無数](むすう)の[星](ほし)があり、[本当](ほんとう)にきれいでした。[毎晩](まいばん)あんな[空](そら)が[見](み)たいと[思](おも)っても、[私](わたし)の[街](まち)では[月](つき)しか[見](み)えません。[都会](とかい)で[星](ほし)は[見](み)られないのでしょうか。（[東京](とうきょう)・14[歳](さい)[女子](じょし)）","[回答](かいとう)：[都会](とかい)で[星](ほし)が[見](み)えないのは、[夜](よる)の[街](まち)の[照明](しょうめい)が[空気](くうき)[中](ちゅう)のちりなどに[当](あ)たって[起](お)こる「[光害](こうがい)」という[公害](こうがい)によるものです。「『[光害](こうがい)』と[言](い)われても、[夜](よる)は[照明](しょうめい)なしで[生活](せいかつ)できないから、[都会](とかい)で[星](ほし)を[見](み)るのはあきらめよう」とあなたは（50）。しかし、あきらめる[前](まえ)に[少](すこ)し[考](かんが)えてみてください。[照明](しょうめい)の[登場](とうじょう)で[夜](よる)も[明](あか)るくなり、[人々](ひとびと)の[生活](せいかつ)は[安全](あんぜん)で[便利](べんり)になりましたが、[都会](とかい)の[夜](よる)の[明](あか)るさは[必要](ひつよう)[以上](いじょう)だと[思](おも)いませんか。また、（51）を[受](う)けているのは[人間](にんげん)だけです。[昼](ひる)は[明](あか)るく、[夜](よる)は[暗](くら)いという[自然](しぜん)のリズムがくずれ、[植物](しょくぶつ)や[動物](どうぶつ)に[大](おお)きな[影響](えいきょう)を[与](あた)えています。","[夜](よる)、[照明](しょうめい)を[使](つか)わなければ、[光害](こうがい)はなくなります。（52）、[東京](とうきょう)のような[大](だい)[都会](とかい)で[夜](よる)にまったく[照明](しょうめい)を[使](つか)わずに[生活](せいかつ)するのは[現実](げんじつ)[的](てき)に[不可能](ふかのう)です。そこで、[照明](しょうめい)を[目的](もくてき)に[合](あ)わせて[適切](てきせつ)に[使](つか)うことが、[光害](こうがい)[対策](たいさく)として[重要](じゅうよう)になります。すでに[現在](げんざい)、[環境省](かんきょうしょう)が[定](さだ)めた[光害](こうがい)[対策](たいさく)の[方針](ほうしん)の[下](した)、[道](みち)を[照](て)らすなら[上](うえ)[方向](ほうこう)に[光](ひかり)がもれないようにするなどの[取](と)り[組](く)みが（53）。[私](わたし)たちも[不要](ふよう)な[照明](しょうめい)はすぐに[消](け)すなど、[常](つね)に[適切](てきせつ)な[量](りょう)の[光](ひかり)を[使](つか)おうと[意識](いしき)して[行動](こうどう)していく[必要](ひつよう)があります。[時間](じかん)はかかるかもしれませんが、あなたの[街](まち)でもキャンプの[夜](よる)に[見](み)たような[星](ほし)が[見](み)られるように（54）。"],"questions":[{"no":50,"options":["[思](おも)うかもしれません","[思](おも)ってはいけません","[思](おも)わねばなりません","[思](おも)わなくてもいいです"],"answer":0,"grammar":"Thể thường+かもしれない","grammar_vi":"Có lẽ ~, biết đâu ~","sentence":"「『[光害](こうがい)』と[言](い)われても、[夜](よる)は[照明](しょうめい)なしで[生活](せいかつ)できないから、[都会](とかい)で[星](ほし)を[見](み)るのはあきらめよう」とあなたは**[思](おも)うかもしれません**。","sentence_vi":"Có thể bạn nghĩ: \\"Dù nghe nói là 'ô nhiễm ánh sáng', nhưng ban đêm không thể sống mà không có đèn, nên thôi bỏ ý định ngắm sao ở thành phố\\"."},{"no":51,"options":["どちらも[影響](えいきょう)","あのような[害](がい)","こちらの[照明](しょうめい)","その[恩恵](おんけい)"],"answer":3,"grammar":"その+N(chỉ thị)","grammar_vi":"N đó, N ấy (chỉ điều đã nhắc ở trước; nhắc lần đầu thì dùng N trần)","sentence":"また、**その[恩恵](おんけい)**を[受](う)けているのは[人間](にんげん)だけです。","sentence_vi":"Ngoài ra, chỉ có con người là được hưởng lợi ích đó."},{"no":52,"options":["つまり","とはいえ","ところで","しかも"],"answer":1,"grammar":"とはいえ(liên từ)","grammar_vi":"Tuy nói vậy, dù vậy (nối câu đối lập)","sentence":"**とはいえ**、[東京](とうきょう)のような[大](だい)[都会](とかい)で[夜](よる)にまったく[照明](しょうめい)を[使](つか)わずに[生活](せいかつ)するのは[現実](げんじつ)[的](てき)に[不可能](ふかのう)です。","sentence_vi":"Tuy nhiên, thực tế không thể sống mà không dùng đèn vào ban đêm ở một đô thị lớn như Tokyo."},{"no":53,"options":["[行](おこな)われるためです","[行](おこな)われています","[行](おこな)われるという[点](てん)です","[行](おこな)われているとします"],"answer":1,"grammar":"Vられている","grammar_vi":"Đang được ~, vẫn được ~ (bị động)","sentence":"すでに[現在](げんざい)、[環境省](かんきょうしょう)が[定](さだ)めた[光害](こうがい)[対策](たいさく)の[方針](ほうしん)の[下](した)、[道](みち)を[照](て)らすなら[上](うえ)[方向](ほうこう)に[光](ひかり)がもれないようにするなどの[取](と)り[組](く)みが**[行](おこな)われています**。","sentence_vi":"Hiện nay đã có những nỗ lực như theo phương châm đối phó ô nhiễm ánh sáng do Bộ Môi trường quy định, nếu chiếu sáng đường thì làm sao cho ánh sáng không rò lên phía trên."},{"no":54,"options":["なると[言](い)えるでしょうか","なっているとよかったのです","なるといいですね","なってほしかったのでしょう"],"answer":2,"grammar":"Vる+といい","grammar_vi":"Mong là ~, ~ thì tốt","sentence":"[時間](じかん)はかかるかもしれませんが、あなたの[街](まち)でもキャンプの[夜](よる)に[見](み)たような[星](ほし)が[見](み)られるように**なるといいですね**。","sentence_vi":"Có thể sẽ mất thời gian, nhưng mong là ở thành phố của bạn cũng có thể thấy những vì sao như đã thấy trong đêm cắm trại."}],"translation_vi":"Câu hỏi: Khi đi cắm trại ở vùng quê, bầu trời đêm có vô số vì sao, thật sự rất đẹp. Dù tôi muốn đêm nào cũng được ngắm bầu trời như thế, nhưng ở thành phố của tôi chỉ thấy mặt trăng. Ở thành phố không thể ngắm sao được sao? (Tokyo, nữ 14 tuổi)\\n\\nTrả lời: Việc không thấy sao ở thành phố là do một loại ô nhiễm gọi là \\"ô nhiễm ánh sáng\\", xảy ra khi ánh đèn chiếu sáng thành phố ban đêm chạm vào bụi trong không khí. Có thể bạn nghĩ: \\"Dù nghe nói là 'ô nhiễm ánh sáng', nhưng ban đêm không thể sống mà không có đèn, nên thôi bỏ ý định ngắm sao ở thành phố\\". Nhưng trước khi bỏ cuộc, hãy suy nghĩ một chút. Nhờ có đèn chiếu sáng, đêm cũng sáng, cuộc sống của con người trở nên an toàn và tiện lợi hơn, nhưng bạn có thấy độ sáng ban đêm của thành phố là quá mức cần thiết không? Ngoài ra, chỉ có con người là được hưởng lợi ích đó. Nhịp điệu tự nhiên là ban ngày sáng, ban đêm tối bị phá vỡ, gây ảnh hưởng lớn đến thực vật và động vật.\\n\\nNếu ban đêm không dùng đèn thì ô nhiễm ánh sáng sẽ hết. Tuy nhiên, thực tế không thể sống mà không dùng đèn vào ban đêm ở một đô thị lớn như Tokyo. Vì vậy, điều quan trọng để đối phó với ô nhiễm ánh sáng là dùng đèn phù hợp với mục đích. Hiện nay đã có những nỗ lực như theo phương châm đối phó ô nhiễm ánh sáng do Bộ Môi trường quy định, nếu chiếu sáng đường thì làm sao cho ánh sáng không rò lên phía trên. Chúng ta cũng cần hành động với ý thức luôn dùng lượng ánh sáng phù hợp, chẳng hạn tắt ngay những đèn không cần thiết. Có thể sẽ mất thời gian, nhưng mong là ở thành phố của bạn cũng có thể thấy những vì sao như đã thấy trong đêm cắm trại."},{"paragraphs":["[商品](しょうひん)[名](めい)や[商品](しょうひん)の[説明](せつめい)などで「[大人](おとな)の[旅](たび)」「[大人](おとな)のパスタ」「[大人](おとな)のピアノ[教室](きょうしつ)」といった[表現](ひょうげん)をよく[目](め)にする。「[大人](おとな)」とあるが、[成人](せいじん)[用](よう)ではなく[年齢](ねんれい)[制限](せいげん)はない。とすると、こうした[表現](ひょうげん)で[使](つか)われている「[大人](おとな)」とは（50）を[指](さ)しているのだろうか。[気](き)になって[調](しら)べてみた。","ある[旅行](りょこう)[会社](かいしゃ)は、「[大人](おとな)の[旅](たび)」を[企画](きかく)している。これは、[高級](こうきゅう)な[旅館](りょかん)に[泊](と)まったり、[時間](じかん)をかけて[旅行](りょこう)したり（51）。[私](わたし)はずっと、[旅行](りょこう)[会社](かいしゃ)が[企画](きかく)するのは[低](てい)[価格](かかく)で[短時間](たんじかん)に[多](おお)くの[観光](かんこう)[地](ち)に[行](い)く[忙](いそが)しい[旅行](りょこう)というイメージを[持](も)っていたが、「[大人](おとな)の[旅](たび)」は[違](ちが)っていた。","また、[先日](せんじつ)[読](よ)んだ[記事](きじ)によると、「[大人](おとな)のパスタ」というのは、[素材](そざい)にこだわった[商品](しょうひん)らしい。[価値](かち)があれば[価格](かかく)はあまり[気](き)にしないという[人](ひと)を[対象](たいしょう)として[開発](かいはつ)された。だから、[良](よ)い[素材](そざい)を[使](つか)うことによって[多少](たしょう)[価格](かかく)が[高](たか)くなっても（52）。","[駅](えき)にはられていた「[大人](おとな)のピアノ[教室](きょうしつ)」のポスターで[募集](ぼしゅう)していた[生徒](せいと)は、[昔](むかし)[習](なら)っていたピアノをまた[習](なら)いたいという[人](ひと)や、[仕事](しごと)や[家事](かじ)[以外](いがい)に[何](なに)か[趣味](しゅみ)を[見](み)つけたいという[人](ひと)だった。（53）、[経済](けいざい)[的](てき)、[時間](じかん)[的](てき)、[精神](せいしん)[的](てき)に[余裕](よゆう)がある[人](ひと)が「[大人](おとな)」なのだろう。[私](わたし)は、[旅行](りょこう)はお[金](かね)をかけないで[行](い)きたいし、[食事](しょくじ)は[質](しつ)より[量](りょう)だ。[勉強](べんきょう)とアルバイトで[精](せい)いっぱいだから、[何](なに)かを[習](なら)う[余裕](よゆう)もない。「[大人](おとな)」の[価値](かち)[観](かん)がわからない[私](わたし)は、まだ「[大人](おとな)」ではなさそうだ。「[大人](おとな)」の[商品](しょうひん)の[価値](かち)がわかるようになったら、「[大人](おとな)」に（54）。"],"questions":[{"no":50,"options":["ここまで","そういう[大人](おとな)","どのような[人](ひと)","それ[以下](いか)"],"answer":2,"grammar":"どのような+N","grammar_vi":"N như thế nào (hỏi về loại)","sentence":"とすると、こうした[表現](ひょうげん)で[使](つか)われている「[大人](おとな)」とは**どのような[人](ひと)**を[指](さ)しているのだろうか。","sentence_vi":"Vậy thì \\"người lớn\\" được dùng trong những cách diễn đạt này chỉ loại người như thế nào nhỉ?"},{"no":51,"options":["するものだ","するつもりだ","するほうだ","するべきだ"],"answer":0,"grammar":"~たり~たりするものだ","grammar_vi":"Là kiểu ~ (nêu đặc trưng, đặc điểm)","sentence":"これは、[高級](こうきゅう)な[旅館](りょかん)に[泊](と)まったり、[時間](じかん)をかけて[旅行](りょこう)したり**するものだ**。","sentence_vi":"Đây là kiểu du lịch như ở nhà trọ cao cấp, đi du lịch từ từ mất nhiều thời gian."},{"no":52,"options":["[問題](もんだい)ないかどうかだ","[問題](もんだい)ないということだ","[問題](もんだい)ないとするだろうか","[問題](もんだい)ないのだと[思](おも)っていた"],"answer":1,"grammar":"~ということだ(kết luận)","grammar_vi":"Có nghĩa là ~ (kết luận, giải thích)","sentence":"だから、[良](よ)い[素材](そざい)を[使](つか)うことによって[多少](たしょう)[価格](かかく)が[高](たか)くなっても**[問題](もんだい)ないということだ**。","sentence_vi":"Vì vậy, nghĩa là dù giá có cao hơn một chút nhờ dùng nguyên liệu tốt cũng không sao."},{"no":53,"options":["しかも","ただし","[要](よう)するに","それどころか"],"answer":2,"grammar":"要するに","grammar_vi":"Nói tóm lại, tóm lại là","sentence":"**[要](よう)するに**、[経済](けいざい)[的](てき)、[時間](じかん)[的](てき)、[精神](せいしん)[的](てき)に[余裕](よゆう)がある[人](ひと)が「[大人](おとな)」なのだろう。","sentence_vi":"Tóm lại, có lẽ \\"người lớn\\" là người có sự dư dả về kinh tế, thời gian và tinh thần."},{"no":54,"options":["なれるはずだった","なりたくなってきた","なるわけではない","なれるのかもしれない"],"answer":3,"grammar":"Thể thường+かもしれない","grammar_vi":"Có lẽ ~, biết đâu ~","sentence":"「[大人](おとな)」の[商品](しょうひん)の[価値](かち)がわかるようになったら、「[大人](おとな)」に**なれるのかもしれない**。","sentence_vi":"Nếu hiểu được giá trị của những sản phẩm \\"người lớn\\", có lẽ tôi cũng sẽ trở thành \\"người lớn\\"."}],"translation_vi":"Trong tên sản phẩm hay mô tả sản phẩm, tôi thường thấy các cách diễn đạt như \\"du lịch người lớn\\", \\"mì Ý người lớn\\", \\"lớp piano người lớn\\". Dù có chữ \\"người lớn\\" nhưng không phải dành cho người trưởng thành và không có giới hạn tuổi. Vậy thì \\"người lớn\\" được dùng trong những cách diễn đạt này chỉ loại người như thế nào nhỉ? Tò mò, tôi đã tìm hiểu.\\n\\nMột công ty du lịch đang lên kế hoạch \\"chuyến du lịch người lớn\\". Đây là kiểu du lịch như ở nhà trọ cao cấp, đi du lịch từ từ mất nhiều thời gian. Tôi vẫn luôn có hình dung rằng du lịch do công ty du lịch lên kế hoạch là những chuyến đi bận rộn, giá rẻ, ghé nhiều điểm tham quan trong thời gian ngắn, nhưng \\"du lịch người lớn\\" lại khác.\\n\\nNgoài ra, theo bài báo tôi đọc hôm trước, \\"mì Ý người lớn\\" dường như là sản phẩm chú trọng nguyên liệu. Nó được phát triển cho những người không quan tâm lắm đến giá nếu có giá trị. Vì vậy, nghĩa là dù giá có cao hơn một chút nhờ dùng nguyên liệu tốt cũng không sao.\\n\\nHọc viên được tuyển trên áp phích \\"lớp piano người lớn\\" dán ở nhà ga là những người muốn học lại piano đã học ngày xưa, hoặc những người muốn tìm một sở thích gì đó ngoài công việc và việc nhà. Tóm lại, có lẽ \\"người lớn\\" là người có sự dư dả về kinh tế, thời gian và tinh thần. Tôi thì muốn đi du lịch mà không tốn tiền, và bữa ăn thì chuộng số lượng hơn chất lượng. Vì đã quá bận học và làm thêm nên tôi cũng chẳng có dư dả để học thêm gì. Tôi không hiểu giá trị quan của \\"người lớn\\" nên có vẻ vẫn chưa phải là \\"người lớn\\". Nếu hiểu được giá trị của những sản phẩm \\"người lớn\\", có lẽ tôi cũng sẽ trở thành \\"người lớn\\".","title":"[日本](にほん)の「[大人](おとな)」"},{"paragraphs":["それを[見](み)たのは、[日本](にほん)に[着](つ)いた[日](ひ)、[空港](くうこう)からホテルへバスで[向](む)かっているときだった。[高](たか)さは（50）。[青](あお)い[布](ぬの)に[白](しろ)い[字](じ)で「[夏](なつ)[祭](まつ)り」と[書](か)かれた[大](おお)きな[長方形](ちょうほうけい)の[旗](はた)が[道路](どうろ)[沿](ぞ)いに[一定](いってい)[間隔](かんかく)で[何](なん)[本](ほん)も[立](た)っていたのだ。[初](はじ)めて[見](み)る、[面白](おもしろ)い[光景](こうけい)だった。","このとき、「この[旗](はた)は[何](なに)だ？」と[思](おも)った。しかし、[街](まち)を[歩](ある)くと、あちこちに[似](に)たような[旗](はた)があり、それらを[見](み)ているうち、「これは[広告](こうこく)だ。」と[気](き)づいた。[旗](はた)にはそれぞれ、「お[弁当](べんとう)」、「[食](た)べ[放題](ほうだい)」、「[本日](ほんじつ)[特売](とくばい)[日](び)」といった[短](みじか)い[言葉](ことば)が[書](か)かれている。（51）[旗](はた)も[色](いろ)が[派手](はで)で[高](たか)さがあり、1[本](ほん)でもよく[目立](めだ)つ。そのため[自然](しぜん)と[目](め)が[行](い)く。また、[何](なん)[本](ほん)か[同](おな)じ[旗](はた)が[並](なら)んで[立](た)っていると、まるで[一](ひと)つの[大](おお)きな[看板](かんばん)のように[見](み)える。さらに、[旗](はた)はどこにでも[簡単](かんたん)に[立](た)てられるから、[街](まち)のあちこちで（52）。","[私](わたし)はこの[旗](はた)に[強](つよ)い[関心](かんしん)を[持](も)った。（53）、この[旗](はた)は「のぼり」というそうだ。サイズは[縦](たて)180センチ、[横](よこ)60センチのものが[多](おお)い。[布](ぬの)の[上部](じょうぶ)と[片方](かたほう)の[端](はし)に[棒](ぼう)が[通](とお)してあり、[風](かぜ)が[吹](ふ)かなくても[見](み)えるようになっている。[今](いま)の[形](かたち)ののぼりは、600[年](ねん)ぐらい[前](まえ)にはすでにあり、[当時](とうじ)は[戦](たたか)いで[自分](じぶん)の[軍](ぐん)と[敵](てき)の[軍](ぐん)とを[見分](みわ)けるために[使](つか)われていたらしい。[時代](じだい)は[変](か)わり、[今](いま)はそのような[目的](もくてき)で[使](つか)われることはない。だが、[今](いま)も、[情報](じょうほう)を[一瞬](いっしゅん)ではっきりと[伝](つた)えたいときにのぼりを[使](つか)うのは（54）。のぼりの[特徴](とくちょう)をとらえ、[広告](こうこく)に[応用](おうよう)した[発想](はっそう)に[感心](かんしん)した。"],"questions":[{"no":50,"options":["2メートルくらいだっただろうか","2メートルくらいだったものなのか","2メートルくらいだと[言](い)われたそうだ","2メートルくらいだと[思](おも)われていたことだ"],"answer":0,"grammar":"Thể thường+だろうか(nhớ lại)","grammar_vi":"Không biết có phải ~ không (tự hỏi, nhớ lại không chắc chắn)","sentence":"[高](たか)さは**2メートルくらいだっただろうか**。","sentence_vi":"Chiều cao khoảng 2 mét thì phải."},{"no":51,"options":["このように","あのように","どの","そちらの"],"answer":2,"grammar":"どの+N+も","grammar_vi":"N nào cũng ~","sentence":"**どの**[旗](はた)も[色](いろ)が[派手](はで)で[高](たか)さがあり、1[本](ほん)でもよく[目立](めだ)つ。","sentence_vi":"Lá cờ nào cũng màu sắc sặc sỡ, cao lớn, chỉ một cây thôi cũng rất nổi bật."},{"no":52,"options":["[使](つか)われている","[使](つか)っていく","[使](つか)おう","[使](つか)わせる"],"answer":0,"grammar":"Vられている","grammar_vi":"Đang được ~, vẫn được ~ (bị động)","sentence":"さらに、[旗](はた)はどこにでも[簡単](かんたん)に[立](た)てられるから、[街](まち)のあちこちで**[使](つか)われている**。","sentence_vi":"Hơn nữa, vì cờ dựng ở đâu cũng dễ nên được dùng ở khắp nơi trong thành phố."},{"no":53,"options":["[以上](いじょう)から","[旗](はた)といえば","しかしながら","[調](しら)べてみたところ"],"answer":3,"grammar":"Vたところ","grammar_vi":"Khi ~ thì (thấy kết quả)","sentence":"**[調](しら)べてみたところ**、この[旗](はた)は「のぼり」というそうだ。","sentence_vi":"Khi thử tìm hiểu thì được biết lá cờ này gọi là \\"nobori\\"."},{"no":54,"options":["[変](か)わらないこともない","[変](か)わらないようだ","[変](か)えないでおきたい","[変](か)えなければならない"],"answer":1,"grammar":"Thể thường+ようだ","grammar_vi":"Có vẻ ~, dường như ~","sentence":"だが、[今](いま)も、[情報](じょうほう)を[一瞬](いっしゅん)ではっきりと[伝](つた)えたいときにのぼりを[使](つか)うのは**[変](か)わらないようだ**。","sentence_vi":"Nhưng hiện nay, việc dùng nobori khi muốn truyền đạt thông tin rõ ràng trong chớp mắt dường như vẫn không thay đổi."}],"translation_vi":"Tôi nhìn thấy nó vào ngày đến Nhật, khi đang đi xe buýt từ sân bay về khách sạn. Chiều cao khoảng 2 mét thì phải. Rất nhiều lá cờ hình chữ nhật lớn, nền vải xanh chữ trắng viết \\"Lễ hội mùa hè\\", được dựng dọc đường với khoảng cách đều nhau. Đó là một cảnh tượng thú vị lần đầu tôi thấy.\\n\\nLúc đó tôi nghĩ: \\"Những lá cờ này là gì vậy?\\". Nhưng khi đi bộ trong phố, thấy khắp nơi có những lá cờ tương tự, và trong lúc nhìn chúng tôi nhận ra: \\"Đây là quảng cáo\\". Trên mỗi lá cờ viết những từ ngắn như \\"Cơm hộp\\", \\"Ăn thỏa thích\\", \\"Hôm nay giảm giá\\". Lá cờ nào cũng màu sắc sặc sỡ, cao lớn, chỉ một cây thôi cũng rất nổi bật. Vì thế mắt tự nhiên bị thu hút. Ngoài ra, khi có vài lá cờ giống nhau dựng cạnh nhau thì trông như một tấm biển lớn. Hơn nữa, vì cờ dựng ở đâu cũng dễ nên được dùng ở khắp nơi trong thành phố.\\n\\nTôi rất quan tâm đến những lá cờ này. Khi thử tìm hiểu thì được biết lá cờ này gọi là \\"nobori\\". Nhiều cái có kích thước dọc 180 cm, ngang 60 cm. Có thanh xỏ ở phần trên của vải và một bên cạnh để lá cờ nhìn thấy được kể cả khi không có gió. Nobori hình dạng như bây giờ đã có từ khoảng 600 năm trước, hồi đó dường như được dùng để phân biệt quân mình và quân địch trong chiến trận. Thời đại đã đổi thay, ngày nay không còn dùng cho mục đích đó. Nhưng hiện nay, việc dùng nobori khi muốn truyền đạt thông tin rõ ràng trong chớp mắt dường như vẫn không thay đổi. Tôi cảm phục ý tưởng nắm bắt đặc điểm của nobori và ứng dụng vào quảng cáo.","title":"「のぼり」"},{"paragraphs":["すしを[載](の)せた[皿](さら)が、[客席](きゃくせき)[沿](ぞ)いに[設置](せっち)された[台](だい)の[上](うえ)を[通](とお)って[次々](つぎつぎ)に[流](なが)れていく。[回転](かいてん)ずしの[店](みせ)で、[目](め)の[前](まえ)を[通](とお)り[過](す)ぎるおいしそうなすしを[見](み)ていると、どれも[食](た)べたくなる。つい[食](た)べ[過](す)ぎてしまうという[人](ひと)も（50）。[回転](かいてん)ずしで1[回](かい)に[食](た)べる[量](りょう)の[平均](へいきん)は[一人](ひとり)[約](やく)10[皿](さら)だという。すし1つのご[飯](はん)の[量](りょう)が[約](やく)20グラムで、[普通](ふつう)、[回転](かいてん)ずしでは1[皿](さら)にすしが2つ[載](の)っているから、[約](やく)400グラムもご[飯](はん)を[食](た)べていることになる。[茶](ちゃ)わん1[杯](はい)[分](ぶん)のご[飯](はん)の[量](りょう)が[約](やく)150グラムだとすると、（51）。[回転](かいてん)ずしでたくさん[食](た)べてしまうのはなぜなのか。","こんな（52）。すしが[好](す)きな[人](ひと)たちにすしを[食](た)べてもらう。まずは、すしの[皿](さら)を[台](だい)に[載](の)せて[流](なが)さず、1[皿](さら)ずつ[注文](ちゅうもん)してすしを[食](た)べる。[別](べつ)の[日](ひ)に[今度](こんど)は、[流](なが)れているすしの[皿](さら)を[取](と)ってすしを[食](た)べる。（53）、[流](なが)れているときに[食](た)べた[量](りょう)は、そうでないときの[約](やく)1.5[倍](ばい)になったという。","[心理](しんり)[学](がく)の[専門家](せんもんか)によると、これは「[目](め)の[前](まえ)に[流](なが)れてくる」ことの[効果](こうか)らしい。すしが[目](め)の[前](まえ)に[流](なが)れてくると、[意識](いしき)しなくても[目](め)に[入](はい)り、あれもこれも[食](た)べたいと[思](おも)ってしまう。また、[人間](にんげん)は、[目](め)の[前](まえ)で[動](うご)いている[食](た)べ[物](もの)を[見](み)ると[目](め)で[追](お)って[手](て)に[入](い)れようとする[性質](せいしつ)を[持](も)っており、それも[思](おも)わず[皿](さら)を[取](と)ってしまう[原因](げんいん)の[一](ひと)つだということだ。[回転](かいてん)ずしでたくさん[食](た)べてしまうのには、[納得](なっとく)の[理由](りゆう)があったのだ。[回転](かいてん)ずしの[店](みせ)に[行](い)ったとき、[食](た)べ[過](す)ぎてしまうのは（54）。"],"questions":[{"no":50,"options":["[多](おお)かったのか","[多](おお)いのではないか","[多](おお)ければいい","[多](おお)くてよかった"],"answer":1,"grammar":"~のではないか","grammar_vi":"Chẳng phải là ~ sao? (suy đoán nhẹ)","sentence":"つい[食](た)べ[過](す)ぎてしまうという[人](ひと)も**[多](おお)いのではないか**。","sentence_vi":"Chắc cũng có nhiều người lỡ ăn quá nhiều."},{"no":51,"options":["2[杯](はい)[分](ぶん)[以上](いじょう)だ","2[杯](はい)[分](ぶん)[以上](いじょう)でもおかしくない","2[杯](はい)[分](ぶん)[以上](いじょう)だからだ","2[杯](はい)[分](ぶん)[以上](いじょう)でなければいけない"],"answer":0,"grammar":"Số lượng từ+以上","grammar_vi":"Từ ~ trở lên","sentence":"[茶](ちゃ)わん1[杯](はい)[分](ぶん)のご[飯](はん)の[量](りょう)が[約](やく)150グラムだとすると、**2[杯](はい)[分](ぶん)[以上](いじょう)だ**。","sentence_vi":"Nếu một bát cơm khoảng 150 gram thì lượng đó là hơn 2 bát."},{"no":52,"options":["[実験](じっけん)だといえる","[実験](じっけん)だとしている","[実験](じっけん)がある","[実験](じっけん)になる"],"answer":2,"grammar":"こんな+N(chỉ thị)","grammar_vi":"N như thế này (chỉ điều sắp nói tới)","sentence":"こんな**[実験](じっけん)がある**。","sentence_vi":"Có một thí nghiệm như thế này."},{"no":53,"options":["つまり","すると","ところが","[一方](いっぽう)で"],"answer":1,"grammar":"すると","grammar_vi":"Thế rồi, ngay sau đó (sự việc xảy ra kế tiếp)","sentence":"**すると**、[流](なが)れているときに[食](た)べた[量](りょう)は、そうでないときの[約](やく)1.5[倍](ばい)になったという。","sentence_vi":"Kết quả, lượng ăn khi sushi chạy trên băng chuyền nhiều gấp khoảng 1,5 lần so với khi không chạy."},{"no":54,"options":["[避](さ)けたいに[決](き)まっている","[避](さ)けるべきだった","[避](さ)けられたかもしれない","[避](さ)けられないのだろう"],"answer":3,"grammar":"Thể thường+のだろう","grammar_vi":"Có lẽ là ~ (suy đoán, giải thích)","sentence":"[回転](かいてん)ずしの[店](みせ)に[行](い)ったとき、[食](た)べ[過](す)ぎてしまうのは**[避](さ)けられないのだろう**。","sentence_vi":"Khi đến quán sushi băng chuyền, có lẽ khó tránh khỏi việc ăn quá nhiều."}],"translation_vi":"Những đĩa sushi đi qua trên băng chuyền đặt dọc chỗ ngồi của khách, lần lượt trôi qua. Ở quán sushi băng chuyền, khi nhìn những miếng sushi ngon lành trôi trước mắt, món nào cũng muốn ăn. Chắc cũng có nhiều người lỡ ăn quá nhiều. Nghe nói lượng ăn trung bình mỗi lần ở quán sushi băng chuyền là khoảng 10 đĩa mỗi người. Mỗi miếng sushi có khoảng 20 gram cơm, thường mỗi đĩa có 2 miếng, nên tức là ăn tới khoảng 400 gram cơm. Nếu một bát cơm khoảng 150 gram thì lượng đó là hơn 2 bát. Tại sao ở quán sushi băng chuyền lại ăn nhiều đến vậy?\\n\\nCó một thí nghiệm như thế này. Cho những người thích sushi ăn sushi. Trước tiên, đĩa sushi không đặt lên băng chuyền mà họ gọi từng đĩa một để ăn. Hôm khác, lần này họ lấy đĩa sushi đang chạy trên băng chuyền để ăn. Kết quả, lượng ăn khi sushi chạy trên băng chuyền nhiều gấp khoảng 1,5 lần so với khi không chạy.\\n\\nTheo chuyên gia tâm lý học, đây dường như là hiệu quả của việc \\"trôi đến trước mắt\\". Khi sushi trôi đến trước mắt, dù không để ý cũng lọt vào mắt, và ta nảy sinh muốn ăn món này món kia. Ngoài ra, con người có đặc tính khi thấy thức ăn chuyển động trước mắt thì mắt đuổi theo và muốn lấy cho được, và đó cũng là một nguyên nhân khiến ta bất giác lấy đĩa. Việc ăn nhiều ở quán sushi băng chuyền hóa ra có lý do thuyết phục. Khi đến quán sushi băng chuyền, có lẽ khó tránh khỏi việc ăn quá nhiều."},{"paragraphs":["[先日](せんじつ)、サッカーの[日本](にほん)[代表](だいひょう)が[海外](かいがい)で[試合](しあい)を[行](おこな)い、その[試合](しあい)が[深夜](しんや)にテレビで[生](なま)[中継](ちゅうけい)された。[生](なま)[中継](ちゅうけい)が[始](はじ)まる[前](まえ)に、[放送](ほうそう)は[何](なん)[時](じ)からか[確認](かくにん)しようとインターネットで[調](しら)べて[驚](おどろ)いた。あるサイトに「[金曜](きんよう)25[時](じ)[放送](ほうそう)」と[書](か)いてあったのだ。[一日](いちにち)は（50）。","[知人](ちじん)に[聞](き)いて、「[金曜](きんよう)25[時](じ)」というのは[土曜](どよう)の[午前](ごぜん)1[時](じ)のことだと[知](し)った。「25[時](じ)」のような[表現](ひょうげん)は、[店](みせ)の[営業](えいぎょう)[時間](じかん)の[掲示](けいじ)などでも[見](み)るという。なぜ、[午前](ごぜん)1[時](じ)を「25[時](じ)」と[表現](ひょうげん)するのだろうか。","（51）[表現](ひょうげん)を[使](つか)い[始](はじ)めたのはテレビ[局](きょく)だとする[説](せつ)が[有力](ゆうりょく)だ。[日本](にほん)の[多](おお)くのテレビ[局](きょく)では、[朝](あさ)4[時](じ)[前後](ぜんご)に[一日](いちにち)の[放送](ほうそう)が[始](はじ)まり、そこからの24[時間](じかん)を[1日](ついたち)と[考](かんが)える。つまり、テレビ[局](きょく)にとっては、[夜](よる)の0[時](じ)が[1日](ついたち)の[終](お)わりではない。22[時](じ)、23[時](じ)ときたら、その[次](つぎ)は0[時](じ)ではなく24[時](じ)で、[午前](ごぜん)1[時](じ)は25[時](じ)なのである。このようにして「25[時](じ)」という[表現](ひょうげん)が（52）。","[現代](げんだい)の[日本](にほん)[社会](しゃかい)は[夜](よる)[型](がた)[化](か)が[進](すす)み、[午前](ごぜん)0[時](じ)を[過](す)ぎても[活動](かつどう)している[人](ひと)が[多](おお)い。だから、[午前](ごぜん)0[時](じ)を[過](す)ぎても「[今日](きょう)」は[続](つづ)く。（53）、「[起](お)きてから[寝](ね)るまでが[今日](きょう)」だと[考](かんが)えれば、[翌日](よくじつ)の[午前](ごぜん)1[時](じ)ではなく、その[日](ひ)の25[時](じ)と[表現](ひょうげん)したほうが[的確](てきかく)かもしれない。[私](わたし)も、[土曜](どよう)の[午前](ごぜん)1[時](じ)に[見](み)た[番組](ばんぐみ)は[金曜](きんよう)の[夜](よる)に[見](み)たという[感](かん)じがするので、[金曜](きんよう)25[時](じ)と[考](かんが)えたほうが[実際](じっさい)の[感覚](かんかく)に[近](ちか)い[気](き)もする。[生活](せいかつ)の[夜](よる)[型](がた)[化](か)と「[寝](ね)るまでが[今日](きょう)」という[考](かんが)え[方](かた)が、24[時間](じかん)しかない[一日](いちにち)に「25[時](じ)」を（54）。"],"questions":[{"no":50,"options":["24[時間](じかん)なのか","24[時間](じかん)ではないのか","24[時間](じかん)といえるか","24[時間](じかん)だっただろうか"],"answer":1,"grammar":"~のではないか","grammar_vi":"Chẳng phải là ~ sao? (suy đoán nhẹ)","sentence":"[一日](いちにち)は**24[時間](じかん)ではないのか**。","sentence_vi":"Chẳng phải một ngày là 24 giờ sao?"},{"no":51,"options":["こういう","それ[以外](いがい)の","[同](おな)じ","[次](つぎ)のような"],"answer":0,"grammar":"こういう+N(chỉ thị)","grammar_vi":"N như thế này (chỉ loại vừa nói tới)","sentence":"**こういう**[表現](ひょうげん)を[使](つか)い[始](はじ)めたのはテレビ[局](きょく)だとする[説](せつ)が[有力](ゆうりょく)だ。","sentence_vi":"Có giả thuyết mạnh cho rằng chính các đài truyền hình là nơi bắt đầu dùng cách diễn đạt như vậy."},{"no":52,"options":["[生](う)まれることになっている","[生](う)まれたとしよう","[生](う)まれるといわれていた","[生](う)まれたらしい"],"answer":3,"grammar":"Thể thường+らしい","grammar_vi":"Nghe nói ~, hình như ~","sentence":"このようにして「25[時](じ)」という[表現](ひょうげん)が**[生](う)まれたらしい**。","sentence_vi":"Có vẻ cách diễn đạt \\"25 giờ\\" đã ra đời như vậy."},{"no":53,"options":["ただ","[一方](いっぽう)","[確](たし)かに","それでも"],"answer":2,"grammar":"たしかに","grammar_vi":"Đúng là, quả thật","sentence":"**[確](たし)かに**、「[起](お)きてから[寝](ね)るまでが[今日](きょう)」だと[考](かんが)えれば、[翌日](よくじつ)の[午前](ごぜん)1[時](じ)ではなく、その[日](ひ)の25[時](じ)と[表現](ひょうげん)したほうが[的確](てきかく)かもしれない。","sentence_vi":"Quả thật, nếu nghĩ \\"từ lúc thức dậy đến lúc đi ngủ là hôm nay\\" thì có lẽ diễn đạt là 25 giờ của ngày hôm đó sẽ chính xác hơn là 1 giờ sáng ngày hôm sau."},{"no":54,"options":["[作](つく)ったからだ","[作](つく)ったのだろう","[作](つく)ったこともある","[作](つく)ったほどだ"],"answer":1,"grammar":"Thể thường+のだろう","grammar_vi":"Có lẽ là ~ (suy đoán, giải thích)","sentence":"[生活](せいかつ)の[夜](よる)[型](がた)[化](か)と「[寝](ね)るまでが[今日](きょう)」という[考](かんが)え[方](かた)が、24[時間](じかん)しかない[一日](いちにち)に「25[時](じ)」を**[作](つく)ったのだろう**。","sentence_vi":"Có lẽ chính việc sinh hoạt thiên về ban đêm và cách nghĩ \\"đến khi ngủ vẫn là hôm nay\\" đã tạo ra \\"25 giờ\\" trong một ngày chỉ có 24 giờ."}],"translation_vi":"Hôm trước, đội tuyển bóng đá quốc gia Nhật thi đấu ở nước ngoài và trận đấu được truyền hình trực tiếp vào đêm khuya. Trước khi phát sóng trực tiếp bắt đầu, tôi tra trên Internet để xác nhận mấy giờ phát sóng thì ngạc nhiên. Một trang web ghi \\"phát sóng lúc 25 giờ thứ Sáu\\". Chẳng phải một ngày là 24 giờ sao?\\n\\nHỏi người quen, tôi biết rằng \\"25 giờ thứ Sáu\\" nghĩa là 1 giờ sáng thứ Bảy. Nghe nói cách nói như \\"25 giờ\\" cũng gặp ở bảng giờ mở cửa của các cửa hàng. Tại sao 1 giờ sáng lại được diễn đạt là \\"25 giờ\\"?\\n\\nCó giả thuyết mạnh cho rằng chính các đài truyền hình là nơi bắt đầu dùng cách diễn đạt như vậy. Ở nhiều đài truyền hình Nhật, một ngày phát sóng bắt đầu vào khoảng 4 giờ sáng và 24 giờ từ đó được coi là một ngày. Tức là, với đài truyền hình, 0 giờ đêm không phải là kết thúc của một ngày. Sau 22 giờ, 23 giờ thì tiếp theo không phải 0 giờ mà là 24 giờ, và 1 giờ sáng là 25 giờ. Có vẻ cách diễn đạt \\"25 giờ\\" đã ra đời như vậy.\\n\\nXã hội Nhật hiện đại ngày càng thiên về ban đêm, nhiều người vẫn hoạt động sau 0 giờ sáng. Vì vậy, sau 0 giờ \\"hôm nay\\" vẫn tiếp tục. Quả thật, nếu nghĩ \\"từ lúc thức dậy đến lúc đi ngủ là hôm nay\\" thì có lẽ diễn đạt là 25 giờ của ngày hôm đó sẽ chính xác hơn là 1 giờ sáng ngày hôm sau. Tôi cũng có cảm giác chương trình xem lúc 1 giờ sáng thứ Bảy là xem vào tối thứ Sáu, nên nghĩ là \\"25 giờ thứ Sáu\\" có vẻ sát với cảm nhận thực tế hơn. Có lẽ chính việc sinh hoạt thiên về ban đêm và cách nghĩ \\"đến khi ngủ vẫn là hôm nay\\" đã tạo ra \\"25 giờ\\" trong một ngày chỉ có 24 giờ.","title":"25[時](じ)"},{"paragraphs":["[公衆](こうしゅう)トイレの[入](い)り[口](くち)に[描](えが)かれている[男女](だんじょ)の[絵](え)のマーク。そのマークがあれば、[文字](もじ)で「トイレ」と[書](か)かれていなくても、そこがトイレであることがわかる。[世界](せかい)のあちこちで[使](つか)われているこのトイレマークが[実](じつ)は[日本](にほん)で[生](う)まれたものだということを（50）。トイレマークが[生](う)まれたのは、1964[年](ねん)の[東京](とうきょう)オリンピックがきっかけだ。この[東京](とうきょう)オリンピックは、アルファベットを[使](つか)わない[国](くに)での[初](はじ)めての[開催](かいさい)であったため、[特](とく)に[問題](もんだい)になったのが、[言葉](ことば)の[壁](かべ)だった。[当時](とうじ)、[日本](にほん)[国内](こくない)の[案内](あんない)[板](ばん)は「お[手洗](てあら)い」などと[日本語](にほんご)で[書](か)かれているものがほとんどだった。（51）、それでは[世界](せかい)90[数](すう)か[国](こく)から[来日](らいにち)する[選手](せんしゅ)たちに[理解](りかい)してもらえない。かといって、[参加](さんか)[国](こく)すべての[国](くに)の[言葉](ことば)で[書](か)くわけにもいかない。そこで、[案内](あんない)[板](ばん)[作成](さくせい)[者](しゃ)たちは、あらゆる[国](くに)の[選手](せんしゅ)が[理解](りかい)できるよう、[絵](え)で[表](あらわ)すことを[考](かんが)えた。（52）、トイレマークなのだ。","そのほかにも、[食堂](しょくどう)、シャワー、[公衆](こうしゅう)[電話](でんわ)[等](とう)の[施設](しせつ)や[設備](せつび)を[表](あらわ)すマークや、[水泳](すいえい)、バレーボール[等](とう)の[競技](きょうぎ)を[表](あらわ)すマークも[作](つく)られた。[競技](きょうぎ)を[表](あらわ)すマークは、この[東京](とうきょう)オリンピックで[初](はじ)めて[全面](ぜんめん)[的](てき)に[導入](どうにゅう)され、[高](たか)い[評価](ひょうか)を[受](う)けた。そして、その[後](ご)のオリンピックでもデザインを[変](か)えながら[毎回](まいかい)（53）。トイレマークに[代表](だいひょう)されるように、[東京](とうきょう)オリンピックをきっかけに[日本](にほん)で[生](う)まれたマークが、[言葉](ことば)の[壁](かべ)を[越](こ)え、[今](いま)や[新](あら)たなコミュニケーション[手段](しゅだん)として、[世界](せかい)に[広](ひろ)がっている。それは、あらゆる[人](ひと)にわかりやすくという[思](おも)いが[世界](せかい)に[届](とど)いた（54）。"],"questions":[{"no":50,"options":["ご[存](ぞん)じなわけだ","ご[存](ぞん)じだろうか","ご[存](ぞん)じのようだ","ご[存](ぞん)じだからだろう"],"answer":1,"grammar":"ご存じだ","grammar_vi":"Biết (kính ngữ của 知っている)","sentence":"[世界](せかい)のあちこちで[使](つか)われているこのトイレマークが[実](じつ)は[日本](にほん)で[生](う)まれたものだということを**ご[存](ぞん)じだろうか**。","sentence_vi":"Bạn có biết rằng biểu tượng nhà vệ sinh này, đang được dùng khắp thế giới, thực ra ra đời ở Nhật không?"},{"no":51,"options":["それに","しかし","または","それどころか"],"answer":1,"grammar":"しかし","grammar_vi":"Nhưng, tuy nhiên (nối hai câu đối lập)","sentence":"**しかし**、それでは[世界](せかい)90[数](すう)か[国](こく)から[来日](らいにち)する[選手](せんしゅ)たちに[理解](りかい)してもらえない。","sentence_vi":"Tuy nhiên, như vậy thì các vận động viên từ hơn 90 nước trên thế giới đến Nhật sẽ không hiểu được."},{"no":52,"options":["[作成](さくせい)[者](しゃ)が[理解](りかい)したのは","[日本](にほん)で[考](かんが)えられたのが","ここに[生](う)み[出](だ)したのは","こうして[生](う)まれたのが"],"answer":3,"grammar":"こうして","grammar_vi":"Như vậy, nhờ thế (nêu kết quả của quá trình vừa nói)","sentence":"**こうして[生](う)まれたのが**、トイレマークなのだ。","sentence_vi":"Đó chính là biểu tượng nhà vệ sinh ra đời như vậy."},{"no":53,"options":["[使用](しよう)されている","[使用](しよう)した[点](てん)だ","[使用](しよう)していける","[使用](しよう)したいものだ"],"answer":0,"grammar":"Vられている","grammar_vi":"Đang được ~, vẫn được ~ (bị động)","sentence":"そして、その[後](ご)のオリンピックでもデザインを[変](か)えながら[毎回](まいかい)**[使用](しよう)されている**。","sentence_vi":"Và ở các kỳ Olympic sau đó, biểu tượng này cũng được sử dụng mỗi lần, dù thay đổi thiết kế."},{"no":54,"options":["[結果](けっか)として[表](あらわ)れるかもしれない","[結果](けっか)のはずだった","[結果](けっか)に[違](ちが)いない","[結果](けっか)でなければならなかった"],"answer":2,"grammar":"Thể thường+に違いない","grammar_vi":"Chắc chắn là ~","sentence":"それは、あらゆる[人](ひと)にわかりやすくという[思](おも)いが[世界](せかい)に[届](とど)いた**[結果](けっか)に[違](ちが)いない**。","sentence_vi":"Đó chắc chắn là kết quả của việc tâm nguyện làm cho ai cũng dễ hiểu đã đến được với thế giới."}],"translation_vi":"Biểu tượng hình nam nữ vẽ ở lối vào nhà vệ sinh công cộng. Có biểu tượng đó thì dù không viết chữ \\"nhà vệ sinh\\" cũng biết đó là nhà vệ sinh. Bạn có biết rằng biểu tượng nhà vệ sinh này, đang được dùng khắp thế giới, thực ra ra đời ở Nhật không? Biểu tượng nhà vệ sinh ra đời nhân dịp Olympic Tokyo năm 1964. Vì đây là lần đầu tiên Olympic được tổ chức ở một nước không dùng bảng chữ cái, nên điều trở thành vấn đề đặc biệt là rào cản ngôn ngữ. Hồi đó, hầu hết bảng chỉ dẫn trong nước Nhật đều viết bằng tiếng Nhật như \\"Otearai\\". Tuy nhiên, như vậy thì các vận động viên từ hơn 90 nước trên thế giới đến Nhật sẽ không hiểu được. Nhưng cũng không thể viết bằng ngôn ngữ của tất cả các nước tham gia. Vì thế, những người làm bảng chỉ dẫn đã nghĩ đến việc thể hiện bằng hình vẽ để vận động viên của mọi nước đều hiểu được. Đó chính là biểu tượng nhà vệ sinh ra đời như vậy.\\n\\nNgoài ra, người ta còn tạo ra các biểu tượng chỉ cơ sở, thiết bị như nhà ăn, vòi tắm, điện thoại công cộng, và các biểu tượng chỉ môn thi đấu như bơi lội, bóng chuyền. Biểu tượng chỉ môn thi đấu lần đầu tiên được đưa vào toàn diện ở Olympic Tokyo này và nhận được đánh giá cao. Và ở các kỳ Olympic sau đó, biểu tượng này cũng được sử dụng mỗi lần, dù thay đổi thiết kế. Như biểu tượng nhà vệ sinh là đại diện, những biểu tượng ra đời ở Nhật nhân dịp Olympic Tokyo đã vượt qua rào cản ngôn ngữ và nay lan rộng khắp thế giới như một phương tiện giao tiếp mới. Đó chắc chắn là kết quả của việc tâm nguyện làm cho ai cũng dễ hiểu đã đến được với thế giới.","title":"[日本](にほん)[発](はつ)のトイレマーク"},{"paragraphs":["105[歳](さい)の[日本人](にほんじん)[男性](だんせい)が、[陸上](りくじょう)[競技](きょうぎ)の100メートルで[世界](せかい)[記録](きろく)を[出](だ)した。2015[年](ねん)に[行](おこな)われたある[陸上](りくじょう)の[世界](せかい)[大会](たいかい)でのことだ。","「マスターズ」と[呼](よ)ばれる（50）。[日本](にほん)ではまだあまり[知](し)られていないが、スポーツをいくつになっても[楽](たの)しむことを[目的](もくてき)とした[大会](たいかい)で、[陸上](りくじょう)、[水泳](すいえい)、テニスなど[様々](さまざま)な[競技](きょうぎ)の[大会](たいかい)が[世界中](せかいじゅう)で[開催](かいさい)されている。[陸上](りくじょう)の[大会](たいかい)では[通常](つうじょう)5[歳](さい)ごとに[分](わ)けられたクラスで[同年代](どうねんだい)と[競](きそ)う。そのため、[体力](たいりょく)が[落](お)ちて[若](わか)いころのように[走](はし)れなくても[対等](たいとう)に[競](きそ)うことができる。つまり、105[歳](さい)の[男性](だんせい)が[出](だ)した[世界](せかい)[記録](きろく)は、[彼](かれ)が[参加](さんか)したクラスにおける[世界](せかい)[記録](きろく)（51）。","ある[調査](ちょうさ)によると、マスターズに[参加](さんか)している[高齢](こうれい)[者](しゃ)は[心](こころ)と[体](からだ)の[健康](けんこう)を[維持](いじ)しているという。[運動](うんどう)は[心](こころ)に[活気](かっき)を[生](う)み、[記録](きろく)という[目標](もくひょう)は[生活](せいかつ)の[中](なか)で[感](かん)じる[不安](ふあん)やストレスを[少](すく)なくするそうだ。","[心](こころ)も[体](からだ)も[元気](げんき)な[高齢](こうれい)[者](しゃ)の[多](おお)い[社会](しゃかい)は、[高齢](こうれい)[化](か)[社会](しゃかい)の[一](ひと)つの[理想](りそう)である。マスターズに[参加](さんか)する[高齢](こうれい)[者](しゃ)が[増](ふ)えれば、この[理想](りそう)に[近](ちか)づくことができる。（52）、マスターズの[存在](そんざい)が[影響](えいきょう)を[与](あた)えるのは、[参加](さんか)[者](しゃ)にとどまらない。[参加](さんか)[者](しゃ)[以外](いがい)の[高齢](こうれい)[者](しゃ)も、[同年代](どうねんだい)が[記録](きろく)を[目指](めざ)す[姿](すがた)を[目](め)にすることで、[体](からだ)を[動](うご)かすきっかけや[心](こころ)の[活力](かつりょく)が[得](え)られるに[違](ちが)いない。（53）、マスターズが[広](ひろ)く[知](し)られる[必要](ひつよう)がある。テレビなどで[目](め)にする[機会](きかい)が[増](ふ)えるといい。","いつまでも[心身](しんしん)ともに[元気](げんき)でいられる（54）。その[社会](しゃかい)の[実現](じつげん)に[向](む)けて、マスターズの[今後](こんご)の[発展](はってん)が[期待](きたい)される。"],"questions":[{"no":50,"options":["[大会](たいかい)はある","[大会](たいかい)がある","[大会](たいかい)はあるのか","[大会](たいかい)があるのか"],"answer":1,"grammar":"~と呼ばれる+N","grammar_vi":"N được gọi là ~","sentence":"「マスターズ」と[呼](よ)ばれる**[大会](たいかい)がある**。","sentence_vi":"Có một giải đấu gọi là \\"Masters\\"."},{"no":51,"options":["というわけだ","と[言](い)えないこともない","というだけではない","と[言](い)ってもいいぐらいだ"],"answer":0,"grammar":"~というわけだ","grammar_vi":"Nghĩa là vậy, có nghĩa là ~ (kết luận, giải thích)","sentence":"つまり、105[歳](さい)の[男性](だんせい)が[出](だ)した[世界](せかい)[記録](きろく)は、[彼](かれ)が[参加](さんか)したクラスにおける[世界](せかい)[記録](きろく)**というわけだ**。","sentence_vi":"Tức là, kỷ lục thế giới mà người đàn ông 105 tuổi lập nên là kỷ lục thế giới trong hạng mà ông ấy tham gia."},{"no":52,"options":["とすると","とはいえ","さらに","このように"],"answer":2,"grammar":"さらに","grammar_vi":"Hơn nữa, thêm vào đó","sentence":"**さらに**、マスターズの[存在](そんざい)が[影響](えいきょう)を[与](あた)えるのは、[参加](さんか)[者](しゃ)にとどまらない。","sentence_vi":"Hơn nữa, ảnh hưởng của sự tồn tại của Masters không chỉ dừng ở người tham gia."},{"no":53,"options":["そうやって","そうなったら","それでも","それには"],"answer":3,"grammar":"それには","grammar_vi":"Để làm điều đó thì (nêu điều kiện cần)","sentence":"**それには**、マスターズが[広](ひろ)く[知](し)られる[必要](ひつよう)がある。","sentence_vi":"Để làm được điều đó, cần để Masters được biết đến rộng rãi."},{"no":54,"options":["[社会](しゃかい)","[社会](しゃかい)だ","[社会](しゃかい)とは","[社会](しゃかい)だから"],"answer":0,"grammar":"Thể thường+N(bổ nghĩa)","grammar_vi":"N mà ~ (mệnh đề bổ nghĩa cho danh từ)","sentence":"いつまでも[心身](しんしん)ともに[元気](げんき)でいられる**[社会](しゃかい)**。","sentence_vi":"Một xã hội mà mọi người có thể luôn khỏe mạnh cả thân lẫn tâm."}],"translation_vi":"Một người đàn ông Nhật 105 tuổi đã lập kỷ lục thế giới nội dung 100 mét điền kinh. Đó là tại một giải điền kinh thế giới tổ chức năm 2015.\\n\\nCó một giải đấu gọi là \\"Masters\\". Ở Nhật nó vẫn chưa được biết đến nhiều, nhưng đây là giải đấu nhằm mục đích tận hưởng thể thao dù ở bất kỳ tuổi nào, và các giải của nhiều môn như điền kinh, bơi lội, quần vợt được tổ chức khắp thế giới. Ở giải điền kinh, thông thường các vận động viên thi đấu trong các hạng chia theo từng 5 tuổi với những người cùng độ tuổi. Vì thế, dù thể lực suy giảm và không chạy được như hồi trẻ vẫn có thể thi đấu bình đẳng. Tức là, kỷ lục thế giới mà người đàn ông 105 tuổi lập nên là kỷ lục thế giới trong hạng mà ông ấy tham gia.\\n\\nTheo một cuộc khảo sát, những người cao tuổi tham gia Masters duy trì được sức khỏe tinh thần và thể chất. Vận động tạo sinh khí cho tinh thần, và mục tiêu là kỷ lục giúp giảm bớt lo âu, căng thẳng trong cuộc sống.\\n\\nMột xã hội có nhiều người cao tuổi khỏe mạnh cả thân lẫn tâm là một lý tưởng của xã hội già hóa. Nếu số người cao tuổi tham gia Masters tăng lên thì có thể tiến gần lý tưởng này. Hơn nữa, ảnh hưởng của sự tồn tại của Masters không chỉ dừng ở người tham gia. Những người cao tuổi không tham gia chắc chắn cũng nhờ thấy những người cùng tuổi nỗ lực hướng đến kỷ lục mà có động lực vận động cơ thể và sức sống tinh thần. Để làm được điều đó, cần để Masters được biết đến rộng rãi. Mong là cơ hội thấy nó trên truyền hình sẽ nhiều lên.\\n\\nMột xã hội mà mọi người có thể luôn khỏe mạnh cả thân lẫn tâm. Người ta kỳ vọng vào sự phát triển của Masters trong tương lai để hiện thực hóa xã hội đó.","title":"[高齢](こうれい)[化](か)[社会](しゃかい)におけるスポーツ"},{"paragraphs":["[質問](しつもん)：[鳥](とり)はなぜ[飛](と)べるのですか。[人間](にんげん)も[翼](つばさ)（つばさ）をつけたら、[飛](と)べますか。（[草太](そうた) [小](しょう)3）","[回答](かいとう)：[空](そら)を[飛](と)ぶためには[体](からだ)が[軽](かる)いことが[大切](たいせつ)です。（50）、[空](そら)を[飛](と)ぶ[鳥](とり)は、[体](からだ)や[翼](つばさ)の[大](おお)きさのわりには、[体](からだ)がとても[軽](かる)くできているのです。[例](たと)えば、コンドルという[鳥](とり)は、[翼](つばさ)の[長](なが)さ（[左右](さゆう)の[翼](つばさ)を[広](ひろ)げたときの[翼](つばさ)の[先](さき)から[先](さき)までの[長](なが)さ）が3mほどもありますが、[体重](たいじゅう)は10〜15kgしかありません。[鳥](とり)が[重](おも)そうに[見](み)えるのは、[羽](はね)が[膨](ふく)らんでいるからで、[本当](ほんとう)はとても[細](ほそ)い[体](からだ)をしています。そして、[鳥](とり)の[骨](ほね)は[細](ほそ)く、[骨](ほね)の[中](なか)はトンネルのような[空洞](くうどう)の[状態](じょうたい)になっているため、[軽](かる)いのです。","でも[草太](そうた)[君](くん)は、もしかしたら「それなら[人間](にんげん)は、[体重](たいじゅう)に[合](あ)わせて[大](おお)きい[翼](つばさ)をつければいい。」と[思](おも)うかもしれませんね。では、[翼](つばさ)はどのくらいの（51）。ある[説](せつ)によると、[体重](たいじゅう)60kgの[人間](にんげん)が[飛](と)ぶのに[必要](ひつよう)な[翼](つばさ)の[長](なが)さは、[約](やく)34mだそうです。[長](なが)さ10mの[大型](おおがた)バスを3[台](だい)[並](なら)べたときの[長](なが)さよりも[長](なが)いわけです。（52）は[人間](にんげん)にはとても[動](うご)かせませんよね。[鳥](とり)が[体](からだ)のわりに[大](おお)きな[翼](つばさ)を[動](うご)かせるのは、[胸](むね)の[筋肉](きんにく)が[大変](たいへん)[発達](はったつ)しているからです。[鳥](とり)の[胸](むね)の[筋肉](きんにく)は、[体重](たいじゅう)の[約](やく)35%を[占](し)めると[言](い)われています。そのため、[鳥](とり)は[翼](つばさ)を[強](つよ)く[動](うご)かすことができるのです。","そのほかにも、[鳥](とり)の[体](からだ)は[表面](ひょうめん)の[羽](はね)がなめらかで、[空気](くうき)の[抵抗](ていこう)を[受](う)けにくい[形](かたち)になっています。（53）、[鳥](とり)は、[単](たん)に[翼](つばさ)があるから[飛](と)べるのではなく、いろいろな[点](てん)で[体](からだ)[全体](ぜんたい)が[飛](と)ぶのに[最適](さいてき)な[構造](こうぞう)になっていることがわかりますね。[鳥](とり)は[飛](と)ぶために[進化](しんか)してきたのです。[残念](ざんねん)ながら、[人間](にんげん)は、[翼](つばさ)をつけただけでは[飛](と)ぶのは（54）。"],"questions":[{"no":50,"options":["[一方](いっぽう)","[実](じつ)は","ところが","なぜなら"],"answer":1,"grammar":"実は","grammar_vi":"Thực ra là, sự thật là","sentence":"**[実](じつ)は**、[空](そら)を[飛](と)ぶ[鳥](とり)は、[体](からだ)や[翼](つばさ)の[大](おお)きさのわりには、[体](からだ)がとても[軽](かる)くできているのです。","sentence_vi":"Thực ra, loài chim bay trên trời có cơ thể được cấu tạo rất nhẹ so với kích cỡ cơ thể và đôi cánh."},{"no":51,"options":["[長](なが)さがあるのでしょう","[長](なが)さになりましたか","[長](なが)さだと[言](い)いましたか","[長](なが)さが[要](い)るのでしょう"],"answer":3,"grammar":"どのくらいの+N","grammar_vi":"N khoảng bao nhiêu (hỏi mức độ)","sentence":"では、[翼](つばさ)はどのくらいの**[長](なが)さが[要](い)るのでしょう**。","sentence_vi":"Vậy thì, đôi cánh cần có chiều dài khoảng bao nhiêu?"},{"no":52,"options":["[翼](つばさ)","そんなに[大](おお)きな[翼](つばさ)","こっちの[翼](つばさ)","あのような[大](おお)きな[翼](つばさ)"],"answer":1,"grammar":"そんなに","grammar_vi":"~ đến thế (chỉ mức độ vừa nêu ở trước)","sentence":"**そんなに[大](おお)きな[翼](つばさ)**は[人間](にんげん)にはとても[動](うご)かせませんよね。","sentence_vi":"Đôi cánh to đến mức đó thì con người không thể nào vẫy nổi nhỉ."},{"no":53,"options":["これに[対](たい)して","[最初](さいしょ)に[述](の)べたように","こうして[見](み)てみると","[最後](さいご)の[結論](けつろん)から"],"answer":2,"grammar":"こうして見てみると","grammar_vi":"Nhìn như thế này thì (tổng kết)","sentence":"**こうして[見](み)てみると**、[鳥](とり)は、[単](たん)に[翼](つばさ)があるから[飛](と)べるのではなく、いろいろな[点](てん)で[体](からだ)[全体](ぜんたい)が[飛](と)ぶのに[最適](さいてき)な[構造](こうぞう)になっていることがわかりますね。","sentence_vi":"Nhìn như thế này, ta hiểu rằng chim bay được không chỉ vì có cánh, mà toàn bộ cơ thể có cấu trúc tối ưu để bay ở nhiều điểm."},{"no":54,"options":["[難](むずか)しそうです","[難](むずか)しいからです","[難](むずか)しくなってきたらしいです","[難](むずか)しくなってしまうためです"],"answer":0,"grammar":"Aい+そうだ","grammar_vi":"Có vẻ ~ (phán đoán từ vẻ bên ngoài)","sentence":"[残念](ざんねん)ながら、[人間](にんげん)は、[翼](つばさ)をつけただけでは[飛](と)ぶのは**[難](むずか)しそうです**。","sentence_vi":"Đáng tiếc là với con người, chỉ gắn cánh thôi thì có vẻ khó mà bay được."}],"translation_vi":"Câu hỏi: Tại sao chim bay được? Con người gắn cánh vào thì có bay được không? (Souta, lớp 3)\\n\\nTrả lời: Để bay trên trời, điều quan trọng là cơ thể nhẹ. Thực ra, loài chim bay trên trời có cơ thể được cấu tạo rất nhẹ so với kích cỡ cơ thể và đôi cánh. Ví dụ, loài chim gọi là kền kền khoang (condor) có sải cánh (chiều dài từ đầu cánh này đến đầu cánh kia khi dang hai cánh) khoảng 3 m nhưng cân nặng chỉ 10–15 kg. Chim trông có vẻ nặng là vì lông xù lên, thực ra cơ thể rất mảnh. Và xương chim mảnh, bên trong xương rỗng như đường hầm nên nhẹ.\\n\\nNhưng có thể Souta nghĩ: \\"Vậy thì con người cứ gắn cánh lớn phù hợp với cân nặng là được.\\" Vậy thì đôi cánh cần có chiều dài khoảng bao nhiêu? Theo một giả thuyết, chiều dài cánh cần để một người nặng 60 kg bay là khoảng 34 m. Dài hơn cả khi xếp ba chiếc xe buýt lớn dài 10 m cạnh nhau. Đôi cánh to đến mức đó thì con người không thể nào vẫy nổi nhỉ. Chim có thể vẫy đôi cánh lớn so với cơ thể là vì cơ ngực rất phát triển. Người ta nói cơ ngực của chim chiếm khoảng 35% cân nặng. Vì vậy chim có thể vẫy cánh mạnh.\\n\\nNgoài ra, cơ thể chim có lông bề mặt trơn láng, hình dạng khó chịu lực cản của không khí. Nhìn như thế này, ta hiểu rằng chim bay được không chỉ vì có cánh, mà toàn bộ cơ thể có cấu trúc tối ưu để bay ở nhiều điểm. Chim đã tiến hóa để bay. Đáng tiếc là với con người, chỉ gắn cánh thôi thì có vẻ khó mà bay được."},{"paragraphs":["[仕事](しごと)、[買](か)い[物](もの)、[遊](あそ)びに[行](い)くとき、[誰](だれ)でも[必](かなら)ずお[世話](せわ)になるものがある。（50）だ。[当](あ)たり[前](まえ)のように[存在](そんざい)し、[多](おお)くの[人](ひと)に[利用](りよう)されているが、[様々](さまざま)な[工夫](くふう)がされていることはあまり[知](し)られていない。","[例](たと)えば、[高速](こうそく)[道路](どうろ)や[大](おお)きな[道路](どうろ)の[多](おお)くで[雨水](あまみず)が[道路](どうろ)[上](じょう)にたまりにくい[設計](せっけい)になっていることは（51）。[道路](どうろ)[表面](ひょうめん)に[小](ちい)さな[無数](むすう)の[穴](あな)があり、[水](みず)が[舗装](ほそう)の[下](した)に[抜](ぬ)けるという[仕組](しく)みだ。[高速](こうそく)[道路](どうろ)で[雨](あめ)の[日](ひ)に[事故](じこ)が[多](おお)かった[地点](ちてん)も、この[舗装](ほそう)にした[後](あと)、[雨](あめ)の[日](ひ)の[事故](じこ)が[約](やく)80%[減少](げんしょう)したという。（52）、[寒](さむ)い[地域](ちいき)では[雪](ゆき)や[氷](こおり)が[原因](げんいん)でスリップ[事故](じこ)が[多発](たはつ)する。そのため、[雪](ゆき)や[氷](こおり)を[砕](くだ)く[機能](きのう)をもった[道路](どうろ)が[開発](かいはつ)されている。[粒状](りゅうじょう)のゴムなど、[柔軟](じゅうなん)[性](せい)のある[小](ちい)さな[素材](そざい)を[道路](どうろ)に[埋](う)め[込](こ)み、[車](くるま)の[重](おも)みで[道路](どうろ)をわずかに[変形](へんけい)させて[雪](ゆき)や[氷](こおり)を[砕](くだ)く。カーブや[坂道](さかみち)などをそういう[舗装](ほそう)にすれば、[道路](どうろ)に[雪](ゆき)や[氷](こおり)が[密着](みっちゃく)するのを[防](ふせ)ぐことができ、スリップの[危険](きけん)[性](せい)が[減](へ)る。","[道路](どうろ)[表面](ひょうめん)の[温度](おんど)を[下](さ)げる（53）。[道路](どうろ)は[太陽](たいよう)に[熱](ねっ)せられ、[夏](なつ)は[特](とく)に[熱](あつ)くなりやすい。そこで、[太陽光](たいようこう)[線](せん)の[吸収](きゅうしゅう)を[防](ふせ)ぐ[物質](ぶっしつ)を[表面](ひょうめん)に[塗](ぬ)ることで[温度](おんど)[上昇](じょうしょう)を[抑](おさ)えている。この[舗装](ほそう)により、[道路](どうろ)の[温度](おんど)は[最大](さいだい)10[度](ど)[以上](いじょう)も[下](さ)がる。[人](ひと)やペットが[歩](ある)く[公園](こうえん)や[歩道](ほどう)にぴったりだ。","これら[以外](いがい)にも、[様々](さまざま)な[機能](きのう)の[道路](どうろ)が[日々](ひび)[開発](かいはつ)され、[利用](りよう)されている。[道路](どうろ)の[違](ちが)いは[見](み)た[目](め)にはよくわからないかもしれない。しかし、[人々](ひとびと)がより[安全](あんぜん)で[快適](かいてき)に[暮](く)らせるよう、[足元](あしもと)で（54）。"],"questions":[{"no":50,"options":["[道路](どうろ)","ある[道路](どうろ)","その[道路](どうろ)","こんな[道路](どうろ)"],"answer":0,"grammar":"Nだ(nêu lần đầu)","grammar_vi":"N trần: nêu lần đầu, không dùng その/この","sentence":"[仕事](しごと)、[買](か)い[物](もの)、[遊](あそ)びに[行](い)くとき、[誰](だれ)でも[必](かなら)ずお[世話](せわ)になるものがある。**[道路](どうろ)**だ。","sentence_vi":"Khi đi làm, mua sắm hay đi chơi, ai cũng nhất định phải nhờ vả thứ gì đó. Đó là con đường."},{"no":51,"options":["ご[存](ぞん)じだ","ご[存](ぞん)じのようだ","ご[存](ぞん)じだろうか","ご[存](ぞん)じなのだろう"],"answer":2,"grammar":"ご存じだ","grammar_vi":"Biết (kính ngữ của 知っている)","sentence":"[例](たと)えば、[高速](こうそく)[道路](どうろ)や[大](おお)きな[道路](どうろ)の[多](おお)くで[雨水](あまみず)が[道路](どうろ)[上](じょう)にたまりにくい[設計](せっけい)になっていることは**ご[存](ぞん)じだろうか**。","sentence_vi":"Chẳng hạn, bạn có biết rằng nhiều đường cao tốc và đường lớn được thiết kế để nước mưa khó đọng trên mặt đường không?"},{"no":52,"options":["また","すると","こうして","したがって"],"answer":0,"grammar":"また","grammar_vi":"Ngoài ra, hơn nữa (thêm một ví dụ)","sentence":"**また**、[寒](さむ)い[地域](ちいき)では[雪](ゆき)や[氷](こおり)が[原因](げんいん)でスリップ[事故](じこ)が[多発](たはつ)する。","sentence_vi":"Ngoài ra, ở vùng lạnh, tai nạn trượt bánh do tuyết và băng xảy ra nhiều."},{"no":53,"options":["[工夫](くふう)だと[言](い)える","[工夫](くふう)も[考](かんが)えられる","[工夫](くふう)だと[思](おも)われる","[工夫](くふう)も[見](み)られる"],"answer":1,"grammar":"Nも考えられる","grammar_vi":"Cũng có thể nghĩ đến ~, cũng có ~ (nêu thêm ví dụ)","sentence":"[道路](どうろ)[表面](ひょうめん)の[温度](おんど)を[下](さ)げる**[工夫](くふう)も[考](かんが)えられる**。","sentence_vi":"Cũng có cách làm để giảm nhiệt độ bề mặt đường."},{"no":54,"options":["[支](ささ)えてくれているはずだった","[支](ささ)えてくれているわけだ","[支](ささ)えてくれているからだった","[支](ささ)えてくれているおかげだ"],"answer":1,"grammar":"Vてくれているわけだ","grammar_vi":"Vậy là (đang) ~ cho chúng ta (kết luận, giải thích)","sentence":"しかし、[人々](ひとびと)がより[安全](あんぜん)で[快適](かいてき)に[暮](く)らせるよう、[足元](あしもと)で**[支](ささ)えてくれているわけだ**。","sentence_vi":"Tuy nhiên, vậy là dưới chân chúng ta, con đường đang âm thầm nâng đỡ để mọi người sống an toàn và thoải mái hơn."}],"translation_vi":"Khi đi làm, mua sắm hay đi chơi, ai cũng nhất định phải nhờ vả thứ gì đó. Đó là con đường. Nó tồn tại như điều hiển nhiên và được nhiều người sử dụng, nhưng ít người biết có rất nhiều sáng tạo đã được áp dụng.\\n\\nChẳng hạn, bạn có biết rằng nhiều đường cao tốc và đường lớn được thiết kế để nước mưa khó đọng trên mặt đường không? Cơ chế là bề mặt đường có vô số lỗ nhỏ, nước thoát xuống dưới lớp lát. Tại những điểm trên đường cao tốc từng có nhiều tai nạn khi trời mưa, sau khi lát kiểu này, tai nạn ngày mưa nghe nói giảm khoảng 80%. Ngoài ra, ở vùng lạnh, tai nạn trượt bánh do tuyết và băng xảy ra nhiều. Vì vậy, người ta phát triển loại đường có chức năng đập vỡ tuyết và băng. Họ chôn vào đường các vật liệu nhỏ, mềm dẻo như cao su dạng hạt, và dùng trọng lượng của xe làm đường biến dạng chút ít để đập vỡ tuyết, băng. Nếu lát kiểu đó ở các khúc cua, dốc... thì có thể ngăn tuyết, băng bám chặt vào mặt đường, giảm nguy cơ trượt bánh.\\n\\nCũng có cách làm để giảm nhiệt độ bề mặt đường. Đường bị mặt trời đốt nóng, đặc biệt mùa hè rất dễ nóng. Vì vậy người ta phủ lên bề mặt một chất ngăn hấp thụ tia nắng để hạn chế nhiệt độ tăng. Nhờ lớp lát này, nhiệt độ đường giảm tối đa hơn 10 độ. Rất phù hợp cho công viên và vỉa hè nơi người và thú cưng đi lại.\\n\\nNgoài những loại này, các loại đường có nhiều chức năng khác cũng đang được phát triển và sử dụng mỗi ngày. Có thể nhìn bên ngoài khó thấy sự khác biệt của các con đường. Tuy nhiên, vậy là dưới chân chúng ta, con đường đang âm thầm nâng đỡ để mọi người sống an toàn và thoải mái hơn.","title":"[道路](どうろ)のひみつ"},{"paragraphs":["[今](いま)も[昔](むかし)も、[子供](こども)たちに[親](した)しまれている[折](お)り[紙](がみ)。そんな[身近](みぢか)な[折](お)り[紙](がみ)が[今](いま)、「[折](お)り[紙](がみ)[工学](こうがく)」という[学問](がくもん)となっている。[一](いち)[例](れい)を（48）。[折](お)り[紙](がみ)の「[折](お)って[畳](たた)むこと」と「[畳](たた)んだものを[広](ひろ)げること」を[利用](りよう)した[研究](けんきゅう)がある。[大](おお)きなものを[小](ちい)さくし、それを[簡単](かんたん)に[元](もと)の[大](おお)きさに[戻](もど)す[方法](ほうほう)として、[折](お)るだけで[形](かたち)や[大](おお)きさが[変](か)えられる[折](お)り[紙](がみ)が[注目](ちゅうもく)されたのだ。ただ[折](お)って[小](ちい)さくするのなら、[新聞](しんぶん)を[折](お)り[畳](たた)むように[何](なん)[回](かい)も[折](お)ればいい。しかしそれでは、[広](ひろ)げるときに、[畳](たた)んだ[分](ぶん)の[回数](かいすう)だけ[開](ひら)くことになる。（49）、[一気](いっき)に[元](もと)の[大](おお)きさに[戻](もど)せる[折](お)り[方](かた)を[開発](かいはつ)するために[研究](けんきゅう)が[重](かさ)ねられた。その[結果](けっか)、[何](なん)[回](かい)[折](お)った[後](あと)でも、[折](お)り[畳](たた)んだ[状態](じょうたい)から[両端](りょうたん)を[引](ひ)っ[張](ぱ)るだけで、[元](もと)の[平面](へいめん)に[戻](もど)すことができる[方法](ほうほう)にたどり[着](つ)いたのである。","この[折](お)り[方](かた)を（50）、[人工](じんこう)[衛星](えいせい)に[用](もち)いる「[太陽](たいよう)[電池](でんち)パネル」などの[装置](そうち)が[作](つく)られている。[装置](そうち)を[宇宙](うちゅう)へ[運](はこ)ぶロケットの[容量](ようりょう)には[限界](げんかい)があり、[装置](そうち)は[小](ちい)さくしなければならない。だからといって[分割](ぶんかつ)して[部品](ぶひん)にすると、[宇宙](うちゅう)[空間](くうかん)で[組](く)み[立](た)てる[技術](ぎじゅつ)が[必要](ひつよう)となる。ここに[研究](けんきゅう)の[成果](せいか)が[生](い)かされる。[開発](かいはつ)された[折](お)り[方](かた)を[使](つか)えば、[装置](そうち)を[折](お)り[畳](たた)んで[小](ちい)さくすることができ、[宇宙](うちゅう)[空間](くうかん)に[出](で)たときには[簡単](かんたん)に（51）。","[伝統](でんとう)[的](てき)な[遊](あそ)びが[宇宙](うちゅう)で[使](つか)われる[最新](さいしん)[技術](ぎじゅつ)につながっている。[子供](こども)と[折](お)り[紙](がみ)で[遊](あそ)びながら、このような[科学](かがく)の[話](はなし)を（52）。[折](お)り[紙](がみ)を[通](とお)して、[宇宙](うちゅう)[工学](こうがく)や[技術](ぎじゅつ)[開発](かいはつ)の[分野](ぶんや)にも[興味](きょうみ)を[持](も)つかもしれない。"],"questions":[{"no":48,"options":["[挙](あ)げている","[挙](あ)げようとする","[挙](あ)げよう","[挙](あ)げるだろう"],"answer":2,"grammar":"Vよう(ý chí)","grammar_vi":"Để tôi ~, xin phép ~ (người nói tự đưa ra ý định)","sentence":"[一](いち)[例](れい)を**[挙](あ)げよう**。","sentence_vi":"Xin nêu một ví dụ."},{"no":49,"options":["ただし","しかも","そこで","かえって"],"answer":2,"grammar":"そこで","grammar_vi":"Vì vậy, thế là (hành động xảy ra dựa trên điều vừa nói)","sentence":"**そこで**、[一気](いっき)に[元](もと)の[大](おお)きさに[戻](もど)せる[折](お)り[方](かた)を[開発](かいはつ)するために[研究](けんきゅう)が[重](かさ)ねられた。","sentence_vi":"Vì vậy, các nghiên cứu đã được lặp đi lặp lại để phát triển cách gấp có thể trả về kích thước ban đầu chỉ bằng một động tác."},{"no":50,"options":["[活用](かつよう)して","[活用](かつよう)するほかに","[活用](かつよう)するまで","[活用](かつよう)したにもかかわらず"],"answer":0,"grammar":"Vて(cách thức)","grammar_vi":"Bằng cách ~, dùng ~ để (phương tiện)","sentence":"この[折](お)り[方](かた)を**[活用](かつよう)して**、[人工](じんこう)[衛星](えいせい)に[用](もち)いる「[太陽](たいよう)[電池](でんち)パネル」などの[装置](そうち)が[作](つく)られている。","sentence_vi":"Ứng dụng cách gấp này, người ta đang làm ra các thiết bị như \\"tấm pin mặt trời\\" dùng cho vệ tinh nhân tạo."},{"no":51,"options":["[広](ひろ)げられるというのか","[広](ひろ)げられるかのようだ","[広](ひろ)げられるのだろうか","[広](ひろ)げられるというわけだ"],"answer":3,"grammar":"~というわけだ","grammar_vi":"Nghĩa là vậy, có nghĩa là ~ (kết luận, giải thích)","sentence":"[開発](かいはつ)された[折](お)り[方](かた)を[使](つか)えば、[装置](そうち)を[折](お)り[畳](たた)んで[小](ちい)さくすることができ、[宇宙](うちゅう)[空間](くうかん)に[出](で)たときには[簡単](かんたん)に**[広](ひろ)げられるというわけだ**。","sentence_vi":"Nếu dùng cách gấp đã phát triển thì có thể gấp thiết bị nhỏ lại và khi ra không gian vũ trụ có thể dễ dàng mở ra."},{"no":52,"options":["してみたがらない","してみるのも[悪](わる)くない","してみそうない","してみても[始](はじ)まらない"],"answer":1,"grammar":"Vてみるのも悪くない","grammar_vi":"Thử ~ cũng không tồi","sentence":"[子供](こども)と[折](お)り[紙](がみ)で[遊](あそ)びながら、このような[科学](かがく)の[話](はなし)を**してみるのも[悪](わる)くない**。","sentence_vi":"Vừa chơi gấp giấy với con, thử kể những câu chuyện khoa học như thế này cũng không tồi."}],"translation_vi":"Origami (gấp giấy) được trẻ em yêu thích từ xưa đến nay. Origami gần gũi như vậy hiện nay đã trở thành một ngành học gọi là \\"kỹ thuật origami\\". Xin nêu một ví dụ. Có một nghiên cứu tận dụng \\"việc gấp lại\\" và \\"việc mở ra những thứ đã gấp\\" của origami. Origami, có thể thay đổi hình dạng và kích thước chỉ bằng gấp, được chú ý như một phương pháp thu nhỏ vật lớn rồi dễ dàng đưa về kích thước ban đầu. Nếu chỉ gấp để thu nhỏ thì cứ gấp nhiều lần như gấp tờ báo là được. Nhưng như vậy thì khi mở ra phải mở đúng số lần đã gấp. Vì vậy, các nghiên cứu đã được lặp đi lặp lại để phát triển cách gấp có thể trả về kích thước ban đầu chỉ bằng một động tác. Kết quả là người ta tìm ra cách chỉ cần kéo hai đầu từ trạng thái đã gấp là có thể trả về mặt phẳng ban đầu dù đã gấp bao nhiêu lần.\\n\\nỨng dụng cách gấp này, người ta đang làm ra các thiết bị như \\"tấm pin mặt trời\\" dùng cho vệ tinh nhân tạo. Sức chứa của tên lửa đưa thiết bị lên vũ trụ có giới hạn nên phải thu nhỏ thiết bị. Nhưng nếu chia nhỏ thành các bộ phận thì lại cần kỹ thuật lắp ráp trong không gian vũ trụ. Đây là chỗ thành quả nghiên cứu được phát huy. Nếu dùng cách gấp đã phát triển thì có thể gấp thiết bị nhỏ lại và khi ra không gian vũ trụ có thể dễ dàng mở ra.\\n\\nTrò chơi truyền thống đang gắn liền với công nghệ mới nhất được dùng trong vũ trụ. Vừa chơi gấp giấy với con, thử kể những câu chuyện khoa học như thế này cũng không tồi. Qua origami, có thể các em cũng sẽ hứng thú với lĩnh vực kỹ thuật vũ trụ và phát triển công nghệ.","title":"[伝統](でんとう)から[最新](さいしん)[技術](ぎじゅつ)へ"},{"paragraphs":["[夏休](なつやす)みに、[友達](ともだち)に[誘](さそ)われて[打](う)ち[水](みず)のイベントに[参加](さんか)しました。[私](わたし)は、そのとき[初](はじ)めて[打](う)ち[水](みず)というものを[知](し)りました。[打](う)ち[水](みず)は、[暑](あつ)さ[対策](たいさく)として[道路](どうろ)や、[玄関](げんかん)[先](さき)などに[水](みず)をまくという、[日本](にほん)に[昔](むかし)から[伝](つた)わる[生活](せいかつ)の[知恵](ちえ)です。もともとは[各](かく)[家庭](かてい)で[行](おこな)うものでしたが、[節電](せつでん)や[地球](ちきゅう)[温暖](おんだん)[化](か)[対策](たいさく)として[打](う)ち[水](みず)のイベントを[企画](きかく)する[自治体](じちたい)なども（48）。","[打](う)ち[水](みず)をすると、[確](たし)かに[涼](すず)しく[感](かん)じました。（49）、[気分](きぶん)の[問題](もんだい)ではないかとも[思](おも)いました。[打](う)ち[水](みず)によって[実際](じっさい)に[気温](きおん)は[下](さ)がるのでしょうか。","[調](しら)べてみたら、[打](う)ち[水](みず)の[効果](こうか)を[調](しら)べた[実験](じっけん)[結果](けっか)を[紹介](しょうかい)している[記事](きじ)がありました。その[記事](きじ)によると、[水](みず)をまいたところの[気温](きおん)が2[度](ど)[下](さ)がったということでした。これは[水](みず)の[性質](せいしつ)によるものです。[水](みず)は[気体](きたい)になるときに、[周囲](しゅうい)の[熱](ねつ)を[吸収](きゅうしゅう)します。[水](みず)をまいたところの[地面](じめん)の[熱](ねつ)は[気体](きたい)と[一緒](いっしょ)に[逃](に)げていき、[気温](きおん)が（50）。しかも、[地面](じめん)の[温度](おんど)は、[水](みず)が[蒸発](じょうはつ)しきった[後](あと)も1[時間](じかん)は[下](さ)がったままだったとも[書](か)かれていました。","「[打](う)ち[水](みず)の[効果](こうか)を[十分](じゅうぶん)に[得](え)るには、[朝](あさ)か[夕方](ゆうがた)に[日陰](ひかげ)にまくこともポイントのようです。そうすることで[水](みず)がすぐに[蒸発](じょうはつ)せず、[温度](おんど)の[下](さ)がった[状態](じょうたい)が[持続](じぞく)します。」[私](わたし)が[参加](さんか)したイベントも[夕方](ゆうがた)からだったので、なぜだろうと[思](おも)っていましたが、（51）あったのだと[知](し)って、なるほどと[思](おも)いました。","[打](う)ち[水](みず)の[効果](こうか)は、[科学](かがく)[的](てき)に[説明](せつめい)できるものでした。だから[昔](むかし)から[今](いま)まで[打](う)ち[水](みず)の[文化](ぶんか)が[続](つづ)いているのだと（52）。"],"questions":[{"no":48,"options":["[増](ふ)えたとします","[増](ふ)えたためです","[増](ふ)えてしまいます","[増](ふ)えているそうです"],"answer":3,"grammar":"Thể thường+そうだ(nghe nói)","grammar_vi":"Nghe nói ~ (truyền đạt thông tin nghe được)","sentence":"もともとは[各](かく)[家庭](かてい)で[行](おこな)うものでしたが、[節電](せつでん)や[地球](ちきゅう)[温暖](おんだん)[化](か)[対策](たいさく)として[打](う)ち[水](みず)のイベントを[企画](きかく)する[自治体](じちたい)なども**[増](ふ)えているそうです**。","sentence_vi":"Vốn dĩ đó là việc mỗi gia đình tự làm, nhưng nghe nói gần đây cũng ngày càng nhiều chính quyền địa phương tổ chức sự kiện rải nước như một biện pháp tiết kiệm điện và chống nóng lên toàn cầu."},{"no":49,"options":["ただし","それに","つまり","それどころか"],"answer":0,"grammar":"ただし","grammar_vi":"Tuy nhiên (bổ sung điều kiện, ngoại lệ)","sentence":"**ただし**、[気分](きぶん)の[問題](もんだい)ではないかとも[思](おも)いました。","sentence_vi":"Tuy nhiên, tôi cũng nghĩ có thể đó chỉ là vấn đề tâm lý."},{"no":50,"options":["[下](さ)がるところです","[下](さ)がる[一方](いっぽう)でした","[下](さ)がるというわけです","[下](さ)がることがありました"],"answer":2,"grammar":"~というわけだ","grammar_vi":"Nghĩa là vậy, có nghĩa là ~ (kết luận, giải thích)","sentence":"[水](みず)をまいたところの[地面](じめん)の[熱](ねつ)は[気体](きたい)と[一緒](いっしょ)に[逃](に)げていき、[気温](きおん)が**[下](さ)がるというわけです**。","sentence_vi":"Nhiệt của mặt đất nơi tưới nước thoát đi cùng hơi nước, và nhiệt độ không khí giảm xuống."},{"no":51,"options":["ある[理由](りゆう)が","そのような[理由](りゆう)が","どの[理由](りゆう)も","あんな[理由](りゆう)も"],"answer":1,"grammar":"そのような+N","grammar_vi":"N như vậy (chỉ điều vừa nêu ở trước)","sentence":"「[打](う)ち[水](みず)の[効果](こうか)を[十分](じゅうぶん)に[得](え)るには、[朝](あさ)か[夕方](ゆうがた)に[日陰](ひかげ)にまくこともポイントのようです。そうすることで[水](みず)がすぐに[蒸発](じょうはつ)せず、[温度](おんど)の[下](さ)がった[状態](じょうたい)が[持続](じぞく)します。」[私](わたし)が[参加](さんか)したイベントも[夕方](ゆうがた)からだったので、なぜだろうと[思](おも)っていましたが、**そのような[理由](りゆう)が**あったのだと[知](し)って、なるほどと[思](おも)いました。","sentence_vi":"Tôi vốn thắc mắc vì sao sự kiện mình tham gia cũng bắt đầu từ chiều, nhưng khi biết có lý do như vậy, tôi mới thấy đúng là thế."},{"no":52,"options":["[納得](なっとく)させられました","[納得](なっとく)したのでしょう","[納得](なっとく)させてほしかったです","[納得](なっとく)してもらえました"],"answer":0,"grammar":"Vさせられる(nhận ra)","grammar_vi":"Bị khiến cho (nhận ra, cảm thấy) ~","sentence":"だから[昔](むかし)から[今](いま)まで[打](う)ち[水](みず)の[文化](ぶんか)が[続](つづ)いているのだと**[納得](なっとく)させられました**。","sentence_vi":"Tôi đã được thuyết phục rằng chính vì thế văn hóa rải nước vẫn tiếp tục từ xưa đến nay."}],"translation_vi":"Vào kỳ nghỉ hè, tôi được bạn rủ tham gia một sự kiện uchimizu (rải nước). Lúc đó tôi lần đầu biết đến uchimizu. Uchimizu là trí tuệ sinh hoạt truyền từ xưa ở Nhật, là việc rải nước lên đường, trước cửa nhà... để chống nóng. Vốn dĩ đó là việc mỗi gia đình tự làm, nhưng nghe nói gần đây cũng ngày càng nhiều chính quyền địa phương tổ chức sự kiện uchimizu như một biện pháp tiết kiệm điện và chống nóng lên toàn cầu.\\n\\nKhi rải nước, tôi quả thật cảm thấy mát. Tuy nhiên, tôi cũng nghĩ có thể đó chỉ là vấn đề tâm lý. Liệu rải nước có thực sự làm nhiệt độ giảm không?\\n\\nKhi tìm hiểu, tôi thấy có bài báo giới thiệu kết quả thí nghiệm về hiệu quả của uchimizu. Theo bài báo, nhiệt độ ở nơi rải nước giảm 2 độ. Điều này là do tính chất của nước. Khi nước hóa hơi, nó hấp thụ nhiệt xung quanh. Nhiệt của mặt đất nơi tưới nước thoát đi cùng hơi nước, và nhiệt độ không khí giảm xuống. Hơn nữa, bài báo còn viết rằng nhiệt độ mặt đất vẫn giảm trong 1 giờ sau khi nước bay hơi hết.\\n\\n\\"Để có đủ hiệu quả của uchimizu, điểm mấu chốt dường như là rải nước vào buổi sáng hoặc chiều ở chỗ bóng râm. Làm vậy nước không bay hơi ngay và trạng thái nhiệt độ giảm được duy trì.\\" Sự kiện tôi tham gia cũng bắt đầu từ chiều nên tôi thắc mắc vì sao, nhưng khi biết có lý do như vậy, tôi mới thấy đúng là thế.\\n\\nHiệu quả của uchimizu có thể giải thích bằng khoa học. Tôi đã được thuyết phục rằng chính vì thế văn hóa rải nước vẫn tiếp tục từ xưa đến nay.","title":"[打](う)ち[水](みず)"},{"paragraphs":["[初](はじ)めて[正確](せいかく)な[日本](にほん)[地図](ちず)を[作成](さくせい)した[人物](じんぶつ)として[知](し)られる[伊能](いのう)[忠敬](ただたか)は、1745[年](ねん)、[上総](かずさ)[国](こく)（[今](いま)の[千葉](ちば)[県](けん)）に[生](う)まれた。[優](すぐ)れた[経営](けいえい)[者](しゃ)だった[忠敬](ただたか)だが、50[歳](さい)を[前](まえ)に[仕事](しごと)をやめ、[興味](きょうみ)があった[星](ほし)や[暦](こよみ)について[高橋](たかはし)[至時](よしとき)のもとで（48）。19[歳](さい)も[年下](としした)の[至時](よしとき)を[忠敬](ただたか)は[敬](うやま)い、[熱心](ねっしん)に[勉強](べんきょう)した。[当時](とうじ)の[学者](がくしゃ)たちの[関心](かんしん)は、[地球](ちきゅう)の[直径](ちょっけい)を[知](し)ることにあった。[江戸](えど)（[今](いま)の[東京](とうきょう)）から[蝦夷](えぞ)[地](ち)（[今](いま)の[北海道](ほっかいどう)）までの[距離](きょり)は[当時](とうじ)はまだわからなかったが、それが（49）[正確](せいかく)に[直径](ちょっけい)が[計算](けいさん)できると[知](し)った[忠敬](ただたか)は、[蝦夷](えぞ)[地](ち)へ[行](い)くことを[願](ねが)う。しかし、[蝦夷](えぞ)[地](ち)に[行](い)くには[国](くに)の[許可](きょか)が[必要](ひつよう)だった。[至時](よしとき)は、[蝦夷](えぞ)[地](ち)の[地図](ちず)[作成](さくせい)を[理由](りゆう)に[国](くに)の[許可](きょか)をとり、[忠敬](ただたか)を[担当](たんとう)にする。（50）、[忠敬](ただたか)55[歳](さい)のとき、[地図](ちず)[作](づく)りの[旅](たび)が[始](はじ)まった。","[昼間](ひるま)は[測](はか)って[歩](ある)き、[夜](よる)は[星](ほし)を[観察](かんさつ)して[昼間](ひるま)[測](はか)った[数値](すうち)を[修正](しゅうせい)する[日々](ひび)が[続](つづ)いた。[完成](かんせい)した[蝦夷](えぞ)[地](ち)の[地図](ちず)は[国](くに)から[高](たか)く[評価](ひょうか)され、[忠敬](ただたか)は[東日本](ひがしにほん)の[地図](ちず)[作成](さくせい)も（51）。[地図](ちず)[作成](さくせい)の[旅](たび)は[順調](じゅんちょう)に[終](お)わったが、[完成](かんせい)[前](まえ)、[忠敬](ただたか)を[支](ささ)え[続](つづ)けた[至時](よしとき)が[病気](びょうき)で[亡](な)くなってしまう。[一番](いちばん)の[理解](りかい)[者](しゃ)である[至時](よしとき)を[失](うしな)い、[忠敬](ただたか)はひどく[落](お)ち[込](こ)んだ。だが、[悲](かな)しみに[耐](た)え、さらに[命](めい)じられた[西日本](にしにほん)の[地図](ちず)[作成](さくせい)にも[取](と)り[組](く)む。[旅](たび)を[終](お)え、[完成](かんせい)に[向](む)けて[作業](さぎょう)の[最終](さいしゅう)[段階](だんかい)に[入](はい)っていた1818[年](ねん)、[忠敬](ただたか)は73[歳](さい)で[人生](じんせい)の[幕](まく)を[閉](と)じた。[作業](さぎょう)は[弟子](でし)らが[続](つづ)け、1821[年](ねん)、[日本](にほん)[全国](ぜんこく)の[地図](ちず)が[完成](かんせい)した。","[忠敬](ただたか)は[自分](じぶん)に[大](おお)きな[仕事](しごと)ができたのはすべて[至時](よしとき)[先生](せんせい)のおかげだと[書](か)き[残](のこ)している。[歴史](れきし)に[残](のこ)る（52）は、[二](に)[人](にん)の[信頼](しんらい)[関係](かんけい)によって、[誕生](たんじょう)したのである。"],"questions":[{"no":48,"options":["[学](まな)んだばかりだ","[学](まな)ぼうと[思](おも)っている","[学](まな)び[始](はじ)めた","[学](まな)ぶところだった"],"answer":2,"grammar":"V_ます_+はじめる","grammar_vi":"Bắt đầu ~","sentence":"[優](すぐ)れた[経営](けいえい)[者](しゃ)だった[忠敬](ただたか)だが、50[歳](さい)を[前](まえ)に[仕事](しごと)をやめ、[興味](きょうみ)があった[星](ほし)や[暦](こよみ)について[高橋](たかはし)[至時](よしとき)のもとで**[学](まな)び[始](はじ)めた**。","sentence_vi":"Tadataka vốn là một nhà kinh doanh giỏi, nhưng trước tuổi 50 ông nghỉ việc và bắt đầu học về sao và lịch mà ông hứng thú dưới sự hướng dẫn của Takahashi Yoshitoki."},{"no":49,"options":["わかって","わかれば","わかるため","わかったことで"],"answer":1,"grammar":"Vば(điều kiện)","grammar_vi":"Nếu ~ thì ~","sentence":"[江戸](えど)（[今](いま)の[東京](とうきょう)）から[蝦夷](えぞ)[地](ち)（[今](いま)の[北海道](ほっかいどう)）までの[距離](きょり)は[当時](とうじ)はまだわからなかったが、それが**わかれば**[正確](せいかく)に[直径](ちょっけい)が[計算](けいさん)できると[知](し)った[忠敬](ただたか)は、[蝦夷](えぞ)[地](ち)へ[行](い)くことを[願](ねが)う。","sentence_vi":"Khoảng cách từ Edo đến Ezo hồi đó vẫn chưa biết, nhưng Tadataka biết rằng nếu biết được nó thì có thể tính chính xác đường kính, nên ông mong được đến Ezo."},{"no":50,"options":["また","しかも","ところが","こうして"],"answer":3,"grammar":"こうして","grammar_vi":"Như vậy, nhờ thế (nêu kết quả của quá trình vừa nói)","sentence":"**こうして**、[忠敬](ただたか)55[歳](さい)のとき、[地図](ちず)[作](づく)りの[旅](たび)が[始](はじ)まった。","sentence_vi":"Như vậy, khi Tadataka 55 tuổi, chuyến đi vẽ bản đồ bắt đầu."},{"no":51,"options":["[命](めい)じられることとなる","[命](めい)じられたことになる","[命](めい)じられることもある","[命](めい)じられたことである"],"answer":1,"grammar":"Vた+ことになる","grammar_vi":"Tức là đã ~, trở thành đã ~ (kết luận)","sentence":"[完成](かんせい)した[蝦夷](えぞ)[地](ち)の[地図](ちず)は[国](くに)から[高](たか)く[評価](ひょうか)され、[忠敬](ただたか)は[東日本](ひがしにほん)の[地図](ちず)[作成](さくせい)も**[命](めい)じられたことになる**。","sentence_vi":"Bản đồ Ezo hoàn thành được nhà nước đánh giá cao, và nói cách khác Tadataka cũng được giao vẽ bản đồ miền Đông Nhật Bản."},{"no":52,"options":["これ","あるもの","[日本](にほん)[地図](ちず)","そういう[地図](ちず)"],"answer":2,"grammar":"Thể thường+N(bổ nghĩa)","grammar_vi":"N mà ~ (mệnh đề bổ nghĩa cho danh từ)","sentence":"[歴史](れきし)に[残](のこ)る**[日本](にほん)[地図](ちず)**は、[二](に)[人](にん)の[信頼](しんらい)[関係](かんけい)によって、[誕生](たんじょう)したのである。","sentence_vi":"Bản đồ Nhật Bản đi vào lịch sử đã ra đời nhờ mối quan hệ tin cậy giữa hai người."}],"translation_vi":"Ino Tadataka, người được biết đến là người đầu tiên lập bản đồ Nhật Bản chính xác, sinh năm 1745 ở xứ Kazusa (nay là tỉnh Chiba). Tadataka vốn là một nhà kinh doanh giỏi, nhưng trước tuổi 50 ông nghỉ việc và bắt đầu học về sao và lịch mà ông hứng thú dưới sự hướng dẫn của Takahashi Yoshitoki. Tadataka kính trọng Yoshitoki, người trẻ hơn mình 19 tuổi, và học tập chăm chỉ. Mối quan tâm của các học giả thời đó là biết đường kính Trái Đất. Khoảng cách từ Edo (nay là Tokyo) đến Ezo (nay là Hokkaido) hồi đó vẫn chưa biết, nhưng Tadataka biết rằng nếu biết được nó thì có thể tính chính xác đường kính, nên ông mong được đến Ezo. Tuy nhiên, để đến Ezo cần có giấy phép của nhà nước. Yoshitoki lấy lý do vẽ bản đồ Ezo để xin phép nhà nước và giao Tadataka phụ trách. Như vậy, khi Tadataka 55 tuổi, chuyến đi vẽ bản đồ bắt đầu.\\n\\nBan ngày đi bộ đo đạc, ban đêm quan sát sao để hiệu chỉnh số liệu đo ban ngày; những ngày như thế kéo dài. Bản đồ Ezo hoàn thành được nhà nước đánh giá cao, và nói cách khác Tadataka cũng được giao vẽ bản đồ miền Đông Nhật Bản. Chuyến đi vẽ bản đồ diễn ra suôn sẻ, nhưng trước khi hoàn thành, Yoshitoki, người luôn nâng đỡ Tadataka, qua đời vì bệnh. Mất đi người hiểu mình nhất, Tadataka vô cùng suy sụp. Nhưng ông vượt qua nỗi buồn, tiếp tục đảm nhận vẽ bản đồ miền Tây Nhật Bản được giao thêm. Năm 1818, khi đã kết thúc chuyến đi và bước vào giai đoạn cuối của việc hoàn thiện, Tadataka qua đời ở tuổi 73. Các đệ tử tiếp tục công việc, và năm 1821 bản đồ toàn Nhật Bản hoàn thành.\\n\\nTadataka đã viết lại rằng việc ông có thể làm nên một sự nghiệp lớn đều là nhờ thầy Yoshitoki. Bản đồ Nhật Bản đi vào lịch sử đã ra đời nhờ mối quan hệ tin cậy giữa hai người."},{"paragraphs":["[私](わたし)はロボット[工学](こうがく)を[専攻](せんこう)しています。[将来](しょうらい)は[医療](いりょう)[分野](ぶんや)でのロボット[活用](かつよう)に[関](かか)わる[仕事](しごと)をするのが[夢](ゆめ)です。[今](いま)は「ロボット・セラピー」というものに[興味](きょうみ)があります。[最近](さいきん)、[介護](かいご)の[現場](げんば)で[注目](ちゅうもく)されているものですが、みなさん、（48）。","「アニマル・セラピー」なら[聞](き)いたことのある[人](ひと)も[多](おお)いかもしれません。[動物](どうぶつ)と[触](ふ)れ[合](あ)うことで[穏](おだ)やかな[気持](きも)ちになり、ストレスが[減](へ)るなどの[医療](いりょう)[効果](こうか)で[知](し)られています。しかし、[実際](じっさい)に[介護](かいご)[施設](しせつ)などで[動物](どうぶつ)を[飼](か)おうとすると、アレルギーや[世話](せわ)の[問題](もんだい)など、[難](むずか)しい[面](めん)もあります。（49）、アニマル・セラピーに[替](か)わるものとして、[最近](さいきん)、ロボット・セラピーが[注目](ちゅうもく)されるようになりました。","ロボット・セラピーのロボットには[動物](どうぶつ)[型](がた)、[赤](あか)ちゃん[型](がた)などがあり、それらに[共通](きょうつう)するのはコミュニケーションが[可能](かのう)だということです。どの[型](かた)のロボットも、[感覚](かんかく)[機能](きのう)を[持](も)っており、[触](ふ)れ[合](あ)う[人](ひと)の[様子](ようす)や[周囲](しゅうい)の[状況](じょうきょう)を[判断](はんだん)して、[様々](さまざま)な[感情](かんじょう)を[表現](ひょうげん)することができます。[例](たと)えば、だっこされたり、なでられたりすると、[可愛](かわい)い[声](こえ)を[出](だ)して[喜](よろこ)んだり、[気持](きも)ち[良](よ)さそうな[表情](ひょうじょう)をしたりします。こういったロボットとの[触](ふ)れ[合](あ)いによって、[精神](せいしん)[的](てき)[安定](あんてい)やコミュニケーション[能力](のうりょく)の[改善](かいぜん)などの[効果](こうか)が（50）。","[私](わたし)が[今](いま)[学](まな)んでいるのはロボット[工学](こうがく)の[基礎](きそ)です。[将来](しょうらい)こういったロボットの[研究](けんきゅう)、[開発](かいはつ)に[参加](さんか)するために、これからも[勉強](べんきょう)を[続](つづ)けます。そして、[医療](いりょう)[分野](ぶんや)に（51）。"],"questions":[{"no":48,"options":["ご[存知](ぞんじ)でしょう","ご[存知](ぞんじ)だと[思](おも)います","ご[存知](ぞんじ)でしょうか","ご[存知](ぞんじ)だと[思](おも)いますか"],"answer":2,"grammar":"ご存じだ","grammar_vi":"Biết (kính ngữ của 知っている)","sentence":"[最近](さいきん)、[介護](かいご)の[現場](げんば)で[注目](ちゅうもく)されているものですが、みなさん、**ご[存知](ぞんじ)でしょうか**。","sentence_vi":"Đây là thứ gần đây được chú ý ở hiện trường chăm sóc người cao tuổi, các bạn có biết không?"},{"no":49,"options":["そこで","そのうえ","それなのに","そういえば"],"answer":0,"grammar":"そこで","grammar_vi":"Vì vậy, thế là (hành động xảy ra dựa trên điều vừa nói)","sentence":"**そこで**、アニマル・セラピーに[替](か)わるものとして、[最近](さいきん)、ロボット・セラピーが[注目](ちゅうもく)されるようになりました。","sentence_vi":"Vì vậy, gần đây robot therapy bắt đầu được chú ý như một thứ thay thế cho animal therapy."},{"no":50,"options":["[得](え)られる[点](てん)です","[得](え)られてもかまいません","[得](え)られるのだそうです","[得](え)られなければなりません"],"answer":2,"grammar":"Thể thường+そうだ(nghe nói)","grammar_vi":"Nghe nói ~ (truyền đạt thông tin nghe được)","sentence":"こういったロボットとの[触](ふ)れ[合](あ)いによって、[精神](せいしん)[的](てき)[安定](あんてい)やコミュニケーション[能力](のうりょく)の[改善](かいぜん)などの[効果](こうか)が**[得](え)られるのだそうです**。","sentence_vi":"Nghe nói nhờ tiếp xúc với những robot như vậy, có thể đạt được hiệu quả như ổn định tinh thần và cải thiện khả năng giao tiếp."},{"no":51,"options":["[貢献](こうけん)するつもりでした","[貢献](こうけん)すべきだからです","[貢献](こうけん)できるようにしています","[貢献](こうけん)できるようになりたいです"],"answer":3,"grammar":"Vるようになる","grammar_vi":"Trở nên có thể ~, dần dần ~ (Vるようになりたい = muốn trở nên có thể ~)","sentence":"そして、[医療](いりょう)[分野](ぶんや)に**[貢献](こうけん)できるようになりたいです**。","sentence_vi":"Và tôi muốn trở thành người có thể đóng góp cho lĩnh vực y tế."}],"translation_vi":"Tôi đang theo học ngành robot học. Ước mơ của tôi là trong tương lai làm công việc liên quan đến ứng dụng robot trong lĩnh vực y tế. Hiện tại tôi quan tâm đến cái gọi là \\"robot therapy\\". Đây là thứ gần đây được chú ý ở hiện trường chăm sóc người cao tuổi, các bạn có biết không?\\n\\nCó thể nhiều người đã nghe nói đến \\"animal therapy\\". Nó được biết đến với hiệu quả y tế như nhờ tiếp xúc với động vật mà tâm trạng trở nên yên bình, căng thẳng giảm. Tuy nhiên, thực tế khi định nuôi động vật ở các cơ sở chăm sóc, cũng có những mặt khó như dị ứng và vấn đề chăm sóc. Vì vậy, gần đây robot therapy bắt đầu được chú ý như một thứ thay thế cho animal therapy.\\n\\nRobot dùng trong robot therapy có loại hình thú vật, loại hình em bé..., và điểm chung của chúng là có thể giao tiếp. Robot loại nào cũng có chức năng cảm giác, phán đoán trạng thái của người tiếp xúc và tình hình xung quanh để thể hiện nhiều cảm xúc. Ví dụ, khi được bế hoặc vuốt ve, chúng phát ra tiếng đáng yêu để tỏ vẻ vui, hoặc có vẻ mặt thoải mái. Nghe nói nhờ tiếp xúc với những robot như vậy, có thể đạt được hiệu quả như ổn định tinh thần và cải thiện khả năng giao tiếp.\\n\\nHiện tôi đang học những kiến thức cơ bản của ngành robot. Để sau này tham gia nghiên cứu, phát triển những robot như vậy, từ nay tôi sẽ tiếp tục học. Và tôi muốn trở thành người có thể đóng góp cho lĩnh vực y tế.","title":"ロボット・セラピー"},{"paragraphs":["[毎日](まいにち)の[生活](せいかつ)の[中](なか)で、[天気](てんき)[予報](よほう)は[欠](か)かせない[情報](じょうほう)の[一](ひと)つだ。[着](き)る[服](ふく)を[選](えら)ぶときも、[休日](きゅうじつ)の[予定](よてい)を[立](た)てるときも、[天気](てんき)は（48）。[毎朝](まいあさ)[天気](てんき)[情報](じょうほう)をチェックしている[人](ひと)も[多](おお)いだろう。","そんな[天気](てんき)[予報](よほう)を[活用](かつよう)した[新](あら)たな[取](と)り[組](く)みが[始](はじ)まっている。[気象](きしょう)[情報](じょうほう)から[食品](しょくひん)の[高度](こうど)な[需要](じゅよう)[予測](よそく)を[行](おこな)い、「[食品](しょくひん)ロス」、つまり、まだ[食](た)べられるのに[捨](す)てられてしまう[食品](しょくひん)を[減](へ)らすというものだ。[食品](しょくひん)の[中](なか)には、[天候](てんこう)や[気温](きおん)に[需要](じゅよう)が[大](おお)きく[左右](さゆう)されるものも[多](おお)い。[需要](じゅよう)[予測](よそく)を[誤](あやま)り、[過剰](かじょう)に[生産](せいさん)してしまうと、それだけ[多](おお)くの[食品](しょくひん)ロスが[生](しょう)じてしまう。（49）[政府](せいふ)は、[気象](きしょう)データとPOSデータ（[何](なに)が、いつ、いくつ、いくらで[売](う)れたのかを[示](しめ)す[販売](はんばい)[情報](じょうほう)）から[高度](こうど)な[需要](じゅよう)[予測](よそく)を[行](おこな)い、[製造](せいぞう)や[販売](はんばい)の[各社](かくしゃ)に[提供](ていきょう)する[取](と)り[組](く)みを[始](はじ)めた。その[結果](けっか)は、[食品](しょくひん)ロスを[減](へ)らせるばかりではない。[食品](しょくひん)が[無駄](むだ)に[捨](す)てられることが[少](すく)なくなるため、その[処理](しょり)の[過程](かてい)で[発生](はっせい)する[二酸化炭素](にさんかたんそ)を[減](へ)らすこともできる。","（50）、まず、[長期](ちょうき)[保存](ほぞん)ができず[気象](きしょう)[状況](じょうきょう)が[売](う)り[上](あ)げに[大](おお)きく[影響](えいきょう)する「[豆腐](とうふ)」と、[特定](とくてい)の[季節](きせつ)に[需要](じゅよう)が[集中](しゅうちゅう)する「[麺](めん)つゆ」に[絞](しぼ)って[実験](じっけん)が[行](おこな)われた。その[結果](けっか)、[食品](しょくひん)ロスを20〜30％[減](へ)らせることがわかった。[現在](げんざい)は、[対象](たいしょう)[商品](しょうひん)を[拡大](かくだい)しながら、[人工](じんこう)[知能](ちのう)も[取](と)り[入](い)れ、さらに[高度](こうど)な[需要](じゅよう)[予測](よそく)が[可能](かのう)になってきているという。このように、[私](わたし)たちの[生活](せいかつ)に[欠](か)かせない[気象](きしょう)[情報](じょうほう)は、[食品](しょくひん)ロス[問題](もんだい)の[解決](かいけつ)にも[役立](やくだ)っているのである。[今後](こんご)、より[大](おお)きな[成果](せいか)が（51）。"],"questions":[{"no":48,"options":["[気](き)になるもの","[気](き)になるだけ","[気](き)になるかどうか","[気](き)になるかのよう"],"answer":0,"grammar":"~もの(kết câu bằng danh từ)","grammar_vi":"Kết câu bằng danh từ 'もの' (nêu nhận xét chung)","sentence":"[着](き)る[服](ふく)を[選](えら)ぶときも、[休日](きゅうじつ)の[予定](よてい)を[立](た)てるときも、[天気](てんき)は**[気](き)になるもの**。","sentence_vi":"Khi chọn quần áo mặc hay khi lên kế hoạch ngày nghỉ, thời tiết đều là điều người ta để ý."},{"no":49,"options":["なお","たとえば","そこで","ところが"],"answer":2,"grammar":"そこで","grammar_vi":"Vì vậy, thế là (hành động xảy ra dựa trên điều vừa nói)","sentence":"**そこで**[政府](せいふ)は、[気象](きしょう)データとPOSデータ（[何](なに)が、いつ、いくつ、いくらで[売](う)れたのかを[示](しめ)す[販売](はんばい)[情報](じょうほう)）から[高度](こうど)な[需要](じゅよう)[予測](よそく)を[行](おこな)い、[製造](せいぞう)や[販売](はんばい)の[各社](かくしゃ)に[提供](ていきょう)する[取](と)り[組](く)みを[始](はじ)めた。","sentence_vi":"Vì vậy, chính phủ đã bắt đầu một nỗ lực dự báo nhu cầu ở mức cao từ dữ liệu khí tượng và dữ liệu POS (thông tin bán hàng cho biết cái gì, khi nào, bao nhiêu, giá bao nhiêu) rồi cung cấp cho các công ty sản xuất và bán hàng."},{"no":50,"options":["この[取](と)り[組](く)みは","そういった[取](と)り[組](く)みも","あのような[取](と)り[組](く)み","こちらの[取](と)り[組](く)みも"],"answer":0,"grammar":"この+N(chỉ thị)","grammar_vi":"N này (chỉ điều đang nói đến)","sentence":"**この[取](と)り[組](く)みは**、まず、[長期](ちょうき)[保存](ほぞん)ができず[気象](きしょう)[状況](じょうきょう)が[売](う)り[上](あ)げに[大](おお)きく[影響](えいきょう)する「[豆腐](とうふ)」と、[特定](とくてい)の[季節](きせつ)に[需要](じゅよう)が[集中](しゅうちゅう)する「[麺](めん)つゆ」に[絞](しぼ)って[実験](じっけん)が[行](おこな)われた。","sentence_vi":"Nỗ lực này trước tiên được thử nghiệm trên hai mặt hàng: \\"đậu phụ\\", loại không bảo quản lâu được và chịu ảnh hưởng lớn của thời tiết đến doanh số, và \\"nước tương mì\\", loại có nhu cầu tập trung vào một mùa nhất định."},{"no":51,"options":["[期待](きたい)できるからだ","[期待](きたい)できそうだ","[期待](きたい)できるはずだった","[期待](きたい)できればよかった"],"answer":1,"grammar":"V_ます_+そうだ","grammar_vi":"Có vẻ sẽ/sắp ~ (phán đoán từ vẻ bên ngoài)","sentence":"[今後](こんご)、より[大](おお)きな[成果](せいか)が**[期待](きたい)できそうだ**。","sentence_vi":"Từ nay về sau, có vẻ có thể kỳ vọng những thành quả lớn hơn."}],"translation_vi":"Trong cuộc sống hằng ngày, dự báo thời tiết là một thông tin không thể thiếu. Khi chọn quần áo mặc hay khi lên kế hoạch ngày nghỉ, thời tiết đều là điều người ta để ý. Chắc cũng nhiều người kiểm tra thông tin thời tiết mỗi sáng.\\n\\nMột nỗ lực mới tận dụng dự báo thời tiết như vậy đã bắt đầu. Đó là dự báo nhu cầu thực phẩm ở mức cao từ thông tin khí tượng để giảm \\"lãng phí thực phẩm\\", tức thực phẩm vẫn ăn được mà bị vứt bỏ. Trong số thực phẩm, có nhiều loại có nhu cầu bị thời tiết, nhiệt độ chi phối mạnh. Nếu dự báo nhu cầu sai và sản xuất quá mức thì sẽ phát sinh nhiều lãng phí thực phẩm tương ứng. Vì vậy, chính phủ đã bắt đầu một nỗ lực dự báo nhu cầu ở mức cao từ dữ liệu khí tượng và dữ liệu POS (thông tin bán hàng cho biết cái gì, khi nào, bao nhiêu, giá bao nhiêu) rồi cung cấp cho các công ty sản xuất và bán hàng. Kết quả không chỉ giảm được lãng phí thực phẩm. Vì thực phẩm bị vứt bỏ vô ích ít đi nên cũng có thể giảm khí carbon dioxide phát sinh trong quá trình xử lý.\\n\\nNỗ lực này trước tiên được thử nghiệm trên hai mặt hàng: \\"đậu phụ\\", loại không bảo quản lâu được và chịu ảnh hưởng lớn của thời tiết đến doanh số, và \\"nước tương mì (mentsuyu)\\", loại có nhu cầu tập trung vào một mùa nhất định. Kết quả cho thấy có thể giảm 20–30% lãng phí thực phẩm. Hiện nay, người ta mở rộng các mặt hàng áp dụng, đưa cả trí tuệ nhân tạo vào, và nghe nói việc dự báo nhu cầu ở mức cao hơn nữa đang trở nên khả thi. Như vậy, thông tin khí tượng không thể thiếu trong đời sống chúng ta cũng đang góp phần giải quyết vấn đề lãng phí thực phẩm. Từ nay về sau, có vẻ có thể kỳ vọng những thành quả lớn hơn."},{"paragraphs":["[今回](こんかい)、[留学生](りゅうがくせい)センターで[行](おこな)われた[文化](ぶんか)[体験](たいけん)のテーマは「[落語](らくご)」だった。[落語](らくご)は[日本](にほん)の[伝統](でんとう)[的](てき)な[芸能](げいのう)の[一](ひと)つだ。[着物](きもの)を[着](き)た[落語](らくご)[家](か)が[舞台](ぶたい)に[正座](せいざ)したまま、[一人](ひとり)で[何役](なんやく)も[演](えん)じ、[語](かた)って[聞](き)かせる。たいていは、[面白](おもしろ)く、おかしい[話](はなし)だ。[私](わたし)の[国](くに)には[演劇](えんげき)はあるが、[落語](らくご)のようなものはない。[私](わたし)は、[文化](ぶんか)[体験](たいけん)が[落語](らくご)だと[知](し)って、[実](じつ)はがっかりした。[以前](いぜん)、ある[落語](らくご)を[授業](じゅぎょう)で[読](よ)んだが、あまり[面白](おもしろ)いと（48）。[話](はなし)をただ[聞](き)いているのは[退屈](たいくつ)だろうと[思](おも)ったし、[聞](き)き[取](と)れるかどうかも[不安](ふあん)だった。","（49）[落語](らくご)を[聞](き)いている[間](ま)、[私](わたし)はよく[笑](わら)った。[落語](らくご)[家](か)の[動作](どうさ)や[声](こえ)の[出](だ)し[方](かた)は[本当](ほんとう)に[面白](おもしろ)くて、[場面](ばめん)の[様子](ようす)もよくわかった。しぐさや[話](はな)し[方](かた)を[変](か)えて、[親](おや)と[子供](こども)など[二](に)[役](やく)[以上](いじょう)を[一人](ひとり)で[演](えん)じ、[会話](かいわ)を[進](すす)める。[座](すわ)ったまま[体](からだ)を[揺](ゆ)らして[歩](ある)いている[様子](ようす)を[見](み)せ、[家](いえ)から[店](みせ)に[移動](いどう)したことを[表](あらわ)す。[食事](しょくじ)の[動作](どうさ)は、[本当](ほんとう)に[何](なに)かを[食](た)べているようだった。[文化](ぶんか)[体験](たいけん)が[終](お)わったとき、[落語](らくご)の[印象](いんしょう)がすっかり[変](か)わっていた。[落語](らくご)とは、[落語](らくご)[家](か)の[動作](どうさ)と[語](かた)りを[同時](どうじ)に（50）。","[私](わたし)は、[話](はなし)の[細部](さいぶ)は[理解](りかい)できていなかったかもしれない。しかし、[落語](らくご)[家](か)の[動作](どうさ)と[語](かた)りを[通](とお)して、[登場](とうじょう)[人物](じんぶつ)の[性格](せいかく)や[暮](く)らしが[感](かん)じられた。それに、[映像](えいぞう)や[音楽](おんがく)や[踊](おど)りがなくても、[生](い)き[生](い)きと[話](はなし)を[伝](つた)え、[人](ひと)を[笑](わら)わせられる[落語](らくご)[家](か)の[表現](ひょうげん)[力](りょく)にも[感動](かんどう)した。[落語](らくご)には、[怖](こわ)い[話](はなし)や[感動](かんどう)[的](てき)な[話](はなし)もあるそうだ。[落語](らくご)[家](か)は（51）をするのだろうか。ぜひいろいろな[落語](らくご)を[聞](き)いてみたい。"],"questions":[{"no":48,"options":["[思](おも)えなかったまでだ","[思](おも)えなかったほどだ","[思](おも)えなかっただけだ","[思](おも)えなかったからだ"],"answer":3,"grammar":"Thể thường+からだ","grammar_vi":"Là vì ~ (nêu lý do cho câu trước)","sentence":"[以前](いぜん)、ある[落語](らくご)を[授業](じゅぎょう)で[読](よ)んだが、あまり[面白](おもしろ)いと**[思](おも)えなかったからだ**。","sentence_vi":"Trước đây tôi đã đọc một truyện rakugo trong giờ học, nhưng không thấy thú vị lắm."},{"no":49,"options":["しかも","すなわち","ところが","したがって"],"answer":2,"grammar":"ところが","grammar_vi":"Thế nhưng (kết quả trái với dự đoán)","sentence":"**ところが**[落語](らくご)を[聞](き)いている[間](ま)、[私](わたし)はよく[笑](わら)った。","sentence_vi":"Thế nhưng, trong lúc nghe rakugo, tôi đã cười rất nhiều."},{"no":50,"options":["[楽](たの)しむものなのだ","[楽](たの)しむはずなのだ","[楽](たの)しむようにするのだ","[楽](たの)しむことになったのだ"],"answer":0,"grammar":"Vる+ものなのだ","grammar_vi":"Vốn là thứ để ~, đó là điều ~ (giải thích bản chất)","sentence":"[落語](らくご)とは、[落語](らくご)[家](か)の[動作](どうさ)と[語](かた)りを[同時](どうじ)に**[楽](たの)しむものなのだ**。","sentence_vi":"Rakugo là thứ để thưởng thức đồng thời động tác và lời kể của nghệ nhân."},{"no":51,"options":["どんな[表現](ひょうげん)","その[表現](ひょうげん)","[表現](ひょうげん)","こういう[表現](ひょうげん)"],"answer":0,"grammar":"どんな+N(nghi vấn)","grammar_vi":"N như thế nào (câu hỏi)","sentence":"[落語](らくご)[家](か)は**どんな[表現](ひょうげん)**をするのだろうか。","sentence_vi":"Không biết nghệ nhân rakugo sẽ biểu diễn kiểu diễn đạt như thế nào."}],"translation_vi":"Lần này chủ đề trải nghiệm văn hóa được tổ chức tại Trung tâm Du học sinh là \\"rakugo\\". Rakugo là một loại hình nghệ thuật biểu diễn truyền thống của Nhật. Nghệ nhân mặc kimono ngồi quỳ trên sân khấu, một mình đóng nhiều vai và kể chuyện. Hầu hết là những câu chuyện hài hước, buồn cười. Ở nước tôi có kịch nhưng không có thứ gì như rakugo. Khi biết trải nghiệm văn hóa là rakugo, thật ra tôi đã thất vọng. Vì trước đây tôi đã đọc một truyện rakugo trong giờ học, nhưng không thấy thú vị lắm. Tôi nghĩ chỉ ngồi nghe kể chuyện thì sẽ chán, và cũng lo không nghe hiểu nổi.\\n\\nThế nhưng, trong lúc nghe rakugo, tôi đã cười rất nhiều. Động tác và cách phát âm của nghệ nhân thật sự rất thú vị và tôi cũng hiểu rõ khung cảnh. Thay đổi cử chỉ và cách nói, một mình đóng từ hai vai trở lên như cha và con để dẫn dắt hội thoại. Ngồi nguyên chỗ nhưng lắc người để thể hiện dáng đi, biểu thị việc di chuyển từ nhà đến cửa hàng. Động tác ăn uống trông như thật sự đang ăn gì đó. Khi buổi trải nghiệm kết thúc, ấn tượng của tôi về rakugo đã hoàn toàn thay đổi. Rakugo là thứ để thưởng thức đồng thời động tác và lời kể của nghệ nhân.\\n\\nCó thể tôi đã không hiểu hết các chi tiết của câu chuyện. Nhưng qua động tác và lời kể của nghệ nhân, tôi cảm nhận được tính cách và cuộc sống của các nhân vật. Hơn nữa, tôi cũng cảm động trước khả năng biểu đạt của nghệ nhân, người dù không có hình ảnh, âm nhạc hay múa vẫn truyền tải câu chuyện sinh động và làm người ta cười. Nghe nói rakugo cũng có những chuyện đáng sợ và cảm động. Không biết nghệ nhân sẽ biểu diễn kiểu diễn đạt như thế nào. Tôi nhất định muốn nghe thử nhiều loại rakugo.","title":"「[落語](らくご)」[体験](たいけん)"},{"paragraphs":["[誰](だれ)もが[安全](あんぜん)に、そして[快適](かいてき)に[暮](く)らせる[街](まち)をつくるため、[各](かく)[自治体](じちたい)はさまざまな[取](と)り[組](く)みを[行](おこな)っている。[特](とく)に[都市](とし)[部](ぶ)において、[駅](えき)[周辺](しゅうへん)の[整備](せいび)は[重要](じゅうよう)な[課題](かだい)となる。[今回](こんかい)[取](と)り[上](あ)げるのは、[自転車](じてんしゃ)の[駐](ちゅう)[輪](わ)（48）。[多](おお)くの[駅](えき)には[駐輪場](ちゅうりんじょう)が[設置](せっち)されているが、スペースには[限](かぎ)りがある。[駐輪場](ちゅうりんじょう)を[利用](りよう)できない[人](ひと)が[多](おお)くなると、[道路](どうろ)や[歩道](ほどう)など[許可](きょか)されていない[場所](ばしょ)に[置](お)かれる[自転車](じてんしゃ)が[増](ふ)え、[車両](しゃりょう)や[歩行](ほこう)[者](しゃ)の[通行](つうこう)の[妨](さまた)げになってしまう。","そこで[有効](ゆうこう)になるのが[地下](ちか)[空間](くうかん)の[利用](りよう)だ。[地下](ちか)に[駐輪場](ちゅうりんじょう)があること[自体](じたい)はそれほど[珍](めずら)しくない。だが[最近](さいきん)では、[新](あたら)しいタイプの[地下](ちか)[駐輪場](ちゅうりんじょう)も[見](み)られる。それは、[地下](ちか)に（49）。[全](ぜん)[自動](じどう)[式](しき)の[地下](ちか)[駐輪場](ちゅうりんじょう)なのだ。[自転車](じてんしゃ)だけを[運](はこ)ぶエレベーターが[設置](せっち)されており、[地上](ちじょう)で[自転車](じてんしゃ)をエレベーターに[乗](の)せてボタンを[押](お)すと、[機械](きかい)によって[地下](ちか)の[駐](ちゅう)[輪](わ)スペースへと[運](はこ)ばれる。そして、[機械](きかい)が[判断](はんだん)して[空](あ)いている[場所](ばしょ)へ[収納](しゅうのう)してくれる。[取](と)り[出](だ)すときも、[暗証](あんしょう)[番号](ばんごう)を[入力](にゅうりょく)すれば、[機械](きかい)が[地上](ちじょう)へ[運](はこ)んできてくれる。","（50）にはさまざまなメリットがある。たとえば、[出](だ)し[入](い)れの[手軽](てがる)さだ。[荷物](にもつ)が[多](おお)い[人](ひと)や[子供](こども)[連](づ)れにとっては、[駐輪場](ちゅうりんじょう)の[中](なか)を[移動](いどう)せずに[自転車](じてんしゃ)を[取](と)り[出](だ)せるというのは[非常](ひじょう)に[便利](べんり)だ。また、[人](ひと)が[出入](でい)りしないので、[盗難](とうなん)の[心配](しんぱい)もない。[駐輪場](ちゅうりんじょう)[不足](ふそく)を[解決](かいけつ)し、より[快適](かいてき)で[安全](あんぜん)な[街](まち)に（51）、[全](ぜん)[自動](じどう)[式](しき)の[地下](ちか)[駐輪場](ちゅうりんじょう)の[設置](せっち)は[有効](ゆうこう)な[手段](しゅだん)の[一](ひと)つだといえる。[今後](こんご)も[増](ふ)えていきそうだ。"],"questions":[{"no":48,"options":["[問題](もんだい)だろう","[問題](もんだい)である","[問題](もんだい)とのことだ","[問題](もんだい)ではないか"],"answer":1,"grammar":"Nである","grammar_vi":"Là ~ (cách nói văn viết của だ)","sentence":"[今回](こんかい)[取](と)り[上](あ)げるのは、[自転車](じてんしゃ)の[駐](ちゅう)[輪](わ)**[問題](もんだい)である**。","sentence_vi":"Vấn đề tôi nêu lần này là việc gửi xe đạp."},{"no":49,"options":["つくられているにすぎない","つくられているに[違](ちが)いない","つくられているといってもよい","つくられているというだけではない"],"answer":3,"grammar":"Thể thường+というだけではない","grammar_vi":"Không chỉ đơn thuần là ~ (mà còn ~)","sentence":"それは、[地下](ちか)に**つくられているというだけではない**。","sentence_vi":"Điều đó không chỉ đơn thuần là được xây dưới lòng đất."},{"no":50,"options":["[駐輪場](ちゅうりんじょう)","ある[駐輪場](ちゅうりんじょう)","このような[駐輪場](ちゅうりんじょう)","そこの[駐輪場](ちゅうりんじょう)"],"answer":2,"grammar":"このような+N","grammar_vi":"N như thế này (chỉ điều vừa nêu ở trước)","sentence":"**このような[駐輪場](ちゅうりんじょう)**にはさまざまなメリットがある。","sentence_vi":"Loại bãi giữ xe như thế này có nhiều ưu điểm."},{"no":51,"options":["しても","するために","なったように","なってはじめて"],"answer":1,"grammar":"Vる+ために","grammar_vi":"Để ~ (mục đích)","sentence":"[駐輪場](ちゅうりんじょう)[不足](ふそく)を[解決](かいけつ)し、より[快適](かいてき)で[安全](あんぜん)な[街](まち)に**するために**、[全](ぜん)[自動](じどう)[式](しき)の[地下](ちか)[駐輪場](ちゅうりんじょう)の[設置](せっち)は[有効](ゆうこう)な[手段](しゅだん)の[一](ひと)つだといえる。","sentence_vi":"Có thể nói việc lắp đặt bãi giữ xe ngầm hoàn toàn tự động là một biện pháp hiệu quả để giải quyết tình trạng thiếu chỗ gửi xe và biến thành phố thành nơi thoải mái, an toàn hơn."}],"translation_vi":"Để xây dựng những thành phố mà ai cũng sống an toàn và thoải mái, các chính quyền địa phương đang thực hiện nhiều nỗ lực. Đặc biệt ở khu đô thị, việc chỉnh trang khu vực quanh nhà ga là một vấn đề quan trọng. Vấn đề tôi nêu lần này là việc gửi xe đạp. Nhiều nhà ga có bãi giữ xe nhưng không gian có hạn. Khi nhiều người không dùng được bãi giữ xe, xe đạp để ở những nơi không được phép như đường, vỉa hè tăng lên và cản trở xe cộ, người đi bộ.\\n\\nVì vậy, việc tận dụng không gian ngầm trở nên hiệu quả. Bản thân việc có bãi giữ xe dưới lòng đất không quá hiếm. Nhưng gần đây cũng thấy loại bãi giữ xe ngầm kiểu mới. Điều đó không chỉ đơn thuần là được xây dưới lòng đất. Đó là bãi giữ xe ngầm hoàn toàn tự động. Có thang máy chỉ chở xe đạp; đặt xe đạp lên thang máy trên mặt đất rồi bấm nút thì máy sẽ chở xuống khu giữ xe dưới lòng đất. Rồi máy tự phán đoán và cất xe vào chỗ trống. Khi lấy ra cũng vậy, nhập mật mã thì máy sẽ đưa lên mặt đất.\\n\\nLoại bãi giữ xe như thế này có nhiều ưu điểm. Chẳng hạn là sự tiện lợi khi gửi và lấy xe. Đối với người mang nhiều đồ hay đi cùng trẻ nhỏ, việc lấy được xe đạp mà không phải di chuyển trong bãi là cực kỳ tiện. Ngoài ra, vì không có người ra vào nên cũng không lo trộm cắp. Có thể nói việc lắp đặt bãi giữ xe ngầm hoàn toàn tự động là một biện pháp hiệu quả để giải quyết tình trạng thiếu chỗ gửi xe và biến thành phố thành nơi thoải mái, an toàn hơn. Có vẻ từ nay số lượng này sẽ còn tăng.","title":"[地下](ちか)[駐輪場](ちゅうりんじょう)"},{"paragraphs":["[現代](げんだい)[人](じん)は[座](すわ)りすぎだとよく[言](い)われます。[皆](みな)がずっと[席](せき)に[座](すわ)ってパソコンで[作業](さぎょう)をしているという[職場](しょくば)も[珍](めずら)しくないのではないでしょうか。[座](すわ)りすぎが[様々](さまざま)な[体](からだ)の[不調](ふちょう)の[原因](げんいん)になるという[研究](けんきゅう)[報告](ほうこく)も（48）。[座](すわ)りすぎは、[日本人](にほんじん)の4[人](にん)に1[人](にん)が[抱](かか)えているという[腰](こし)の[痛](いた)みの[原因](げんいん)にもなると[考](かんが)えられています。[座](すわ)っている[姿勢](しせい)は[体](からだ)にあまり[負担](ふたん)がかかっていないと[思](おも)うかもしれません。（49）、[座](すわ)り[方](かた)によっては、[実](じつ)は[立](た)っているときの2[倍](ばい)もの[負担](ふたん)が[腰](こし)にかかるのだそうです。[座](すわ)っている[時間](じかん)が[長](なが)くなるほど、[腰](こし)への[負担](ふたん)も[大](おお)きくなり、それが[腰痛](ようつう)につながります。","かといって、ずっと[立](た)ったまま[仕事](しごと)をするというのも[現実](げんじつ)[的](てき)ではありません。[長時間](ちょうじかん)[立](た)っていると、[足](あし)に[疲](つか)れがたまってしまうという[問題](もんだい)もあります。[大切](たいせつ)なのは、（50）[姿勢](しせい)を[長](なが)く[続](つづ)けないことです。[理想](りそう)は30[分](ふん)に1[回](かい)、[少](すく)なくとも1[時間](じかん)に1[回](かい)[立](た)って、[少](すこ)し[動](うご)くのがいいとされています。[実際](じっさい)に、[仕事](しごと)[中](ちゅう)に[時々](ときどき)[立](た)って[動](うご)くようにしてみた[人](ひと)の[多](おお)くが、[腰痛](ようつう)の[改善](かいぜん)や[疲](つか)れを[感](かん)じにくいといった[効果](こうか)を[感](かん)じているようです。[座](すわ)りっぱなしを[避](さ)け、[時々](ときどき)[立](た)って[体](からだ)を[動](うご)かすことは、[気軽](きがる)にできる[腰痛](ようつう)[対策](たいさく)であり、[仕事](しごと)[中](ちゅう)の[集中](しゅうちゅう)[力](りょく)[維持](いじ)にもつながります。[職場](しょくば)で[座](すわ)っている[時間](じかん)が[長](なが)い[人](ひと)は、（51）。"],"questions":[{"no":48,"options":["[増](ふ)えそうでした","[増](ふ)えてきました","[増](ふ)えていきました","[増](ふ)えたところでした"],"answer":1,"grammar":"Vてくる","grammar_vi":"Dần dần trở nên ~","sentence":"[座](すわ)りすぎが[様々](さまざま)な[体](からだ)の[不調](ふちょう)の[原因](げんいん)になるという[研究](けんきゅう)[報告](ほうこく)も**[増](ふ)えてきました**。","sentence_vi":"Các báo cáo nghiên cứu cho rằng ngồi quá nhiều là nguyên nhân của nhiều rối loạn cơ thể cũng ngày càng tăng."},{"no":49,"options":["つもり","しかも","ところが","というのは"],"answer":2,"grammar":"ところが","grammar_vi":"Thế nhưng (kết quả trái với dự đoán)","sentence":"**ところが**、[座](すわ)り[方](かた)によっては、[実](じつ)は[立](た)っているときの2[倍](ばい)もの[負担](ふたん)が[腰](こし)にかかるのだそうです。","sentence_vi":"Thế nhưng, tùy cách ngồi, thực ra lưng phải chịu gánh nặng gấp 2 lần so với khi đứng."},{"no":50,"options":["[同](おな)じ","[違](ちが)う","この","[以下](いか)の"],"answer":0,"grammar":"同じ+N","grammar_vi":"N giống nhau, cùng một N","sentence":"[大切](たいせつ)なのは、**[同](おな)じ**[姿勢](しせい)を[長](なが)く[続](つづ)けないことです。","sentence_vi":"Điều quan trọng là không giữ lâu cùng một tư thế."},{"no":51,"options":["[試](ため)してもいいですか","[試](ため)したらいいのでしょうか","[試](ため)してみればよかったですか","[試](ため)してみてはいかがでしょうか"],"answer":3,"grammar":"Vてみてはいかがでしょうか","grammar_vi":"Anh/chị thử ~ xem sao ạ? (gợi ý lịch sự)","sentence":"[職場](しょくば)で[座](すわ)っている[時間](じかん)が[長](なが)い[人](ひと)は、**[試](ため)してみてはいかがでしょうか**。","sentence_vi":"Những người ngồi lâu ở nơi làm việc, bạn thử xem sao nhé?"}],"translation_vi":"Người ta thường nói người hiện đại ngồi quá nhiều. Chẳng phải cũng không hiếm những nơi làm việc mà mọi người cứ ngồi tại chỗ làm việc trên máy tính suốt sao? Các báo cáo nghiên cứu cho rằng ngồi quá nhiều là nguyên nhân của nhiều rối loạn cơ thể cũng ngày càng tăng. Ngồi quá nhiều cũng được cho là nguyên nhân của đau lưng, thứ mà 1 trong 4 người Nhật mắc phải. Có thể bạn nghĩ tư thế ngồi không gây nhiều gánh nặng cho cơ thể. Thế nhưng, tùy cách ngồi, thực ra lưng phải chịu gánh nặng gấp 2 lần so với khi đứng. Thời gian ngồi càng dài thì gánh nặng cho lưng càng lớn và dẫn đến đau lưng.\\n\\nNhưng cứ đứng làm việc suốt cũng không thực tế. Đứng lâu thì chân tích tụ mệt mỏi, đó cũng là một vấn đề. Điều quan trọng là không giữ lâu cùng một tư thế. Lý tưởng là cứ 30 phút một lần, ít nhất 1 giờ một lần đứng dậy và vận động một chút. Thực tế, nhiều người thử thỉnh thoảng đứng dậy vận động khi làm việc cảm thấy hiệu quả như cải thiện đau lưng và ít cảm thấy mệt. Tránh ngồi liên tục, thỉnh thoảng đứng dậy vận động là biện pháp phòng ngừa đau lưng dễ thực hiện, cũng giúp duy trì sự tập trung khi làm việc. Những người ngồi lâu ở nơi làm việc, bạn thử xem sao nhé?"},{"paragraphs":["「[香道](こうどう)」とは、[香](かお)りを[楽](たの)しむ[日本](にほん)の[伝統](でんとう)[文化](ぶんか)です。[私](わたし)は、[友人](ゆうじん)が[香道](こうどう)の[体験](たいけん)ができる[教室](きょうしつ)に[誘](さそ)ってくれたのをきっかけに、[初](はじ)めて[香道](こうどう)のことを[知](し)りました。[私](わたし)は[普段](ふだん)から[香水](こうすい)などで[香](かお)りを[楽](たの)しんでいるので、[香道](こうどう)の[体験](たいけん)も[楽](たの)しむことができました。","[香道](こうどう)は、「[香木](こうぼく)」と[呼](よ)ばれる[木](き)の[破片](はへん)を[熱](ねっ)し、その[香](かお)りを[楽](たの)しみます。「[香木](こうぼく)」（48）そのような[名前](なまえ)の[木](き)がもともと[存在](そんざい)するわけではありません。いくつかの[種類](しゅるい)の[木](き)の[中](なか)で、[様々](さまざま)な[自然](しぜん)[条件](じょうけん)のもとで、[年月](としつき)の[経過](けいか)によって[香](かお)りを[発生](はっせい)させるようになった[木](き)をそう[呼](よ)びます。[人工](じんこう)[的](てき)に[生産](せいさん)できないため、[大変](たいへん)[貴重](きちょう)なものと（49）。[香道](こうどう)には600[年](ねん)[以上](いじょう)の[歴史](れきし)がありますが、その[存在](そんざい)はあまり[知](し)られていません。[数](かず)に[限](かぎ)りがある[香木](こうぼく)は、[香道](こうどう)が[広](ひろ)まり[需要](じゅよう)が[増](ふ)えすぎればなくなるおそれもあります。（50）、[香道](こうどう)ではあまり[多](おお)くの[弟子](でし)を[受](う)け[入](い)れませんでした。[香道](こうどう)がよく[知](し)られていないのは、そういった[事情](じじょう)もあるそうです。","[香道](こうどう)では、[香](かお)りをかいで、じっくりと[味](あじ)わうことを「[香](かお)りを[聞](き)く」と[言](い)います。[香](かお)りに[心](こころ)を[傾](かたむ)けて[聞](き)くことを[基本](きほん)に、[香](かお)りを[聞](き)きながら[古典](こてん)[文学](ぶんがく)を[鑑賞](かんしょう)したり、どれがどの[香木](こうぼく)の[香](かお)りかを[当](あ)てて[楽](たの)しんだりもします。[繊細](せんさい)な[香](かお)りを[心](こころ)の[中](なか)でゆっくり[味](あじ)わうことを[通](とお)して、[私](わたし)は「[香](かお)りを[聞](き)く」という[意味](いみ)がわかったような[気](き)がしました。[香水](こうすい)のように[手軽](てがる)ではありませんが、このような[香](かお)りの[楽](たの)しみ[方](かた)も（51）。"],"questions":[{"no":48,"options":["のように","のほかに","といっても","であっても"],"answer":2,"grammar":"~といっても","grammar_vi":"Dù nói là ~ nhưng (thực ra có nhiều loại)","sentence":"「[香木](こうぼく)」**といっても**そのような[名前](なまえ)の[木](き)がもともと[存在](そんざい)するわけではありません。","sentence_vi":"Nói là \\"kōboku\\" nhưng vốn dĩ không có loại cây nào có tên như vậy."},{"no":49,"options":["しておきます","されています","しておく[点](てん)です","されている[点](てん)です"],"answer":1,"grammar":"~とされている","grammar_vi":"Được cho là ~, được coi là ~","sentence":"[人工](じんこう)[的](てき)に[生産](せいさん)できないため、[大変](たいへん)[貴重](きちょう)なものと**されています**。","sentence_vi":"Vì không thể sản xuất nhân tạo nên nó được coi là vô cùng quý giá."},{"no":50,"options":["[一方](いっぽう)","ちなみに","ところが","そのため"],"answer":3,"grammar":"そのため","grammar_vi":"Vì vậy, do đó (nêu kết quả)","sentence":"**そのため**、[香道](こうどう)ではあまり[多](おお)くの[弟子](でし)を[受](う)け[入](い)れませんでした。","sentence_vi":"Vì vậy, hương đạo đã không nhận nhiều đệ tử."},{"no":51,"options":["いいものだと[思](おも)います","いいと[思](おも)ったのでしょう","よかったはずです","よかったのではありません"],"answer":0,"grammar":"~ものだと思う","grammar_vi":"Nghĩ rằng đó là điều ~ (nhận xét cảm nhận)","sentence":"[香水](こうすい)のように[手軽](てがる)ではありませんが、このような[香](かお)りの[楽](たの)しみ[方](かた)も**いいものだと[思](おも)います**。","sentence_vi":"Tuy không tiện như nước hoa, nhưng tôi nghĩ cách thưởng thức hương thơm như vậy cũng thật tuyệt."}],"translation_vi":"\\"Kōdō\\" (hương đạo) là văn hóa truyền thống của Nhật để thưởng thức hương thơm. Nhờ người bạn rủ đến một lớp học có thể trải nghiệm hương đạo, tôi lần đầu biết về hương đạo. Vì bình thường tôi đã thưởng thức hương thơm bằng nước hoa..., nên tôi cũng thưởng thức được trải nghiệm hương đạo.\\n\\nHương đạo là thưởng thức mùi hương bằng cách đốt nóng mảnh gỗ gọi là \\"kōboku\\" (hương mộc). Nói là \\"kōboku\\" nhưng vốn dĩ không có loại cây nào có tên như vậy. Trong số một vài loại cây, loại cây phát ra hương thơm sau thời gian dài dưới nhiều điều kiện tự nhiên khác nhau thì được gọi như vậy. Vì không thể sản xuất nhân tạo nên nó được coi là vô cùng quý giá. Hương đạo có lịch sử hơn 600 năm nhưng sự tồn tại của nó ít được biết đến. Hương mộc có số lượng hạn chế, nếu hương đạo lan rộng làm nhu cầu tăng quá mức thì có nguy cơ cạn kiệt. Vì vậy, hương đạo đã không nhận nhiều đệ tử. Nghe nói việc hương đạo ít được biết đến cũng có phần do hoàn cảnh như vậy.\\n\\nTrong hương đạo, việc ngửi mùi hương và thưởng thức kỹ lưỡng được gọi là \\"nghe hương\\". Lấy cơ bản là dồn tâm vào để nghe hương, người ta còn vừa nghe hương vừa thưởng thức văn học cổ điển, hay đoán xem mùi nào là của loại hương mộc nào để vui chơi. Qua việc thong thả thưởng thức hương thơm tinh tế trong lòng, tôi có cảm giác như đã hiểu ý nghĩa của \\"nghe hương\\". Tuy không tiện như nước hoa, nhưng tôi nghĩ cách thưởng thức hương thơm như vậy cũng thật tuyệt.","title":"[香道](こうどう)"},{"paragraphs":["[疲](つか)れを[感](かん)じた[時](とき)、[温泉](おんせん)に[行](い)きたくなるという[人](ひと)も[多](おお)いのではないでしょうか。ただ、[温泉](おんせん)に[入](はい)って、[元気](げんき)になるどころか、[逆](ぎゃく)に[疲](つか)れてしまったという[声](こえ)を[聞](き)くことも[少](すく)なくありません。（48）[温泉](おんせん)は[入](はい)り[方](かた)を[間違](まちが)えると[体](からだ)に[負担](ふたん)をかけてしまうのです。","[体](からだ)に[負担](ふたん)をかけないためにまずしてほしいのは、お[湯](ゆ)に[入](はい)る[前](まえ)に[丁寧](ていねい)に「かけ[湯](ゆ)」をすることです。[心臓](しんぞう)から[遠](とお)い[足](あし)[先](さき)などから[温泉](おんせん)のお[湯](ゆ)をゆっくり、たっぷりかけていきましょう。「かけ[湯](ゆ)」には、お[湯](ゆ)の[温度](おんど)や[温泉](おんせん)の[成分](せいぶん)に[体](からだ)を[慣](な)れさせるといった[重要](じゅうよう)な[役割](やくわり)があります。お[湯](ゆ)に[入](はい)る[前](まえ)には[必](かなら)ず「かけ[湯](ゆ)」を（49）。","そして、お[湯](ゆ)に[入](はい)っている[時間](じかん)にも[注意](ちゅうい)が[必要](ひつよう)です。お[湯](ゆ)に[入](はい)っている[時間](じかん)はぬるく[感](かん)じるお[湯](ゆ)でも20[分](ふん)[程度](ていど)、[熱](あつ)いお[湯](ゆ)なら3〜5[分](ふん)[程度](ていど)にするのが[良](よ)いと[言](い)われています。また、[1日](ついたち)に[何度](なんど)も[温泉](おんせん)に[入](はい)るのもあまり[良](よ)くありません。[1日](ついたち)に1、2[回](かい)、[多](おお)くても3[回](かい)[程度](ていど)にしておきましょう。[温泉](おんせん)の[成分](せいぶん)が[肌](はだ)に[負担](ふたん)を（50）。ですから、[刺激](しげき)の[強](つよ)い[酸性](さんせい)の[温泉](おんせん)に[入](はい)った[時](とき)や、[肌](はだ)への[刺激](しげき)が[強](つよ)いと[感](かん)じた[時](とき)は、[最後](さいご)に[温泉](おんせん)ではないお[湯](ゆ)や[水](みず)を[体](からだ)にかけ、[肌](はだ)に[残](のこ)った[温泉](おんせん)の[成分](せいぶん)を[流](なが)しましょう。なお、[肌](はだ)への[刺激](しげき)が[強](つよ)くなければ、[流](なが)さないほうが[温泉](おんせん)の[成分](せいぶん)が[肌](はだ)に[残](のこ)るのでおすすめです。せっかく[疲](つか)れを[取](と)りに[温泉](おんせん)に[行](い)ったのに、（51）もったいないですよね。[正](ただ)しい[入](はい)り[方](かた)で[日](ひ)ごろの[疲](つか)れが[取](と)れますように。"],"questions":[{"no":48,"options":["[実](じつ)は","[一方](いっぽう)で","しかも","ちなみに"],"answer":0,"grammar":"実は","grammar_vi":"Thực ra là, sự thật là","sentence":"**[実](じつ)は**[温泉](おんせん)は[入](はい)り[方](かた)を[間違](まちが)えると[体](からだ)に[負担](ふたん)をかけてしまうのです。","sentence_vi":"Thực ra, nếu tắm suối nước nóng sai cách thì sẽ gây gánh nặng cho cơ thể."},{"no":49,"options":["するからです","するのでしょう","するつもりです","するようにしてください"],"answer":3,"grammar":"Vる+ようにしてください","grammar_vi":"Hãy cố gắng ~, hãy nhớ ~ (yêu cầu nhắc nhở)","sentence":"お[湯](ゆ)に[入](はい)る[前](まえ)には[必](かなら)ず「かけ[湯](ゆ)」を**するようにしてください**。","sentence_vi":"Trước khi vào nước nóng, hãy nhớ nhất định phải \\"kakeyu\\" (dội nước)."},{"no":50,"options":["かけたとします","かけることもあります","かけたと[思](おも)います","かけることにあります"],"answer":1,"grammar":"Vる+こともある","grammar_vi":"Cũng có khi ~","sentence":"[温泉](おんせん)の[成分](せいぶん)が[肌](はだ)に[負担](ふたん)を**かけることもあります**。","sentence_vi":"Đôi khi thành phần của suối nước nóng cũng gây gánh nặng cho da."},{"no":51,"options":["[疲](つか)れてしまい","[疲](つか)れてしまったのが","[疲](つか)れてしまっては","[疲](つか)れてしまうばかりで"],"answer":2,"grammar":"Vてしまっては","grammar_vi":"Nếu lại ~ mất thì (thật đáng tiếc)","sentence":"せっかく[疲](つか)れを[取](と)りに[温泉](おんせん)に[行](い)ったのに、**[疲](つか)れてしまっては**もったいないですよね。","sentence_vi":"Mất công đi suối nước nóng để giải tỏa mệt mỏi mà lại bị mệt thêm thì thật uổng nhỉ."}],"translation_vi":"Khi cảm thấy mệt, chẳng phải cũng nhiều người muốn đi suối nước nóng sao? Nhưng không hiếm khi nghe nói tắm suối nước nóng xong chẳng những không khỏe lên mà ngược lại còn mệt hơn. Thực ra, nếu tắm suối nước nóng sai cách thì sẽ gây gánh nặng cho cơ thể.\\n\\nĐể không gây gánh nặng cho cơ thể, điều trước tiên tôi muốn bạn làm là dội nước kỹ (\\"kakeyu\\") trước khi vào bồn. Hãy dội từ từ, nhiều nước suối nóng bắt đầu từ những chỗ xa tim như đầu ngón chân. \\"Kakeyu\\" có vai trò quan trọng là làm cơ thể quen với nhiệt độ nước và thành phần của suối. Trước khi vào nước nóng, hãy nhớ nhất định phải \\"kakeyu\\".\\n\\nNgoài ra, cần chú ý cả thời gian ngâm trong nước. Người ta nói nên ngâm khoảng 20 phút với nước cảm thấy ấm, và khoảng 3–5 phút với nước nóng. Ngoài ra, tắm suối nóng nhiều lần trong một ngày cũng không tốt lắm. Hãy giữ ở mức 1–2 lần một ngày, nhiều nhất cũng khoảng 3 lần. Đôi khi thành phần của suối nước nóng cũng gây gánh nặng cho da. Vì vậy, khi tắm suối có tính axit mạnh hoặc khi cảm thấy da bị kích ứng mạnh, hãy dội nước nóng thường hoặc nước lạnh lên người cuối cùng để rửa sạch thành phần suối còn lại trên da. Còn nếu da không bị kích ứng mạnh thì không rửa sẽ giúp thành phần suối còn lại trên da nên được khuyên dùng. Mất công đi suối nước nóng để giải tỏa mệt mỏi mà lại bị mệt thêm thì thật uổng nhỉ. Mong rằng bạn sẽ giải tỏa được mệt mỏi thường ngày nhờ cách tắm đúng.","title":"[温泉](おんせん)の[正](ただ)しい[入](はい)り[方](かた)"},{"paragraphs":["[私](わたし)は[日本](にほん)の[秋](あき)の[景色](けしき)が[好](す)きです。[秋](あき)になって[紅葉](こうよう)が[始](はじ)まり、[緑](みどり)だった[葉](は)が[黄色](きいろ)やオレンジ、[赤](あか)に[変](か)わると、とてもきれいです。[秋](あき)の[紅葉](こうよう)は、[日本](にほん)の[四季](しき)の[変化](へんか)を[感](かん)じさせてくれるものです。（48）ですが、[先日](せんじつ)テレビで、[紅葉](こうよう)がピークを[迎](むか)える[時期](じき)が[年々](ねんねん)[遅](おそ)くなっているというニュースを[見](み)ました。[中](なか)には、1[月](がつ)になってからピークを[迎](むか)えたところもあるそうで、[驚](おどろ)きました。[温暖](おんだん)[化](か)によって[平均](へいきん)[気温](きおん)が[上昇](じょうしょう)していることが[大](おお)きな[原因](げんいん)だそうです。","[私](わたし)は、[夏](なつ)が[過](す)ぎて[気温](きおん)が[下](さ)がってくれば、[必](かなら)ず[紅葉](こうよう)が[始](はじ)まると[思](おも)っていました。（49）、そうではありませんでした。[紅葉](こうよう)には、[条件](じょうけん)となる[気温](きおん)の[変化](へんか)がありました。[葉](は)の[変色](へんしょく)が[始](はじ)まるのは、[1日](ついたち)の[最低](さいてい)[気温](きおん)が[大体](だいたい)8[度](ど)[以下](いか)になってからです。[秋](あき)になっても、[最低](さいてい)[気温](きおん)が[一定](いってい)の[気温](きおん)まで[下](さ)がらなければ、[紅葉](こうよう)は（50）。その[後](ご)、さらに[寒](さむ)くなり、5〜6[度](ど)まで[下](さ)がると、[紅葉](こうよう)は[一気](いっき)に[進](すす)みます。また、5[度](ど)[以下](いか)の[日](ひ)が[続](つづ)くと、[最](もっと)も[美](うつく)しい[紅葉](こうよう)が[見](み)られるといわれています。","[紅葉](こうよう)に[起](お)きている[異変](いへん)を[知](し)り、このまま[温暖](おんだん)[化](か)が[進](すす)むと、[日本](にほん)の[秋](あき)の[景色](けしき)が[変](か)わってしまう[可能](かのう)[性](せい)もあるのではないかと[思](おも)いました。もしかしたら、[紅葉](こうよう)[自体](じたい)が[見](み)られなくなる[日](ひ)も[来](く)るかもしれません。[紅葉](こうよう)を[通](とお)して、[温暖](おんだん)[化](か)が[身近](みぢか)な[問題](もんだい)であることをより[強](つよ)く（51）。"],"questions":[{"no":48,"options":["そこの[紅葉](こうよう)","そんな[紅葉](こうよう)","そちら","[紅葉](こうよう)"],"answer":1,"grammar":"そんな+N(chỉ thị)","grammar_vi":"N như vậy (chỉ điều vừa nêu ở trước)","sentence":"**そんな[紅葉](こうよう)**ですが、[先日](せんじつ)テレビで、[紅葉](こうよう)がピークを[迎](むか)える[時期](じき)が[年々](ねんねん)[遅](おそ)くなっているというニュースを[見](み)ました。","sentence_vi":"Lá đỏ như vậy, nhưng hôm trước tôi xem tin trên tivi nói rằng thời điểm lá đỏ đạt đỉnh đang muộn dần qua từng năm."},{"no":49,"options":["[結局](けっきょく)","[確](たし)かに","しかし","つまり"],"answer":2,"grammar":"しかし","grammar_vi":"Nhưng, tuy nhiên (nối hai câu đối lập)","sentence":"**しかし**、そうではありませんでした。","sentence_vi":"Tuy nhiên, không phải như vậy."},{"no":50,"options":["[始](はじ)まらないのです","[始](はじ)まらないためです","[始](はじ)まらないのでしょうか","[始](はじ)まらないためでしょうか"],"answer":0,"grammar":"Thể thường+のです(giải thích)","grammar_vi":"~ đấy, là vì ~ (giải thích lý do, tình huống)","sentence":"[秋](あき)になっても、[最低](さいてい)[気温](きおん)が[一定](いってい)の[気温](きおん)まで[下](さ)がらなければ、[紅葉](こうよう)は**[始](はじ)まらないのです**。","sentence_vi":"Dù đã sang thu, nếu nhiệt độ thấp nhất không giảm xuống một mức nhất định thì lá đỏ không bắt đầu."},{"no":51,"options":["[感](かん)じているからだと[思](おも)います","[感](かん)じられるところだと[思](おも)います","[感](かん)じさせることができました","[感](かん)じるようになりました"],"answer":3,"grammar":"Vるようになる","grammar_vi":"Trở nên có thể ~, dần dần ~ (Vるようになりたい = muốn trở nên có thể ~)","sentence":"[紅葉](こうよう)を[通](とお)して、[温暖](おんだん)[化](か)が[身近](みぢか)な[問題](もんだい)であることをより[強](つよ)く**[感](かん)じるようになりました**。","sentence_vi":"Qua lá đỏ, tôi đã trở nên cảm nhận mạnh mẽ hơn rằng nóng lên toàn cầu là vấn đề gần gũi."}],"translation_vi":"Tôi thích phong cảnh mùa thu của Nhật. Khi sang thu lá bắt đầu đỏ, lá xanh chuyển sang vàng, cam, đỏ thì rất đẹp. Lá đỏ mùa thu cho ta cảm nhận sự thay đổi của bốn mùa Nhật Bản. Lá đỏ như vậy, nhưng hôm trước tôi xem tin trên tivi nói rằng thời điểm lá đỏ đạt đỉnh đang muộn dần qua từng năm. Nghe nói có nơi mãi đến tháng 1 mới đạt đỉnh, tôi rất ngạc nhiên. Nghe nói nguyên nhân lớn là nhiệt độ trung bình tăng do nóng lên toàn cầu.\\n\\nTôi đã nghĩ rằng hễ hết mùa hè và nhiệt độ giảm xuống thì chắc chắn lá sẽ bắt đầu đỏ. Tuy nhiên, không phải như vậy. Lá đỏ có điều kiện là sự thay đổi nhiệt độ. Lá bắt đầu đổi màu sau khi nhiệt độ thấp nhất trong ngày xuống khoảng 8 độ trở xuống. Dù đã sang thu, nếu nhiệt độ thấp nhất không giảm xuống một mức nhất định thì lá đỏ không bắt đầu. Sau đó, khi lạnh hơn nữa và giảm xuống 5–6 độ thì lá đỏ tiến triển nhanh chóng. Ngoài ra, người ta nói nếu những ngày dưới 5 độ kéo dài thì có thể thấy lá đỏ đẹp nhất.\\n\\nBiết được sự bất thường đang xảy ra với lá đỏ, tôi nghĩ nếu nóng lên toàn cầu cứ tiến triển như vậy, có thể phong cảnh mùa thu Nhật Bản sẽ thay đổi. Biết đâu sẽ có ngày không còn thấy lá đỏ nữa. Qua lá đỏ, tôi đã trở nên cảm nhận mạnh mẽ hơn rằng nóng lên toàn cầu là vấn đề gần gũi.","title":"[紅葉](こうよう)の[異変](いへん)"},{"paragraphs":["[半年](はんとし)[前](まえ)、[私](わたし)は[友達](ともだち)に[誘](さそ)われて、[働](はたら)き[手](て)が[足](た)りない[農家](のうか)を[手伝](てつだ)う「[農業](のうぎょう)ボランティア」を[始](はじ)めた。[過去](かこ)にごみ[拾](ひろ)いなどのボランティアはしたことがあったが、[農業](のうぎょう)ボランティアのことは[友達](ともだち)に[聞](き)くまで[知](し)らなかった。[私](わたし)は[日本](にほん)でいろいろな[経験](けいけん)をしたいと[思](おも)っていたので、[参加](さんか)することにした。","[私](わたし)が[手伝](てつだ)っているのは[南](みなみ)さんという[農家](のうか)だ。40[代](だい)の[夫婦](ふうふ)がトマトやキャベツなど、いろいろな[野菜](やさい)を[作](つく)っている。[農作業](のうさぎょう)は[初](はじ)めての[経験](けいけん)だったが、[農業](のうぎょう)は[想像](そうぞう)していた[以上](いじょう)に[知識](ちしき)や[経験](けいけん)が[必要](ひつよう)だと[感](かん)じた。（48）、[収穫](しゅうかく)のタイミングは、[成長](せいちょう)の[具合](ぐあい)や[天気](てんき)[予報](よほう)をもとに、いつがいいかを[判断](はんだん)しなければならない。また、トマトなどは[成長](せいちょう)の[段階](だんかい)に[応](おう)じて[与](あた)える[水](みず)の[量](りょう)を[変](か)えないとしっかり[育](そだ)たない。[体力](たいりょく)（49）[必要](ひつよう)で、[農業](のうぎょう)は[本当](ほんとう)に[大変](たいへん)な[仕事](しごと)だ。[収穫](しゅうかく)したばかりのトマトを[初](はじ)めて[食](た)べさせてもらったときはあまりおいしくて（50）。[収穫](しゅうかく)したときの[達成](たっせい)[感](かん)や[大切](たいせつ)に[育](そだ)てた[野菜](やさい)を[味](あじ)わう[喜](よろこ)びは、このボランティアに[参加](さんか)しなければ[感](かん)じられなかっただろう。[農家](のうか)の[役](やく)に[立](た)てたことが[嬉](うれ)しかったし、[多](おお)くの[貴重](きちょう)な[経験](けいけん)をすることができた。このボランティアを（51）[本当](ほんとう)に[良](よ)かったと[思](おも)う。"],"questions":[{"no":48,"options":["[一方](いっぽう)","そして","[例](たと)えば","ただし"],"answer":2,"grammar":"たとえば","grammar_vi":"Ví dụ, chẳng hạn","sentence":"**[例](たと)えば**、[収穫](しゅうかく)のタイミングは、[成長](せいちょう)の[具合](ぐあい)や[天気](てんき)[予報](よほう)をもとに、いつがいいかを[判断](はんだん)しなければならない。","sentence_vi":"Chẳng hạn, về thời điểm thu hoạch, phải dựa vào mức độ sinh trưởng và dự báo thời tiết để phán đoán khi nào là tốt."},{"no":49,"options":["だけ","も","は","こそ"],"answer":1,"grammar":"Nも(thêm vào)","grammar_vi":"Cũng ~ (thêm vào điều đã nói)","sentence":"[体力](たいりょく)**も**[必要](ひつよう)で、[農業](のうぎょう)は[本当](ほんとう)に[大変](たいへん)な[仕事](しごと)だ。","sentence_vi":"Còn cần cả thể lực nữa, nông nghiệp thật sự là công việc vất vả."},{"no":50,"options":["[感動](かんどう)したことだ","[感動](かんどう)していた","[感動](かんどう)したはずだ","[感動](かんどう)してしまった"],"answer":1,"grammar":"Vていた(trạng thái)","grammar_vi":"Đang ở trạng thái ~ (vào lúc đó)","sentence":"[収穫](しゅうかく)したばかりのトマトを[初](はじ)めて[食](た)べさせてもらったときはあまりおいしくて**[感動](かんどう)していた**。","sentence_vi":"Lần đầu tôi được ăn quả cà chua vừa thu hoạch, ngon đến mức tôi xúc động."},{"no":51,"options":["やってみて","やってみても","やってみたら","やってみたから"],"answer":0,"grammar":"Vてみて","grammar_vi":"Sau khi thử ~ (thì thấy ~)","sentence":"このボランティアを**やってみて**[本当](ほんとう)に[良](よ)かったと[思](おも)う。","sentence_vi":"Tôi nghĩ thật sự tốt khi đã thử tham gia hoạt động tình nguyện này."}],"translation_vi":"Nửa năm trước, tôi được bạn rủ và bắt đầu \\"tình nguyện nông nghiệp\\", giúp đỡ những nông hộ thiếu nhân lực. Trước đây tôi từng làm tình nguyện như nhặt rác, nhưng không biết đến tình nguyện nông nghiệp cho đến khi nghe bạn nói. Vì tôi muốn có nhiều trải nghiệm ở Nhật nên đã quyết định tham gia.\\n\\nNgười tôi giúp là một nông hộ tên Minami. Hai vợ chồng ngoài 40 tuổi trồng nhiều loại rau như cà chua, bắp cải. Làm nông là lần đầu tiên, và tôi cảm thấy nông nghiệp cần nhiều kiến thức và kinh nghiệm hơn tôi tưởng. Chẳng hạn, về thời điểm thu hoạch, phải dựa vào mức độ sinh trưởng và dự báo thời tiết để phán đoán khi nào là tốt. Ngoài ra, cà chua... nếu không thay đổi lượng nước tưới theo giai đoạn phát triển thì không lớn tốt. Còn cần cả thể lực nữa, nông nghiệp thật sự là công việc vất vả. Lần đầu tôi được ăn quả cà chua vừa thu hoạch, ngon đến mức tôi xúc động. Cảm giác thành tựu khi thu hoạch và niềm vui thưởng thức rau mình chăm sóc cẩn thận, nếu không tham gia tình nguyện này chắc tôi đã không cảm nhận được. Tôi vui vì giúp ích được cho nông hộ và đã có nhiều trải nghiệm quý giá. Tôi nghĩ thật sự tốt khi đã thử tham gia hoạt động tình nguyện này.","title":"[農業](のうぎょう)ボランティア"},{"paragraphs":["[子供](こども)の[生活](せいかつ)から「[遊](あそ)び」をもぎ[取](と)ってしまったら、それはちょうど[羽根](はね)をむしり[取](と)られたトンボと[同](おな)じで、（18）。[羽根](はね)を[取](と)られたトンボは、[地面](じめん)をよたよたと[歩](ある)くことはできるかもしれぬが、[大空](おおぞら)を[自由](じゆう)に[飛](と)び[回](まわ)ることはできないだろう。","[子供](こども)たちは、[仲間](なかま)[同士](どうし)のあせまみれ、どろまみれの[遊](あそ)びの[中](なか)から、おのずと[人間](にんげん)の[心](こころ)の（19）、[友情](ゆうじょう)をつちかうのである。また、[想像](そうぞう)[力](りょく)もここで[発達](はったつ)するだろう。[何](なに)かおもしろいことはないか、こうしてみようああしてみようと、[常](つね)にくふうしない[限](かぎ)り、より[楽](たの)しい[遊](あそ)びは[得](え)られないし、[長続](ながつづ)きもしない。その[間](あいだ)に、[取](と)っ[組](く)み[合](あ)いのけんかもあるかも[知](し)れぬが、そのけんかがまた[大事](だいじ)なのだ。けんかぐらい、[子供](こども)の[感情](かんじょう)の[振幅](しんぷく)を（20）。","もう[一](ひと)つあげよう。[子供](こども)の[遊](あそ)びには、（21）、[自然](しぜん)がいる。[自然](しぜん)は[土](つち)によって[代表](だいひょう)される。その[中](なか)には、[小](ちい)さなありんこたちが[無数](むすう)に[穴](あな)をほり、あるいは[名](な)も[知](し)れぬ[芽](め)が、ひょっこり[顔](かお)をのぞかせるかも[知](し)れない。[子供](こども)たちは、ものごころつきはじめたころから、それら[自然](しぜん)の[生物](せいぶつ)たちとの[交流](こうりゅう)の[中](なか)で、やがて[生命](せいめい)の[尊](とうと)さというものを[学](まな)んでいくのではないか。わたしは、[子供](こども)のこのような（22）[真](しん)の[子供](こども)らしさではないかと[思](おも)っているし、これからも[大事](だいじ)に[育](そだ)てていきたいと[考](かんが)えている。"],"questions":[{"no":18,"options":["[子供](こども)っぽい","[子供](こども)むきではない","[子供](こども)ではない","[子供](こども)だらけだ"],"answer":2,"grammar":"Nではない(không còn là N)","grammar_vi":"Không còn là ~ (mất đi bản chất)","sentence":"[子供](こども)の[生活](せいかつ)から「[遊](あそ)び」をもぎ[取](と)ってしまったら、それはちょうど[羽根](はね)をむしり[取](と)られたトンボと[同](おな)じで、**[子供](こども)ではない**。","sentence_vi":"Nếu lấy đi 'trò chơi' khỏi cuộc sống của trẻ em, thì cũng giống hệt con chuồn chuồn bị nhổ mất cánh, (trẻ ấy) không còn là trẻ con nữa."},{"no":19,"options":["ふれ[合](あ)いを[確](たし)かめつつ","ふれ[合](あ)いを[確](たし)かめなくては","ふれ[合](あ)いを[確](たし)かめては","ふれ[合](あ)いを[確](たし)かずに"],"answer":0,"grammar":"V_ます_+つつ","grammar_vi":"Vừa ~ vừa (dù biết ~)","sentence":"[子供](こども)たちは、[仲間](なかま)[同士](どうし)のあせまみれ、どろまみれの[遊](あそ)びの[中](なか)から、おのずと[人間](にんげん)の[心](こころ)の**ふれ[合](あ)いを[確](たし)かめつつ**、[友情](ゆうじょう)をつちかうのである。","sentence_vi":"Trẻ em, qua những trò chơi lấm lem mồ hôi và bùn đất cùng bạn bè, tự nhiên vừa xác nhận sự gắn bó giữa những tâm hồn con người, vừa vun đắp tình bạn."},{"no":20,"options":["[豊](ゆた)かにするわけがない","[豊](ゆた)かにするものはあるまい","[豊](ゆた)かにするよりほかない","[豊](ゆた)かにすることといえる"],"answer":1,"grammar":"Nぐらい~ものはあるまい","grammar_vi":"Chẳng có gì ~ bằng ~ (văn viết)","sentence":"けんかぐらい、[子供](こども)の[感情](かんじょう)の[振幅](しんぷく)を**[豊](ゆた)かにするものはあるまい**。","sentence_vi":"Chẳng có gì làm phong phú biên độ cảm xúc của trẻ em bằng cãi nhau."},{"no":21,"options":["しかしながら","それどころか","それにつけても","[当然](とうぜん)ながら"],"answer":3,"grammar":"当然ながら","grammar_vi":"Đương nhiên là ~ (nêu điều hiển nhiên)","sentence":"[子供](こども)の[遊](あそ)びには、**[当然](とうぜん)ながら**、[自然](しぜん)がいる。","sentence_vi":"Trong trò chơi của trẻ em, đương nhiên cần có thiên nhiên."},{"no":22,"options":["すがたしか","すがたこそ","すがたなら","すがたより"],"answer":1,"grammar":"Nこそ(nhấn mạnh)","grammar_vi":"Chính ~ mới là ~ (nhấn mạnh)","sentence":"わたしは、[子供](こども)のこのような**すがたこそ**[真](しん)の[子供](こども)らしさではないかと[思](おも)っているし、これからも[大事](だいじ)に[育](そだ)てていきたいと[考](かんが)えている。","sentence_vi":"Tôi nghĩ chính hình ảnh như vậy của trẻ em mới là nét trẻ con đích thực, và từ nay cũng muốn nuôi dưỡng nó một cách trân trọng."}],"translation_vi":"Nếu lấy đi 'trò chơi' khỏi cuộc sống của trẻ em, thì cũng giống hệt con chuồn chuồn bị nhổ mất đôi cánh, không còn là trẻ con nữa. Con chuồn chuồn bị nhổ cánh có thể còn loạng choạng đi trên mặt đất, nhưng chắc chắn không thể bay lượn tự do trên bầu trời rộng.\\n\\nTrẻ em, qua những trò chơi lấm lem mồ hôi và bùn đất cùng bạn bè, tự nhiên vừa xác nhận sự gắn bó giữa những tâm hồn con người, vừa vun đắp tình bạn. Trí tưởng tượng cũng phát triển ở đây. Nếu không luôn nghĩ cách như 'có gì thú vị không', 'thử thế này thử thế kia' thì không có được những trò chơi vui hơn, và cũng không kéo dài lâu. Trong lúc đó có thể có những trận ẩu đả, nhưng chính những trận cãi nhau ấy cũng quan trọng. Chẳng có gì làm phong phú biên độ cảm xúc của trẻ em bằng cãi nhau.\\n\\nTôi xin nêu thêm một điều nữa. Trong trò chơi của trẻ em, đương nhiên cần có thiên nhiên. Thiên nhiên được đại diện bởi đất. Trong đó, những chú kiến nhỏ đào vô số lỗ, hay những mầm cây không rõ tên bất ngờ ló mặt ra. Từ khi bắt đầu có nhận thức, qua giao lưu với những sinh vật tự nhiên ấy, trẻ em dần dần học được sự quý giá của sinh mệnh, phải không? Tôi nghĩ chính hình ảnh như vậy của trẻ em mới là nét trẻ con đích thực, và từ nay cũng muốn nuôi dưỡng nó một cách trân trọng."},{"paragraphs":["わたしたちは、[非常](ひじょう)に[混雑](こんざつ)したバスや[電車](でんしゃ)に[乗](の)り[合](あ)わせる[場合](ばあい)がある。みなが[殺気](さっき)だっていて、おしつぶされそうな[危険](きけん)を[感](かん)じることも[少](すく)なくない。","[世](よ)の[中](なか)には、[人](ひと)の[目](め)につきたくてうずうずしている[人](ひと)も（18）。しかし、[大](だい)[部分](ぶぶん)の[人](ひと)は、[大声](おおごえ)を[出](だ)して[人](ひと)に[見](み)られるのをはずかしいと[思](おも)う。あぶないなあと[気](き)づいても、[声](こえ)に[出](だ)して[注意](ちゅうい)を[発](はっ)するまでに[至](いた)らないことが[多](おお)いのではなかろうか。","[電車](でんしゃ)の[事故](じこ)や、[火事](かじ)などというような、[直接的](ちょくせつてき)な[問題](もんだい)ばかりではない。[考](かんが)えてみると、[世](よ)の[中](なか)には、めいめいが[早](はや)めにさわぎたてれば、それで[大事](だいじ)に[至](いた)らずに[済](す)むということが[少](すく)なくないのだ。（19）、[自分](じぶん)の[身](み)に[直接](ちょくせつ)の[影響](えいきょう)がないと、たいていのことは、ひとごとに[見](み)える。そのため、すぐ[目](め)の[前](まえ)にある[危険](きけん)な[状態](じょうたい)も、つい[見過](みす)ごしがちである。（20）、[大声](おおごえ)でわめくのは、みにくいと[考](かんが)えて、かたつむりのようにひっこんでしまうことが[多](おお)い。","（21）、[大声](おおごえ)でさわぎたてることがこれほどきらいな[人](ひと)たちも、ひとたび[事故](じこ)がおきたとなると、[前](まえ)とはうって[変](か)わったように、わめきたてることが[多](おお)い。いくらどなったところで、そうなってからでは（22）である。だから、よくないことがおきそうな[予感](よかん)がしたら、[日](ひ)ごろは[出](だ)すぎることのきらいな[人](じん)でも、ときにはいのちがけでさわぎたてて、[危険](きけん)を[前](まえ)もって[防](ふせ)ぐ[側](がわ)にまわるように、わたしは[勧](すす)めたい。"],"questions":[{"no":18,"options":["いないものだ","いないものではない","いないわけだ","いないわけではない"],"answer":3,"grammar":"Vない+わけではない","grammar_vi":"Không phải là không ~ (phủ định một phần)","sentence":"[世](よ)の[中](なか)には、[人](ひと)の[目](め)につきたくてうずうずしている[人](ひと)も**いないわけではない**。","sentence_vi":"Trên đời cũng không phải là không có những người nóng lòng muốn được người khác chú ý."},{"no":19,"options":["そこで","ところが","さて","それとも"],"answer":1,"grammar":"ところが","grammar_vi":"Thế nhưng (kết quả trái với dự đoán)","sentence":"**ところが**、[自分](じぶん)の[身](み)に[直接](ちょくせつ)の[影響](えいきょう)がないと、たいていのことは、ひとごとに[見](み)える。","sentence_vi":"Thế nhưng, nếu bản thân không bị ảnh hưởng trực tiếp thì hầu hết mọi chuyện đều trông như chuyện của người khác."},{"no":20,"options":["[気](き)づいたように","[気](き)づいたにつけても","[気](き)づいたとしても","[気](き)づいたわけがなく"],"answer":2,"grammar":"Thể thường+としても","grammar_vi":"Cho dù ~ thì cũng ~","sentence":"**[気](き)づいたとしても**、[大声](おおごえ)でわめくのは、みにくいと[考](かんが)えて、かたつむりのようにひっこんでしまうことが[多](おお)い。","sentence_vi":"Cho dù có nhận ra, nhiều người vẫn nghĩ la hét ầm ĩ là xấu xí nên rụt lại như con ốc sên."},{"no":21,"options":["しかし","そのうえ","つまり","それに"],"answer":0,"grammar":"しかし","grammar_vi":"Nhưng, tuy nhiên (nối hai câu đối lập)","sentence":"**しかし**、[大声](おおごえ)でさわぎたてることがこれほどきらいな[人](ひと)たちも、ひとたび[事故](じこ)がおきたとなると、[前](まえ)とはうって[変](か)わったように、わめきたてることが[多](おお)い。","sentence_vi":"Nhưng ngay cả những người rất ghét làm ồn ào như vậy, một khi tai nạn đã xảy ra thì lại thay đổi hẳn so với trước, thường la hét ầm lên."},{"no":22,"options":["[花](はな)より[団子](だんご)","[猫](ねこ)に[小判](こばん)","あとの[祭](まつ)り","[急](いそ)がばまわれ"],"answer":2,"grammar":"あとの祭り","grammar_vi":"Đã muộn rồi, mất bò mới lo làm chuồng (thành ngữ)","sentence":"いくらどなったところで、そうなってからでは**あとの[祭](まつ)り**である。","sentence_vi":"Dù có la hét thế nào, khi đã xảy ra rồi thì cũng là chuyện đã muộn (mất bò mới lo làm chuồng)."}],"translation_vi":"Chúng ta có lúc phải đi chung trên những chuyến xe buýt hay tàu điện cực kỳ đông đúc. Mọi người đều căng thẳng, và không ít khi ta cảm thấy nguy hiểm như sắp bị ép bẹp.\\n\\nTrên đời cũng không phải là không có những người nóng lòng muốn được người khác chú ý. Tuy nhiên, phần lớn mọi người đều thấy xấu hổ khi cất tiếng lớn để bị người khác nhìn. Dù nhận ra 'nguy hiểm quá' thì nhiều khi cũng không đến mức lên tiếng cảnh báo, phải không?\\n\\nKhông chỉ là những vấn đề trực tiếp như tai nạn tàu điện hay hỏa hoạn. Nghĩ kỹ thì trên đời không ít chuyện nếu mỗi người sớm làm ầm lên thì sẽ không đến mức nghiêm trọng. Thế nhưng, nếu bản thân không bị ảnh hưởng trực tiếp thì hầu hết mọi chuyện đều trông như chuyện của người khác. Vì vậy, ngay cả tình trạng nguy hiểm ngay trước mắt, ta cũng dễ bỏ qua. Cho dù có nhận ra, nhiều người vẫn nghĩ la hét ầm ĩ là xấu xí nên rụt lại như con ốc sên.\\n\\nNhưng ngay cả những người rất ghét làm ồn ào như vậy, một khi tai nạn đã xảy ra thì lại thay đổi hẳn so với trước, thường la hét ầm lên. Dù có la hét thế nào, khi đã xảy ra rồi thì cũng là chuyện đã muộn (mất bò mới lo làm chuồng). Vì thế, nếu có linh cảm điều không hay sắp xảy ra, tôi muốn khuyên rằng ngay cả người ngày thường ghét nổi bật thì đôi khi cũng nên liều mình làm ầm lên để đứng về phía ngăn chặn nguy hiểm từ trước."},{"paragraphs":["[最近](さいきん)では、[名](な)の[知](し)られた[大](だい)[企業](きぎょう)が[不祥事](ふしょうじ)に[絡](から)んで[世間](せけん)を[騒](さわ)がせたり、[刑事](けいじ)[事件](じけん)で[当局](とうきょく)の[捜査](そうさ)を[受](う)けることは[珍](めずら)しくなくなった。[事件](じけん)の[関係](かんけい)[者](しゃ)として[著名](ちょめい)[企業](きぎょう)の[名](な)が[挙](あ)がると、[新聞](しんぶん)やテレビはこぞってそれを[報道](ほうどう)するため、（18）そのような[事件](じけん)が[目立](めだ)つという[面](めん)はあるにせよ、[著名](ちょめい)[企業](きぎょう)が[関係](かんけい)した[犯罪](はんざい)はもはやレアケースとは[言](い)えない[時代](じだい)となっている。（19）、[多](おお)くの[企業](きぎょう)[人](じん)は、[他](た)の[企業](きぎょう)が[捜査](そうさ)[対象](たいしょう)となっても、「[当社](とうしゃ)に[限](かぎ)ってそのようなことがあるはずはない」と、いわば[対岸](たいがん)の[火事](かじ)を[眺](なが)めるような[気持](きも)ちで[新聞](しんぶん)[報道](ほうどう)[等](とう)に[接](せっ)していることと[思](おも)う。その[発想](はっそう)は[健全](けんぜん)であり、また、[本来](ほんらい)そうでなければならないのであるが、[実際](じっさい)には、[企業](きぎょう)[犯罪](はんざい)に[巻](ま)き[込](こ)まれる[危険](きけん)は、たいていの[企業](きぎょう)が[等](ひと)しく[負](お)っているのである。（20）、[不祥事](ふしょうじ)や[企業](きぎょう)[犯罪](はんざい)に[絡](から)んで[名前](なまえ)が[出](で)る[企業](きぎょう)の[多](おお)くは[業務](ぎょうむ)を[通](つう)じて[社会](しゃかい)に[多大](ただい)の[貢献](こうけん)をしているし、[犯罪](はんざい)を[実行](じっこう)したとされる[役職](やくしょく)[員](いん)も[個人](こじん)[的](てき)には[社会](しゃかい)[的](てき)に[高](たか)く[評価](ひょうか)され[尊敬](そんけい)を[集](あつ)めている[例](れい)がむしろ[多](おお)い。[問題](もんだい)は、こういった[企業](きぎょう)や[役職](やくしょく)[員](いん)が、なぜ、[業務](ぎょうむ)を[遂行](すいこう)する[過程](かてい)で、[犯罪](はんざい)として[指弾](しだん)を[受](う)けるような[行為](こうい)に[関係](かんけい)してしまったのかということである。もちろん、[個々](ここ)の[事案](じあん)をみればその[原因](げんいん)はさまざまであろうが、[少](すく)なくとも[一流](いちりゅう)と[目](め)されるような[企業](きぎょう)が[関係](かんけい)した（21）、ある[共通](きょうつう)した[特質](とくしつ)が[見](み)い[出](だ)せるように[思](おも)われる。","いかなる[企業](きぎょう)にも、しかも[歴史](れきし)と[伝統](でんとう)のある[大](だい)[企業](きぎょう)ほど、[組織](そしき)[内](ない)で[通用](つうよう)してきた[慣行](かんこう)というものがある。そして、そのような[企業](きぎょう)[内](ない)の[慣行](かんこう)は、トップの[意思](いし)[決定](けってい)のシステムから[日常](にちじょう)[的](てき)な[業務](ぎょうむ)の[処理](しょり)の[方法](ほうほう)に[至](いた)るまで、[組織](そしき)の[至](いた)るところに[存在](そんざい)し[深](ふか)く[浸透](しんとう)している。それ[自体](じたい)はもちろん[悪](わる)いことではない。また、その[組織](そしき)の[内部](ないぶ)では、そのような[慣行](かんこう)に[合理](ごうり)[性](せい)があるからこそ、[長年](ながねん)にわたって[維持](いじ)され[継承](けいしょう)されてきたのであろう。"],"questions":[{"no":18,"options":["とりわけ","つまり","そこで","もちろん"],"answer":0,"grammar":"とりわけ","grammar_vi":"Đặc biệt là, nhất là","sentence":"[事件](じけん)の[関係](かんけい)[者](しゃ)として[著名](ちょめい)[企業](きぎょう)の[名](な)が[挙](あ)がると、[新聞](しんぶん)やテレビはこぞってそれを[報道](ほうどう)するため、**とりわけ**そのような[事件](じけん)が[目立](めだ)つという[面](めん)はあるにせよ、[著名](ちょめい)[企業](きぎょう)が[関係](かんけい)した[犯罪](はんざい)はもはやレアケースとは[言](い)えない[時代](じだい)となっている。","sentence_vi":"Khi tên một doanh nghiệp nổi tiếng được nêu ra với tư cách bên liên quan đến vụ việc, báo chí và truyền hình đồng loạt đưa tin, nên dù có khía cạnh là những vụ như vậy đặc biệt gây chú ý, thì tội phạm liên quan đến doanh nghiệp nổi tiếng giờ đây đã là thời đại không thể gọi là trường hợp hiếm nữa."},{"no":19,"options":["そういえば","もっとも","それどころか","すなわち"],"answer":1,"grammar":"もっとも","grammar_vi":"Tuy vậy, dù thế (bổ sung điều kiện, ngoại lệ cho ý vừa nói)","sentence":"**もっとも**、[多](おお)くの[企業](きぎょう)[人](じん)は、[他](た)の[企業](きぎょう)が[捜査](そうさ)[対象](たいしょう)となっても、「[当社](とうしゃ)に[限](かぎ)ってそのようなことがあるはずはない」と、いわば[対岸](たいがん)の[火事](かじ)を[眺](なが)めるような[気持](きも)ちで[新聞](しんぶん)[報道](ほうどう)[等](とう)に[接](せっ)していることと[思](おも)う。","sentence_vi":"Tuy vậy, tôi nghĩ nhiều người trong giới doanh nghiệp, ngay cả khi doanh nghiệp khác trở thành đối tượng điều tra, vẫn tiếp nhận tin báo chí với tâm trạng như đứng nhìn lửa cháy bờ bên kia, kiểu 'riêng công ty chúng ta thì không thể có chuyện như vậy'."},{"no":20,"options":["[単](たん)に","[今](いま)に","[実](じつ)に","[現](げん)に"],"answer":3,"grammar":"現に","grammar_vi":"Trên thực tế, thực tế là","sentence":"**[現](げん)に**、[不祥事](ふしょうじ)や[企業](きぎょう)[犯罪](はんざい)に[絡](から)んで[名前](なまえ)が[出](で)る[企業](きぎょう)の[多](おお)くは[業務](ぎょうむ)を[通](つう)じて[社会](しゃかい)に[多大](ただい)の[貢献](こうけん)をしているし、[犯罪](はんざい)を[実行](じっこう)したとされる[役職](やくしょく)[員](いん)も[個人](こじん)[的](てき)には[社会](しゃかい)[的](てき)に[高](たか)く[評価](ひょうか)され[尊敬](そんけい)を[集](あつ)めている[例](れい)がむしろ[多](おお)い。","sentence_vi":"Thực tế, phần lớn các doanh nghiệp có tên trong các bê bối hay tội phạm doanh nghiệp đều đã đóng góp lớn cho xã hội qua hoạt động kinh doanh, và nhiều trường hợp những cán bộ, nhân viên bị cho là đã phạm tội lại được đánh giá cao và kính trọng về mặt xã hội với tư cách cá nhân."},{"no":21,"options":["[事件](じけん)については","[事件](じけん)にしたがっては","[事件](じけん)にとっては","[事件](じけん)にしては"],"answer":0,"grammar":"Nについては","grammar_vi":"Về ~ thì (nêu chủ đề)","sentence":"もちろん、[個々](ここ)の[事案](じあん)をみればその[原因](げんいん)はさまざまであろうが、[少](すく)なくとも[一流](いちりゅう)と[目](め)されるような[企業](きぎょう)が[関係](かんけい)した**[事件](じけん)については**、ある[共通](きょうつう)した[特質](とくしつ)が[見](み)い[出](だ)せるように[思](おも)われる。","sentence_vi":"Tất nhiên, nếu xem từng vụ việc thì nguyên nhân có lẽ muôn hình vạn trạng, nhưng ít nhất đối với những vụ việc liên quan đến các doanh nghiệp được xem là hàng đầu, có vẻ có thể tìm thấy một đặc tính chung nào đó."}],"translation_vi":"Gần đây, việc các doanh nghiệp lớn nổi tiếng dính líu đến bê bối gây xôn xao dư luận, hay bị cơ quan chức năng điều tra trong các vụ án hình sự không còn hiếm. Khi tên một doanh nghiệp nổi tiếng được nêu ra với tư cách bên liên quan đến vụ việc, báo chí và truyền hình đồng loạt đưa tin, nên dù có khía cạnh là những vụ như vậy đặc biệt gây chú ý, thì tội phạm liên quan đến doanh nghiệp nổi tiếng giờ đây đã là thời đại không thể gọi là trường hợp hiếm nữa. Tuy vậy, tôi nghĩ nhiều người trong giới doanh nghiệp, ngay cả khi doanh nghiệp khác trở thành đối tượng điều tra, vẫn tiếp nhận tin báo chí với tâm trạng như đứng nhìn lửa cháy bờ bên kia, kiểu 'riêng công ty chúng ta thì không thể có chuyện như vậy'. Suy nghĩ đó là lành mạnh, và vốn dĩ cũng phải như vậy, nhưng trên thực tế, hầu hết các doanh nghiệp đều gánh nguy cơ bị cuốn vào tội phạm doanh nghiệp như nhau. Thực tế, phần lớn các doanh nghiệp có tên trong các bê bối hay tội phạm doanh nghiệp đều đã đóng góp lớn cho xã hội qua hoạt động kinh doanh, và nhiều trường hợp những cán bộ, nhân viên bị cho là đã phạm tội lại được đánh giá cao và kính trọng về mặt xã hội với tư cách cá nhân. Vấn đề là vì sao những doanh nghiệp và cán bộ, nhân viên như vậy lại dính líu đến hành vi bị truy cứu như tội phạm trong quá trình thực hiện công việc. Tất nhiên, nếu xem từng vụ việc thì nguyên nhân có lẽ muôn hình vạn trạng, nhưng ít nhất đối với những vụ việc liên quan đến các doanh nghiệp được xem là hàng đầu, có vẻ có thể tìm thấy một đặc tính chung nào đó.\\n\\nDoanh nghiệp nào cũng vậy, và nhất là những doanh nghiệp lớn có lịch sử, truyền thống, đều có những thông lệ được áp dụng trong nội bộ tổ chức. Và những thông lệ nội bộ như vậy tồn tại và thấm sâu khắp mọi nơi của tổ chức, từ hệ thống ra quyết định của lãnh đạo cho đến cách xử lý công việc hằng ngày. Bản thân điều đó tất nhiên không xấu. Hơn nữa, trong nội bộ tổ chức, chính vì những thông lệ ấy có tính hợp lý nên chúng mới được duy trì và kế thừa suốt nhiều năm."},{"paragraphs":["[好](す)きという[言葉](ことば)はとても[曖昧](あいまい)だ。「[好](す)き」は、「[嫌](きら)いじゃない」に[始](はじ)まって、「それがないと[死](し)んでしまうかも」にいたるまで、[幅広](はばひろ)く[対応](たいおう)している。[好](す)きなことを[見](み)つけなさい、と[親](おや)や[教師](きょうし)がアドバイスするかも[知](し)れない。（18）、[将来](しょうらい)[的](てき)に[人生](じんせい)を[支](ささ)えてくれるような「[好](す)きなこと」をみつけるのは[簡単](かんたん)ではない。「[好](す)きなこと」（19）、レストランのメニューのようにどこかにズラッと[並](なら)んでいてその[中](なか)から[選](えら)ぶ、というようなものではないからだ。","「[好](す)きなこと」は、[見](み)つけるというより、「[出会](であ)う」ものかも[知](し)れない。「[好](す)きなこと」は、テレビの[映像](えいぞう)や、[本](ほん)の[中](なか)の[言葉](ことば)や、[誰](だれ)かの[言](い)ったことの[中](なか)に[潜](ひそ)んでいて、[突然](とつぜん)その[人](ひと)を[魅了](みりょう)するかもしれない。「[自分](じぶん)には[好](す)きなことは[何](なに)もない」と、がっかりする[必要](ひつよう)はない。[好](す)きなことがこの[世](よ)の[中](なか)に[何](なに)もない、ということではなく、まだ[出会](であ)っていないだけなのだ。[好](す)きなことを（20）。[探](さが)していないと、[出会](であ)ったときにそれが[自分](じぶん)の[好](す)きなものだと[気](き)づかないからだ。（21）、[飢](う)えた[人](ひと)が[食](た)べ[物](もの)を[探](さが)すように、[常](つね)に[目](め)をギラギラさせて、これでもない、あれでもないと、[焦](あせ)って[探](さが)す[必要](ひつよう)はない。[自分](じぶん)は[何](なに)が[好](す)きなのだろうという[気持](きも)ちを、[心](こころ)のどこかに[忘](わす)れずに[持](も)っていればそれで[充分](じゅうぶん)だ。そして[好奇](こうき)[心](しん)を[失](うしな)わずにいれば、いつかかならず「[好](す)きなこと」に[出会](であ)うだろう。この[世](よ)の[中](なか)には、（22）[学問](がくもん)や[仕事](しごと)や[表現](ひょうげん)の[種類](しゅるい)があって、それらは、あなたと[出会](であ)うのを[待](ま)っている。"],"questions":[{"no":18,"options":["さて","だが","さらに","すると"],"answer":1,"grammar":"だが","grammar_vi":"Nhưng, tuy nhiên (nối hai câu đối lập)","sentence":"**だが**、[将来](しょうらい)[的](てき)に[人生](じんせい)を[支](ささ)えてくれるような「[好](す)きなこと」をみつけるのは[簡単](かんたん)ではない。","sentence_vi":"Thế nhưng, tìm được 'điều mình thích' có thể nâng đỡ cuộc đời trong tương lai thì không dễ."},{"no":19,"options":["そのために","それならば","といっても","というのは"],"answer":3,"grammar":"~というのは~からだ","grammar_vi":"Sở dĩ như vậy là vì ~ (giải thích lý do)","sentence":"「[好](す)きなこと」**というのは**、レストランのメニューのようにどこかにズラッと[並](なら)んでいてその[中](なか)から[選](えら)ぶ、というようなものではないからだ。","sentence_vi":"Bởi vì 'điều mình thích' không phải là thứ xếp thành hàng dài ở đâu đó như thực đơn nhà hàng để ta chọn trong đó."},{"no":20,"options":["[探](さが)すのをあきらめなければならない","[探](さが)すのをあきらめるとは[限](かぎ)らない","[探](さが)すのをあきらめるかもしれない","[探](さが)すのをあきらめてはいけない"],"answer":3,"grammar":"Vてはいけない","grammar_vi":"Không được ~ (cấm đoán)","sentence":"[好](す)きなことを**[探](さが)すのをあきらめてはいけない**。","sentence_vi":"Đừng từ bỏ việc tìm kiếm điều mình thích."},{"no":21,"options":["それに","そのうえ","ただし","だって"],"answer":2,"grammar":"ただし","grammar_vi":"Tuy nhiên (bổ sung điều kiện, ngoại lệ)","sentence":"**ただし**、[飢](う)えた[人](ひと)が[食](た)べ[物](もの)を[探](さが)すように、[常](つね)に[目](め)をギラギラさせて、これでもない、あれでもないと、[焦](あせ)って[探](さが)す[必要](ひつよう)はない。","sentence_vi":"Tuy nhiên, không cần nóng vội tìm kiếm, mắt lúc nào cũng sáng rực như người đói tìm đồ ăn, nghĩ 'cũng không phải cái này, cũng không phải cái kia'."},{"no":22,"options":["[数](かぞ)え[切](き)れないほどの","[数](かぞ)えつけないほどの","[数](かぞ)えかねないほどの","[数](かぞ)えかけないほどの"],"answer":0,"grammar":"V_ます_+きれないほど","grammar_vi":"Nhiều đến mức không thể ~ hết","sentence":"この[世](よ)の[中](なか)には、**[数](かぞ)え[切](き)れないほどの**[学問](がくもん)や[仕事](しごと)や[表現](ひょうげん)の[種類](しゅるい)があって、それらは、あなたと[出会](であ)うのを[待](ま)っている。","sentence_vi":"Trên đời này có vô số loại ngành học, nghề nghiệp và hình thức biểu hiện, và chúng đang chờ gặp bạn."}],"translation_vi":"Từ 'thích' rất mơ hồ. 'Thích' bao quát rất rộng, từ 'không ghét' cho đến 'không có nó thì có lẽ tôi sẽ chết'. Cha mẹ hay thầy cô có thể khuyên 'hãy tìm điều mình thích đi'. Thế nhưng, tìm được 'điều mình thích' có thể nâng đỡ cuộc đời trong tương lai thì không dễ. Bởi vì 'điều mình thích' không phải là thứ xếp thành hàng dài ở đâu đó như thực đơn nhà hàng để ta chọn trong đó.\\n\\n'Điều mình thích' có lẽ là thứ ta 'gặp gỡ' hơn là 'tìm thấy'. 'Điều mình thích' ẩn mình trong hình ảnh trên tivi, trong lời trong sách, trong lời ai đó nói, và có thể bất ngờ làm người ta say mê. Không cần phải thất vọng với suy nghĩ 'mình chẳng có điều gì thích'. Không phải trên đời không có điều gì mình thích, mà chỉ là chưa gặp thôi. Đừng từ bỏ việc tìm kiếm điều mình thích. Vì nếu không tìm, khi gặp được ta cũng sẽ không nhận ra đó là điều mình thích. Tuy nhiên, không cần nóng vội tìm kiếm, mắt lúc nào cũng sáng rực như người đói tìm đồ ăn, nghĩ 'cũng không phải cái này, cũng không phải cái kia'. Chỉ cần giữ trong lòng, ở đâu đó, cảm giác 'mình thích gì nhỉ' là đủ. Và nếu không đánh mất sự tò mò, chắc chắn một ngày nào đó bạn sẽ gặp được 'điều mình thích'. Trên đời này có vô số loại ngành học, nghề nghiệp và hình thức biểu hiện, và chúng đang chờ gặp bạn."},{"paragraphs":["[最近](さいきん)、[地球](ちきゅう)の[環境](かんきょう)を[守](まも)るために、[積極](せっきょく)[的](てき)に「リサイクル」をしようという[意見](いけん)をよく（18）。もちろん[使](つか)ったものをすぐに[捨](す)ててしまって、また[新](あら)たに[必要](ひつよう)なものを[作](つく)り[出](だ)すという[使](つか)い[捨](す)て[文化](ぶんか)は[問題](もんだい)であり、[見直](みなお)しが[必要](ひつよう)だ。（19）、[使](つか)い[終](お)わったものをもう[一度](いちど)[資源](しげん)として[利用](りよう)するリサイクルは、[本当](ほんとう)に[地球](ちきゅう)の[環境](かんきょう)を[守](まも)るために[役立](やくだ)っているのだろうか。","[例](たと)えばペットボトルのリサイクルについて[考](かんが)えてみよう。[確](たし)かに、「[使](つか)い[終](お)わったものをゴミとして[捨](す)てるのではなく、もう[一度](いちど)[資源](しげん)として[使](つか)う」という[考](かんが)えは、うまくいけば[理想](りそう)[的](てき)だ。しかし[皆](みな)さんは、[石油](せきゆ)から[新](あたら)しいペットボトルを[作](つく)るのにかかる[石油](せきゆ)の[量](りょう)と、[使](つか)い[終](お)わって[集](あつ)めたペットボトルから[新](あら)たにペットボトルを[作](つく)るのにかかる[石油](せきゆ)の[量](りょう)を[知](し)っているだろうか。（20）、[石油](せきゆ)から[新](あたら)しいペットボトルを[作](つく)るのに[必要](ひつよう)な[石油](せきゆ)は[約](やく)40グラム、[一方](いっぽう)、このペットボトルをリサイクルしようとすると、それに[必要](ひつよう)な[石油](せきゆ)は150グラム[以上](いじょう)と[言](い)われているのだ。これはつまり、[資源](しげん)をできるだけ[使](つか)わないようにするためのリサイクルによって、（21）[資源](しげん)が[多](おお)く[使](つか)われてしまっている[例](れい)といえるだろう。もちろん、[資源](しげん)が[多](おお)く[使](つか)われるのだから、[当然](とうぜん)その[分](ぶん)、[資源](しげん)として[使](つか)えなくなったもの、すなわちゴミも[増](ふ)える。このように、リサイクル[運動](うんどう)には[実](じつ)は[大](おお)きな[問題](もんだい)があるのだ。[本来](ほんらい)、[資源](しげん)を[節約](せつやく)し、[環境](かんきょう)[汚染](おせん)を[防止](ぼうし)するために[行](おこな)われるはずのリサイクルだが、やり[方](かた)によっては、（22）[資源](しげん)を[使](つか)い、ゴミを[増](ふ)やす。"],"questions":[{"no":18,"options":["[手](て)にする","[口](くち)にする","[耳](みみ)にする","[鼻](はな)にする"],"answer":2,"grammar":"耳にする","grammar_vi":"Nghe thấy, tình cờ nghe được (quán ngữ)","sentence":"[最近](さいきん)、[地球](ちきゅう)の[環境](かんきょう)を[守](まも)るために、[積極](せっきょく)[的](てき)に「リサイクル」をしようという[意見](いけん)をよく**[耳](みみ)にする**。","sentence_vi":"Gần đây, tôi thường nghe ý kiến cho rằng để bảo vệ môi trường Trái Đất thì nên tích cực 'tái chế'."},{"no":19,"options":["しかし","すなわち","さらに","そのうえ"],"answer":0,"grammar":"しかし","grammar_vi":"Nhưng, tuy nhiên (nối hai câu đối lập)","sentence":"**しかし**、[使](つか)い[終](お)わったものをもう[一度](いちど)[資源](しげん)として[利用](りよう)するリサイクルは、[本当](ほんとう)に[地球](ちきゅう)の[環境](かんきょう)を[守](まも)るために[役立](やくだ)っているのだろうか。","sentence_vi":"Tuy nhiên, liệu việc tái chế — dùng lại đồ đã dùng xong làm tài nguyên — có thật sự góp phần bảo vệ môi trường Trái Đất không?"},{"no":20,"options":["なお","いわば","ごく","[実](じつ)は"],"answer":3,"grammar":"実は","grammar_vi":"Thực ra là, sự thật là","sentence":"**[実](じつ)は**、[石油](せきゆ)から[新](あたら)しいペットボトルを[作](つく)るのに[必要](ひつよう)な[石油](せきゆ)は[約](やく)40グラム、[一方](いっぽう)、このペットボトルをリサイクルしようとすると、それに[必要](ひつよう)な[石油](せきゆ)は150グラム[以上](いじょう)と[言](い)われているのだ。","sentence_vi":"Thực ra, người ta nói lượng dầu cần để làm chai nhựa mới từ dầu mỏ là khoảng 40 gram, trong khi nếu tái chế chai nhựa này thì lượng dầu cần là từ 150 gram trở lên."},{"no":21,"options":["はじめて","はたして","ようやく","かえって"],"answer":3,"grammar":"かえって","grammar_vi":"Ngược lại, trái lại (kết quả ngược với mong đợi)","sentence":"これはつまり、[資源](しげん)をできるだけ[使](つか)わないようにするためのリサイクルによって、**かえって**[資源](しげん)が[多](おお)く[使](つか)われてしまっている[例](れい)といえるだろう。","sentence_vi":"Điều này nói cách khác là ví dụ cho thấy việc tái chế vốn nhằm hạn chế sử dụng tài nguyên lại khiến tài nguyên bị dùng nhiều hơn."},{"no":22,"options":["リサイクルをするにあたって","リサイクルをすればするほど","リサイクルをするにもかかわらず","リサイクルをした[以上](いじょう)"],"answer":1,"grammar":"Vば+Vる+ほど","grammar_vi":"Càng ~ càng ~","sentence":"[本来](ほんらい)、[資源](しげん)を[節約](せつやく)し、[環境](かんきょう)[汚染](おせん)を[防止](ぼうし)するために[行](おこな)われるはずのリサイクルだが、やり[方](かた)によっては、**リサイクルをすればするほど**[資源](しげん)を[使](つか)い、ゴミを[増](ふ)やす。","sentence_vi":"Tái chế vốn được thực hiện để tiết kiệm tài nguyên và phòng chống ô nhiễm môi trường, nhưng tùy cách làm, càng tái chế thì càng tốn tài nguyên và làm tăng rác thải."}],"translation_vi":"Gần đây, tôi thường nghe ý kiến cho rằng để bảo vệ môi trường Trái Đất thì nên tích cực 'tái chế'. Tất nhiên, văn hóa dùng xong là vứt, rồi lại làm ra cái mới cần thiết là vấn đề và cần xem xét lại. Tuy nhiên, liệu việc tái chế — dùng lại đồ đã dùng xong làm tài nguyên — có thật sự góp phần bảo vệ môi trường Trái Đất không?\\n\\nHãy thử nghĩ về việc tái chế chai nhựa chẳng hạn. Quả thật, ý tưởng 'không vứt đồ đã dùng xong như rác mà dùng lại làm tài nguyên' nếu suôn sẻ thì là lý tưởng. Nhưng các bạn có biết lượng dầu cần để làm chai nhựa mới từ dầu mỏ, và lượng dầu cần để làm lại chai nhựa mới từ chai đã dùng xong thu gom về không? Thực ra, người ta nói lượng dầu cần để làm chai nhựa mới từ dầu mỏ là khoảng 40 gram, trong khi nếu tái chế chai nhựa này thì lượng dầu cần là từ 150 gram trở lên. Điều này nói cách khác là ví dụ cho thấy việc tái chế vốn nhằm hạn chế sử dụng tài nguyên lại khiến tài nguyên bị dùng nhiều hơn. Tất nhiên, vì dùng nhiều tài nguyên hơn nên đương nhiên phần những thứ không dùng làm tài nguyên được nữa, tức rác, cũng tăng lên. Như vậy, phong trào tái chế thực ra có vấn đề lớn. Tái chế vốn được thực hiện để tiết kiệm tài nguyên và phòng chống ô nhiễm môi trường, nhưng tùy cách làm, càng tái chế thì càng tốn tài nguyên và làm tăng rác thải."},{"paragraphs":["[元来](がんらい)、[日本人](にほんじん)はよく「[泣](な)いた」ようである。[柳田](やなぎだ)[国男](くにお)[翁](おう)が、「[涕泣](ていきゅう)[史談](しだん)」という[文章](ぶんしょう)で、このことを[論](ろん)じたが、[古](ふる)くは、[声](こえ)に[出](だ)して[哭](な)くことも[涙](なみだ)を[流](なが)して[泣](な)くことも、きわめて[普通](ふつう)であった[日本人](にほんじん)が、（18）、だんだん、あまり[泣](な)かなくなってきたようにも[見](み)える。","[平安](へいあん)[時代](じだい)の[物語](ものがたり)や[歌](うた)などを[見](み)ると、[女](おんな)も[男](おとこ)も、（19）すぐに[涙](なみだ)を[流](なが)す。『[源氏物語](げんじものがたり)』[五](ご)[十](じゅう)[四](よん)[帖](じょう)に、「[泣](な)く」という[言葉](ことば)は、[実](じつ)に370[回](かい)も[出](で)てくるし、「[涙](なみだ)ぐむ」とかいう[語](ご)も225[回](かい)ぐらい[用](もち)いられている。そのなかには、むろん[幼児](ようじ)の[泣](な)く[場合](ばあい)や、[悲](かな)しみの[涙](なみだ)を[流](なが)すという[場合](ばあい)も[多数](たすう)あるけれども、ありがたさやら[嬉](うれ)しさやら[恋](こい)しさやらで、[大](だい)の[男](おとこ)までが[簡単](かんたん)に[泣](な)き[出](だ)すのには、[少々](しょうしょう)[奇異](きい)な（20）。","「[枕](まくら)も[浮](う)くばかり」[涙](なみだ)を[流](なが)すなどという[表現](ひょうげん)と[同](おな)じような、[文学](ぶんがく)[的](てき)な[修辞](しゅうじ)かとも[疑](うたが)われるが、どうも、そればかりではなさそうである。（21）、[多少](たしょう)[情緒](じょうちょ)[過敏](かびん)と[言](い)えそうな[貴族](きぞく)[社会](しゃかい)を[描](えが)いたこの[種](しゅ)の[文学](ぶんがく)の[性格](せいかく)によるところもあろうけれども、その[後](ご)の、「[物語](ものがたり)」[以外](いがい)の[文学](ぶんがく)[作品](さくひん)でも、こうした[傾向](けいこう)は[同様](どうよう)にうかがえるところを[見](み)ると、こんなふうに[人前](ひとまえ)はばからず[率直](そっちょく)に[感情](かんじょう)を[表出](ひょうしゅつ)するという[自然](しぜん)なすがたが、やはり、[日本人](にほんじん)の[本来](ほんらい)であるらしい。[感情](かんじょう)を[抑制](よくせい)することをもって「よし」とするようになったのは、むしろ[中世](ちゅうせい)[以後](いご)の[傾向](けいこう)であると[思](おも)われる。それには、いろいろの（22）。[柳田](やなぎだ)[翁](おう)の[言](い)われるように、「[泣](な)く」ということが、ことごとく[不幸](ふこう)の[表示](ひょうじ)として[忌](い)み[嫌](きら)われるようになって、そのむやみな[行使](こうし)がはばかられるようになったこと、また、「[泣](な)く」こと[以外](いがい)の[表現](ひょうげん)[法](ほう)として、ことばに[訴](うった)えてその[感情](かんじょう)が[表出](ひょうしゅつ)できると[信](しん)じられるようになり、[事実](じじつ)その[面](めん)に[発達](はったつ)が[見](み)られるようになったこと、などと[考](かんが)えられよう。"],"questions":[{"no":18,"options":["[時代](じだい)をさかのぼるにしたがって","[時代](じだい)を[下](くだ)るにしたがって","[時代](じだい)をへだてるにしたがって","[時代](じだい)をかえるにしたがって"],"answer":1,"grammar":"Vる+にしたがって","grammar_vi":"Càng ~ thì càng ~","sentence":"[柳田](やなぎだ)[国男](くにお)[翁](おう)が、「[涕泣](ていきゅう)[史談](しだん)」という[文章](ぶんしょう)で、このことを[論](ろん)じたが、[古](ふる)くは、[声](こえ)に[出](だ)して[哭](な)くことも[涙](なみだ)を[流](なが)して[泣](な)くことも、きわめて[普通](ふつう)であった[日本人](にほんじん)が、**[時代](じだい)を[下](くだ)るにしたがって**、だんだん、あまり[泣](な)かなくなってきたようにも[見](み)える。","sentence_vi":"Ông Yanagita Kunio đã bàn về điều này trong bài viết 'Teikyū shidan' (Chuyện khóc lóc trong lịch sử), và có vẻ như người Nhật xưa kia khóc thành tiếng hay rơi lệ đều là chuyện hết sức bình thường, nhưng càng về sau thời đại, dần dần họ ít khóc đi."},{"no":19,"options":["うらやむほど","あやしいほど","あきれるほど","おかしいほど"],"answer":2,"grammar":"Thể thường+ほど(mức độ)","grammar_vi":"Đến mức ~","sentence":"[平安](へいあん)[時代](じだい)の[物語](ものがたり)や[歌](うた)などを[見](み)ると、[女](おんな)も[男](おとこ)も、**あきれるほど**すぐに[涙](なみだ)を[流](なが)す。","sentence_vi":"Xem các truyện và thơ ca thời Heian thì thấy cả nữ lẫn nam đều rơi nước mắt dễ dàng đến mức khiến người ta sửng sốt."},{"no":20,"options":["[感](かん)をいだくわけにはいかない","[感](かん)をいだくことはない","[感](かん)をいだかざるをえない","[感](かん)をいだかないこともない"],"answer":2,"grammar":"Vざるを得ない","grammar_vi":"Đành phải ~, buộc phải ~","sentence":"そのなかには、むろん[幼児](ようじ)の[泣](な)く[場合](ばあい)や、[悲](かな)しみの[涙](なみだ)を[流](なが)すという[場合](ばあい)も[多数](たすう)あるけれども、ありがたさやら[嬉](うれ)しさやら[恋](こい)しさやらで、[大](だい)の[男](おとこ)までが[簡単](かんたん)に[泣](な)き[出](だ)すのには、[少々](しょうしょう)[奇異](きい)な**[感](かん)をいだかざるをえない**。","sentence_vi":"Dĩ nhiên trong đó có nhiều trường hợp trẻ nhỏ khóc hay rơi lệ vì buồn đau, nhưng việc cả những đấng nam nhi cũng dễ dàng bật khóc vì biết ơn, vui mừng, nhớ nhung khiến người ta không khỏi có cảm giác hơi kỳ lạ."},{"no":21,"options":["けっして","まったく","かならず","むろん"],"answer":3,"grammar":"むろん","grammar_vi":"Dĩ nhiên, tất nhiên","sentence":"**むろん**、[多少](たしょう)[情緒](じょうちょ)[過敏](かびん)と[言](い)えそうな[貴族](きぞく)[社会](しゃかい)を[描](えが)いたこの[種](しゅ)の[文学](ぶんがく)の[性格](せいかく)によるところもあろうけれども、その[後](ご)の、「[物語](ものがたり)」[以外](いがい)の[文学](ぶんがく)[作品](さくひん)でも、こうした[傾向](けいこう)は[同様](どうよう)にうかがえるところを[見](み)ると、こんなふうに[人前](ひとまえ)はばからず[率直](そっちょく)に[感情](かんじょう)を[表出](ひょうしゅつ)するという[自然](しぜん)なすがたが、やはり、[日本人](にほんじん)の[本来](ほんらい)であるらしい。","sentence_vi":"Dĩ nhiên, cũng có phần do tính chất của loại văn học mô tả xã hội quý tộc có thể nói là hơi nhạy cảm thái quá, nhưng xem ra ở cả các tác phẩm văn học khác ngoài 'monogatari' về sau cũng thấy xu hướng tương tự, nên việc thẳng thắn bộc lộ cảm xúc không ngại người khác như vậy dường như vẫn là bản chất vốn có của người Nhật."},{"no":22,"options":["[目的](もくてき)が[考](かんが)えられる","[理由](りゆう)が[考](かんが)えられる","[結果](けっか)が[考](かんが)えられる","[理由](りゆう)が[見当](みあ)たらない"],"answer":1,"grammar":"Nが考えられる","grammar_vi":"Có thể nghĩ đến ~ (suy xét khả năng)","sentence":"それには、いろいろの**[理由](りゆう)が[考](かんが)えられる**。","sentence_vi":"Có nhiều lý do có thể nghĩ đến cho điều đó."}],"translation_vi":"Vốn dĩ, người Nhật có vẻ hay 'khóc'. Ông Yanagita Kunio đã bàn về điều này trong bài viết 'Teikyū shidan' (Chuyện khóc lóc trong lịch sử), và có vẻ như người Nhật xưa kia khóc thành tiếng hay rơi lệ đều là chuyện hết sức bình thường, nhưng càng về sau thời đại, dần dần họ ít khóc đi.\\n\\nXem các truyện và thơ ca thời Heian thì thấy cả nữ lẫn nam đều rơi nước mắt dễ dàng đến mức khiến người ta sửng sốt. Trong 'Truyện kể Genji' 54 quyển, từ 'khóc' xuất hiện đến 370 lần, từ như 'rưng rưng nước mắt' cũng được dùng khoảng 225 lần. Dĩ nhiên trong đó có nhiều trường hợp trẻ nhỏ khóc hay rơi lệ vì buồn đau, nhưng việc cả những đấng nam nhi cũng dễ dàng bật khóc vì biết ơn, vui mừng, nhớ nhung khiến người ta không khỏi có cảm giác hơi kỳ lạ.\\n\\nCó thể nghi đây là lối tu từ văn học giống như cách nói 'khóc đến nỗi gối nổi lên', nhưng có vẻ không chỉ có vậy. Dĩ nhiên, cũng có phần do tính chất của loại văn học mô tả xã hội quý tộc có thể nói là hơi nhạy cảm thái quá, nhưng xem ra ở cả các tác phẩm văn học khác ngoài 'monogatari' về sau cũng thấy xu hướng tương tự, nên việc thẳng thắn bộc lộ cảm xúc không ngại người khác như vậy dường như vẫn là bản chất vốn có của người Nhật. Coi việc kiềm chế cảm xúc là 'tốt' có lẽ là xu hướng từ sau thời trung đại. Có nhiều lý do có thể nghĩ đến cho điều đó. Như ông Yanagita nói, việc 'khóc' đều bị ghét bỏ như dấu hiệu của bất hạnh nên không còn được tùy tiện thể hiện; ngoài ra, người ta tin rằng có thể bộc lộ cảm xúc bằng lời nói như một cách biểu đạt khác ngoài 'khóc', và quả thực mặt này cũng phát triển — có thể nghĩ đến những lý do như vậy."},{"paragraphs":["いまの[日本](にほん)の[教育](きょういく)[現場](げんば)を[見](み)てみますと、（18）「[失敗](しっぱい)は[成功](せいこう)のもと」「[失敗](しっぱい)は[成功](せいこう)の[母](はは)」という[考](かんが)え[方](かた)が、ほとんど[取](と)り[入](い)れられていないことに[気](き)づきます。（19）、[重視](じゅうし)されているのは、[決](き)められた[設問](せつもん)への[解](かい)を[最短](さいたん)で[出](だ)す[方法](ほうほう)、「こうすればうまくいく」「[失敗](しっぱい)しない」ということを[学](まな)ぶ[方法](ほうほう)ばかりです。","これは[受験](じゅけん)[勉強](べんきょう)に[限](かぎ)りません。[社会](しゃかい)に[出](で)てからも[通用](つうよう)する[知識](ちしき)・[教養](きょうよう)を[教](おし)える[最高](さいこう)[学府](がくふ)である[大学](だいがく)での[学](まな)びもまた[同様](どうよう)です。[失敗](しっぱい)から[学](まな)ぶ[体験](たいけん)[実習](じっしゅう)のように[自分](じぶん)の[頭](あたま)で[考](かんが)え、（20）[新](あら)たな[道](みち)を[模索](もさく)する、[想像](そうぞう)[力](りょく)を[培](つちか)う[演習](えんしゅう)が[行](おこな)われる[機会](きかい)は[悲](かな)しいかな、ほとんどありません。これが「[日本人](にほんじん)の[欠点](けってん)」として[諸](しょ)[外国](がいこく)から[指摘](してき)を[受](う)け、また[自](みずか)らも[自覚](じかく)している「[想像](そうぞう)[力](りょく)の[欠如](けつじょ)」にそのまま[結](むす)びついているのではないでしょうか。","[確](たし)かにかつては、[他人](たにん)の[成功](せいこう)[事例](じれい)を[模倣](もほう)することが[成功](せいこう)への[近道](ちかみち)であった[時代](じだい)がありました。そういう[時代](じだい)には、[決](き)められた[設問](せつもん)に[正確](せいかく)な[解](かい)を[素早](すばや)く[出](だ)す[学習](がくしゅう)[法](ほう)が[効果](こうか)[的](てき)だったことは[確](たし)かです。","しかし、[他人](たにん)の[成功](せいこう)[事例](じれい)を[模倣](もほう)することが[必](かなら)ずしも[自分](じぶん)の[成功](せいこう)を[約束](やくそく)するものではなくなったのが[今](いま)の[時代](じだい)です。[昨日](きのう)までの[成功](せいこう)は、[今日](きょう)の[成功](せいこう)を[意味](いみ)しません。そんな[時代](じだい)に[重要](じゅうよう)なのはやはり[想像](そうぞう)[力](りょく)です。そして[想像](そうぞう)[力](りょく)とは（21）、[失敗](しっぱい)を[避](さ)けて[培](つちか)えるものではありません。（22）。"],"questions":[{"no":18,"options":["さいわいにも","[残念](ざんねん)ながら","[当然](とうぜん)ながら","[意外](いがい)にも"],"answer":1,"grammar":"残念ながら","grammar_vi":"Tiếc là ~","sentence":"いまの[日本](にほん)の[教育](きょういく)[現場](げんば)を[見](み)てみますと、**[残念](ざんねん)ながら**「[失敗](しっぱい)は[成功](せいこう)のもと」「[失敗](しっぱい)は[成功](せいこう)の[母](はは)」という[考](かんが)え[方](かた)が、ほとんど[取](と)り[入](い)れられていないことに[気](き)づきます。","sentence_vi":"Nhìn vào thực tế giáo dục Nhật Bản hiện nay, đáng tiếc là tôi nhận thấy những quan niệm như 'thất bại là mẹ thành công' hầu như không được tiếp nhận."},{"no":19,"options":["それどころではない","それというのも","それどころか","それどころにして"],"answer":2,"grammar":"それどころか","grammar_vi":"Không những thế, ngược lại còn","sentence":"**それどころか**、[重視](じゅうし)されているのは、[決](き)められた[設問](せつもん)への[解](かい)を[最短](さいたん)で[出](だ)す[方法](ほうほう)、「こうすればうまくいく」「[失敗](しっぱい)しない」ということを[学](まな)ぶ[方法](ほうほう)ばかりです。","sentence_vi":"Không những thế, thứ được coi trọng chỉ toàn là phương pháp tìm ra lời giải cho đề bài đã định trong thời gian ngắn nhất, phương pháp học 'làm thế này thì sẽ ổn', 'không để thất bại'."},{"no":20,"options":["[成功](せいこう)[体験](たいけん)を[通](つう)じて","[模倣](もほう)を[通](つう)じて","[演習](えんしゅう)を[通](つう)じて","[失敗](しっぱい)[経験](けいけん)を[通](つう)じて"],"answer":3,"grammar":"Nを通じて","grammar_vi":"Thông qua ~","sentence":"[失敗](しっぱい)から[学](まな)ぶ[体験](たいけん)[実習](じっしゅう)のように[自分](じぶん)の[頭](あたま)で[考](かんが)え、**[失敗](しっぱい)[経験](けいけん)を[通](つう)じて**[新](あら)たな[道](みち)を[模索](もさく)する、[想像](そうぞう)[力](りょく)を[培](つちか)う[演習](えんしゅう)が[行](おこな)われる[機会](きかい)は[悲](かな)しいかな、ほとんどありません。","sentence_vi":"Những buổi luyện tập rèn trí tưởng tượng, nơi ta tự suy nghĩ bằng đầu óc mình như thực tập trải nghiệm học từ thất bại, và tìm tòi con đường mới thông qua kinh nghiệm thất bại, đáng buồn là hầu như không có."},{"no":21,"options":["[新](あたら)しいものをつくりだす[力](ちから)を[意味](いみ)している[一方](いっぽう)で","[新](あたら)しいものをつくりだす[力](ちから)を[意味](いみ)しながら","[新](あたら)しいものをつくりだす[力](ちから)を[意味](いみ)しているものの","[新](あたら)しいものをつくりだす[力](ちから)を[意味](いみ)している[以上](いじょう)"],"answer":3,"grammar":"Vている+以上","grammar_vi":"Vì đang ~ nên (lẽ đương nhiên)","sentence":"そして[想像](そうぞう)[力](りょく)とは**[新](あたら)しいものをつくりだす[力](ちから)を[意味](いみ)している[以上](いじょう)**、[失敗](しっぱい)を[避](さ)けて[培](つちか)えるものではありません。","sentence_vi":"Và vì trí tưởng tượng có nghĩa là sức mạnh tạo ra cái mới, nên nó không thể được nuôi dưỡng bằng cách tránh thất bại."},{"no":22,"options":["[失敗](しっぱい)を[恐](おそ)れなければ[新](あたら)しいものは[生](う)み[出](だ)せない","[失敗](しっぱい)を[恐](おそ)れるからこそ[新](あたら)しいものが[生](う)み[出](だ)せる","[失敗](しっぱい)を[恐](おそ)れていては[新](あたら)しいものは[生](う)み[出](だ)せない","[失敗](しっぱい)を[恐](おそ)れても[新](あたら)しいものは[生](う)み[出](だ)せる"],"answer":2,"grammar":"Vていては","grammar_vi":"Nếu cứ ~ thì (sẽ có kết quả xấu)","sentence":"**[失敗](しっぱい)を[恐](おそ)れていては[新](あたら)しいものは[生](う)み[出](だ)せない**。","sentence_vi":"Nếu cứ sợ thất bại thì không thể tạo ra cái mới."}],"translation_vi":"Nhìn vào thực tế giáo dục Nhật Bản hiện nay, đáng tiếc là tôi nhận thấy những quan niệm như 'thất bại là mẹ thành công' hầu như không được tiếp nhận. Không những thế, thứ được coi trọng chỉ toàn là phương pháp tìm ra lời giải cho đề bài đã định trong thời gian ngắn nhất, phương pháp học 'làm thế này thì sẽ ổn', 'không để thất bại'.\\n\\nĐiều này không chỉ giới hạn ở việc luyện thi. Việc học ở đại học — cơ sở giáo dục cao nhất dạy kiến thức, học vấn dùng được cả khi ra đời — cũng tương tự. Những buổi luyện tập rèn trí tưởng tượng, nơi ta tự suy nghĩ bằng đầu óc mình như thực tập trải nghiệm học từ thất bại, và tìm tòi con đường mới thông qua kinh nghiệm thất bại, đáng buồn là hầu như không có. Phải chăng điều này gắn thẳng với 'sự thiếu hụt trí tưởng tượng' mà nước ngoài chỉ ra như 'khuyết điểm của người Nhật' và chính họ cũng tự nhận thấy?\\n\\nQuả thật đã từng có thời đại mà bắt chước ví dụ thành công của người khác là đường tắt dẫn tới thành công. Ở thời đại đó, phương pháp học đưa ra nhanh lời giải chính xác cho đề bài đã định là hiệu quả, điều đó là chắc chắn.\\n\\nTuy nhiên, thời nay là thời mà bắt chước thành công của người khác không còn nhất thiết đảm bảo thành công cho mình. Thành công đến hôm qua không có nghĩa là thành công hôm nay. Trong thời đại như vậy, điều quan trọng vẫn là trí tưởng tượng. Và vì trí tưởng tượng có nghĩa là sức mạnh tạo ra cái mới, nên nó không thể được nuôi dưỡng bằng cách tránh thất bại. Nếu cứ sợ thất bại thì không thể tạo ra cái mới."},{"paragraphs":["[何](なん)[歳](さい)から[人](ひと)は[大人](おとな)と[呼](よ)ばれるのか、[大人](おとな)（18）[何](なに)か。そういう[議論](ぎろん)は[繰](く)り[返](かえ)し[起](お)きるようだ。[従来](じゅうらい)なら「[成人](せいじん)すれば[大人](おとな)」と[考](かんが)えればよかったのだから[話](はなし)は[簡単](かんたん)だが、[最近](さいきん)はその[基準](きじゅん)があいまいになってきている。[精神](せいしん)[科](か)の[臨床](りんしょう)の[現場](げんば)でも、[拒食症](きょしょくしょう)や[家庭](かてい)[暴力](ぼうりょく)といった[思春](ししゅん)[期](き)の[病理](びょうり)にもとづく[問題](もんだい)を[三](さん)[十](じゅう)[代](だい)、[四](よん)[十](じゅう)[代](だい)になってから[呈](てい)するケースが[目](め)につく。","[一方](いっぽう)、[十](じゅう)[二](に)、[三](さん)[歳](さい)でしっかりした[意識](いしき)を[持](も)ったタレントや（19）、「[高校](こうこう)を[出](で)ればおばさん」と[言](い)っている[少女](しょうじょ)もいる。[早々](そうそう)に「[私](わたし)なんてこんなもの」と[自分](じぶん)に[見切](みき)りをつけてしまう、[若者](わかもの)の「[早](はや)じまい[感](かん)」を[問題](もんだい)[視](し)する[精神](せいしん)[科](か)[医](い)もいる。","（20）、だれが[大人](おとな)でだれが[若者](わかもの)なのか。その[区別](くべつ)はとてもむずかしい。[先](さき)にあげた「[思春](ししゅん)[期](き)の[病理](びょうり)を[抱](かか)える[大人](おとな)」には、[親](おや)や[周囲](しゅうい)との[関係](かんけい)の[中](なか)で[激](はげ)しい[自己](じこ)[否定](ひてい)に[陥](おちい)っているという[共通](きょうつう)[点](てん)がある。「[私](わたし)は[親](おや)に[好](す)かれていなかった」「[自分](じぶん)なんて（21）」と、[彼](かれ)らはつぶやく。（22）、「[大人](おとな)[顔負](かおま)けのプロ[意識](いしき)を[持](も)った[子](こ)ども」は、[自分](じぶん)の[才能](さいのう)や[使命](しめい)をしっかり[自覚](じかく)している。「もうおばさんだ」と[言](い)う[十](じゅう)[代](だい)も、ある[意味](いみ)、「[若](わか)くなければ[自分](じぶん)には[価値](かち)がない」と[自覚](じかく)しているのかも[知](し)れない。"],"questions":[{"no":18,"options":["が","に","とは","とか"],"answer":2,"grammar":"Nとは何か","grammar_vi":"~ là gì? (hỏi định nghĩa)","sentence":"[何](なん)[歳](さい)から[人](ひと)は[大人](おとな)と[呼](よ)ばれるのか、[大人](おとな)**とは**[何](なに)か。","sentence_vi":"Từ mấy tuổi thì một người được gọi là người lớn, người lớn là gì (vậy)."},{"no":19,"options":["スポーツ[選手](せんしゅ)もいるばかりに","スポーツ[選手](せんしゅ)もいると","スポーツ[選手](せんしゅ)もいなければ","スポーツ[選手](せんしゅ)もいれば"],"answer":3,"grammar":"Nもいれば~もいる","grammar_vi":"Có người ~ cũng có người ~","sentence":"[一方](いっぽう)、[十](じゅう)[二](に)、[三](さん)[歳](さい)でしっかりした[意識](いしき)を[持](も)ったタレントや**スポーツ[選手](せんしゅ)もいれば**、「[高校](こうこう)を[出](で)ればおばさん」と[言](い)っている[少女](しょうじょ)もいる。","sentence_vi":"Mặt khác, có cả những nghệ sĩ hay vận động viên mười hai, mười ba tuổi đã có ý thức vững vàng, lại cũng có những cô gái nói 'tốt nghiệp cấp ba là thành bà thím'."},{"no":20,"options":["じょじょに","いっそう","しだいに","いったい"],"answer":3,"grammar":"いったい","grammar_vi":"Rốt cuộc, cái gì mà (nhấn mạnh sự thắc mắc)","sentence":"**いったい**、だれが[大人](おとな)でだれが[若者](わかもの)なのか。","sentence_vi":"Rốt cuộc, ai là người lớn và ai là thanh niên?"},{"no":21,"options":["[生](い)きていた[方](ほう)がいい","[生](い)きていても[仕方](しかた)ない","[生](い)きていなければならない","[生](い)きていてもいい"],"answer":1,"grammar":"Vても仕方がない","grammar_vi":"Có ~ cũng vô ích, đành chịu","sentence":"「[私](わたし)は[親](おや)に[好](す)かれていなかった」「[自分](じぶん)なんて**[生](い)きていても[仕方](しかた)ない**」と、[彼](かれ)らはつぶやく。","sentence_vi":"'Cha mẹ không thương tôi', 'người như tôi thì sống cũng chẳng để làm gì' — họ lẩm bẩm như vậy."},{"no":22,"options":["[一方](いっぽう)","[案外](あんがい)","[事実](じじつ)","[当然](とうぜん)"],"answer":0,"grammar":"一方(liên từ)","grammar_vi":"Mặt khác, trong khi đó","sentence":"**[一方](いっぽう)**、「[大人](おとな)[顔負](かおま)けのプロ[意識](いしき)を[持](も)った[子](こ)ども」は、[自分](じぶん)の[才能](さいのう)や[使命](しめい)をしっかり[自覚](じかく)している。","sentence_vi":"Trong khi đó, 'những đứa trẻ có ý thức chuyên nghiệp không thua người lớn' lại tự giác rõ ràng tài năng và sứ mệnh của mình."}],"translation_vi":"Từ mấy tuổi thì người ta được gọi là người lớn, người lớn là gì. Dường như những cuộc tranh luận như vậy lặp đi lặp lại. Trước đây chỉ cần nghĩ 'đủ tuổi thành niên là người lớn' nên chuyện đơn giản, nhưng gần đây tiêu chuẩn ấy trở nên mơ hồ. Ngay cả trong thực tế lâm sàng tâm thần, người ta thường gặp những ca ở tuổi ba mươi, bốn mươi mới bộc lộ các vấn đề xuất phát từ bệnh lý tuổi dậy thì như chứng biếng ăn hay bạo lực gia đình.\\n\\nMặt khác, có cả những nghệ sĩ hay vận động viên mười hai, mười ba tuổi đã có ý thức vững vàng, lại cũng có những cô gái nói 'tốt nghiệp cấp ba là thành bà thím'. Cũng có bác sĩ tâm thần coi 'cảm giác đóng cửa sớm' của giới trẻ — sớm bỏ cuộc với bản thân kiểu 'người như mình thì chỉ đến thế thôi' — là vấn đề.\\n\\nRốt cuộc, ai là người lớn và ai là thanh niên? Sự phân biệt đó rất khó. 'Những người lớn mang bệnh lý tuổi dậy thì' nêu ở trên có điểm chung là rơi vào sự tự phủ nhận dữ dội trong mối quan hệ với cha mẹ và những người xung quanh. Họ lẩm bẩm: 'Cha mẹ không thương tôi', 'người như tôi thì sống cũng chẳng để làm gì'. Trong khi đó, 'những đứa trẻ có ý thức chuyên nghiệp không thua người lớn' lại tự giác rõ ràng tài năng và sứ mệnh của mình. Cô gái tuổi mười mấy nói 'tôi đã thành bà thím rồi' cũng có lẽ, theo một nghĩa nào đó, đang tự nhận rằng 'nếu không còn trẻ thì mình không có giá trị'."},{"paragraphs":["[本](ほん)を[読](よ)むことは、よいことだ。たとえ、それが[住居](じゅうきょ)の[貧困](ひんこん)の[反映](はんえい)であっても、[個人](こじん)が[自由](じゆう)な（48a）によって、それぞれの[精神](せいしん)の[個室](こしつ)をもつのはのぞましいことだ。[実際](じっさい)、そもそも「[個人](こじん)」というのは、そういうふうにして[成長](せいちょう)してゆくものだからである。","しかし、[家庭](かてい)のなかの[書物](しょもつ)というものを[考](かんが)えてみると、これはずいぶん、ふしぎな[備品](びひん)のような[気](き)がする。（49）、[本](ほん)は[家庭](かてい)の[備品](びひん)のひとつでありながら、[結局](けっきょく)のところ、[個人](こじん)にぞくするものであるからだ。[家庭](かてい)の[本棚](ほんだな)にならんでいる[何](なに)[十](じゅう)[冊](さつ)、あるいは[何](なん)[百](ひゃく)[冊](さつ)の[本](ほん)の[背](せ)[表紙](ひょうし)は、[家族](かぞく)のみんなが[毎日](まいにち)ながめている。（50）、その[一](いち)[冊](さつ)のページを[開](ひら)いて、なかに[入](はい)りこんでゆくのは、[家族](かぞく)のなかの[特定](とくてい)の[個人](こじん)でしかない。（51）、[本棚](ほんだな)にならんでいる[本](ほん)は、いわば、[家族](かぞく)みんなに[共有](きょうゆう)された（48b）の[象徴](しょうちょう)でありながら、[同時](どうじ)に、[家族](かぞく)の[個々](ここ)のメンバーが、そこに[開](ひら)いた[個室](こしつ)の「[入口](いりぐち)」の[並](なら)んでいる[状態](じょうたい)なのである。[本棚](ほんだな)の[前](まえ)に[立](た)つとき、[私](わたし)たちは、[家族](かぞく)の[他](ほか)のメンバーの「[個室](こしつ)」の[入口](いりぐち)の[前](まえ)に[立](た)っているわけであり、[背](せ)[表紙](ひょうし)を[読](よ)むことは、その[個室](こしつ)の[表札](ひょうさつ)を[読](よ)むことなのだ。そうだとすれば、[家族](かぞく)の[他](ほか)のメンバーの「[個室](こしつ)」のなかに、[私](わたし)たちは[勝手](かって)に[踏](ふ)み[込](こ)んでいいのだろうか。"],"questions":[{"no":48,"options":["[忍耐](にんたい)[力](りょく)／[娯楽](ごらく)[性](せい)","[観察](かんさつ)[力](りょく)／[経済](けいざい)[性](せい)","[想像](そうぞう)[力](りょく)／[社会](しゃかい)[性](せい)","[精神](せいしん)[力](りょく)／[閉鎖](へいさ)[性](せい)"],"answer":2,"grammar":"Nによって(phương thức)","grammar_vi":"Bằng ~, nhờ ~ (phương tiện)","sentence":"たとえ、それが[住居](じゅうきょ)の[貧困](ひんこん)の[反映](はんえい)であっても、[個人](こじん)が[自由](じゆう)な**[想像](そうぞう)[力](りょく)**によって、それぞれの[精神](せいしん)の[個室](こしつ)をもつのはのぞましいことだ。\\nつまり、[本棚](ほんだな)にならんでいる[本](ほん)は、いわば、[家族](かぞく)みんなに[共有](きょうゆう)された**[社会](しゃかい)[性](せい)**の[象徴](しょうちょう)でありながら、[同時](どうじ)に、[家族](かぞく)の[個々](ここ)のメンバーが、そこに[開](ひら)いた[個室](こしつ)の「[入口](いりぐち)」の[並](なら)んでいる[状態](じょうたい)なのである。","sentence_vi":"Dù đó có là phản ánh của sự nghèo nàn về nhà ở đi nữa, thì việc mỗi cá nhân nhờ trí tưởng tượng tự do mà có được 'căn phòng riêng' trong tâm hồn là điều đáng mong muốn.\\nNói cách khác, những cuốn sách xếp trên giá, có thể nói là biểu tượng của tính xã hội được cả gia đình cùng chia sẻ, đồng thời cũng là trạng thái xếp hàng của các 'lối vào' những căn phòng riêng mà từng thành viên trong gia đình đã mở ra ở đó."},{"no":49,"options":["[一方](いっぽう)","ところが","かえって","なぜなら"],"answer":3,"grammar":"なぜなら","grammar_vi":"Bởi vì, sở dĩ là vì","sentence":"**なぜなら**、[本](ほん)は[家庭](かてい)の[備品](びひん)のひとつでありながら、[結局](けっきょく)のところ、[個人](こじん)にぞくするものであるからだ。","sentence_vi":"Bởi vì sách tuy là một món đồ dùng của gia đình nhưng rốt cuộc lại thuộc về cá nhân."},{"no":50,"options":["それどころか","それについて","[最後](さいご)の[結論](けつろん)から","その[点](てん)で"],"answer":3,"grammar":"その点で","grammar_vi":"Xét về điểm đó, ở điểm đó","sentence":"**その[点](てん)で**、その[一](いち)[冊](さつ)のページを[開](ひら)いて、なかに[入](はい)りこんでゆくのは、[家族](かぞく)のなかの[特定](とくてい)の[個人](こじん)でしかない。","sentence_vi":"Ở điểm đó, người mở trang của một cuốn và đi vào bên trong cũng chỉ là một cá nhân nhất định trong gia đình."},{"no":51,"options":["ところで","つまり","もちろん","むしろ"],"answer":1,"grammar":"つまり","grammar_vi":"Tức là, nói cách khác","sentence":"**つまり**、[本棚](ほんだな)にならんでいる[本](ほん)は、いわば、[家族](かぞく)みんなに[共有](きょうゆう)された[社会](しゃかい)[性](せい)の[象徴](しょうちょう)でありながら、[同時](どうじ)に、[家族](かぞく)の[個々](ここ)のメンバーが、そこに[開](ひら)いた[個室](こしつ)の「[入口](いりぐち)」の[並](なら)んでいる[状態](じょうたい)なのである。","sentence_vi":"Nói cách khác, những cuốn sách xếp trên giá, có thể nói là biểu tượng của tính xã hội được cả gia đình cùng chia sẻ, đồng thời cũng là trạng thái xếp hàng của các 'lối vào' những căn phòng riêng mà từng thành viên trong gia đình đã mở ra ở đó."}],"translation_vi":"Đọc sách là điều tốt. Dù đó có là phản ánh của sự nghèo nàn về nhà ở đi nữa, thì việc mỗi cá nhân nhờ trí tưởng tượng tự do mà có được 'căn phòng riêng' trong tâm hồn là điều đáng mong muốn. Thực ra, vốn dĩ 'cá nhân' chính là lớn lên theo cách như vậy.\\n\\nTuy nhiên, khi nghĩ về sách trong gia đình, tôi có cảm giác chúng là một thứ đồ dùng khá kỳ lạ. Bởi vì sách tuy là một món đồ dùng của gia đình nhưng rốt cuộc lại thuộc về cá nhân. Gáy của hàng chục, hàng trăm cuốn sách xếp trên giá sách gia đình được cả nhà nhìn mỗi ngày. Ở điểm đó, người mở trang của một cuốn và đi vào bên trong cũng chỉ là một cá nhân nhất định trong gia đình. Nói cách khác, những cuốn sách xếp trên giá, có thể nói là biểu tượng của tính xã hội được cả gia đình cùng chia sẻ, đồng thời cũng là trạng thái xếp hàng của các 'lối vào' những căn phòng riêng mà từng thành viên trong gia đình đã mở ra ở đó. Khi đứng trước giá sách, chúng ta đang đứng trước lối vào 'căn phòng riêng' của các thành viên khác trong gia đình, và đọc gáy sách là đọc bảng tên của căn phòng ấy. Nếu vậy, liệu chúng ta có thể tự tiện bước vào 'căn phòng riêng' của thành viên khác trong gia đình không?"},{"paragraphs":["[近年](きんねん)、[急速](きゅうそく)に[普及](ふきゅう)してきた[電子](でんし)[書籍](しょせき)であるが、[紙](かみ)の[書籍](しょせき)に[代](か)わって[主流](しゅりゅう)になるかというと、（21）。[確](たし)かに、[電子](でんし)[書籍](しょせき)には「[持](も)ち[運](はこ)びが[楽](らく)」「[場所](ばしょ)をとらない」などのメリットが[多](おお)くある。（22）、[紙](かみ)の[書籍](しょせき)には「ページをめくる[感覚](かんかく)」「[本棚](ほんだな)に[並](なら)べる[楽](たの)しみ」といった、[電子](でんし)[書籍](しょせき)にはない[魅力](みりょく)が[存在](そんざい)する。（23）、[読書](どくしょ)[環境](かんきょう)や[好](この)みによって[両者](りょうしゃ)を[使](つか)い[分](わ)ける[人](ひと)が[増](ふ)えており、[紙](かみ)の[書籍](しょせき)が[完全](かんぜん)に[消](き)えてしまうことはないと[考](かんが)えられる。（24）、デジタル[化](か)が[進](すす)む[現代](げんだい)においても、[紙](かみ)の[文化](ぶんか)は[根強](ねづよ)く[残](のこ)っていくに（25）。"],"questions":[{"no":21,"options":["[必](かなら)ずしもそうとは[言](い)えない","そうと[言](い)わざるを[得](え)ない","そうに[違](ちが)いない","そうであるはずがない"],"answer":0,"grammar":"必ずしも~とは言えない","grammar_vi":"Không hẳn là ~, chưa chắc là ~","sentence":"[近年](きんねん)、[急速](きゅうそく)に[普及](ふきゅう)してきた[電子](でんし)[書籍](しょせき)であるが、[紙](かみ)の[書籍](しょせき)に[代](か)わって[主流](しゅりゅう)になるかというと、**[必](かなら)ずしもそうとは[言](い)えない**。","sentence_vi":"Nếu hỏi liệu sách điện tử có thay sách giấy để trở thành xu hướng chủ đạo hay không thì không hẳn có thể nói như vậy."},{"no":22,"options":["したがって","しかしながら","すなわち","たとえば"],"answer":1,"grammar":"しかしながら","grammar_vi":"Tuy nhiên (cách nói trang trọng)","sentence":"**しかしながら**、[紙](かみ)の[書籍](しょせき)には「ページをめくる[感覚](かんかく)」「[本棚](ほんだな)に[並](なら)べる[楽](たの)しみ」といった、[電子](でんし)[書籍](しょせき)にはない[魅力](みりょく)が[存在](そんざい)する。","sentence_vi":"Tuy nhiên, sách giấy có những sức hấp dẫn mà sách điện tử không có, như \\"cảm giác lật trang\\" và \\"niềm vui xếp lên giá sách\\"."},{"no":23,"options":["[実際](じっさい)の","[実際](じっさい)で","[実際](じっさい)に","[実際](じっさい)を"],"answer":2,"grammar":"実際に","grammar_vi":"Thực tế là, quả thật","sentence":"**[実際](じっさい)に**、[読書](どくしょ)[環境](かんきょう)や[好](この)みによって[両者](りょうしゃ)を[使](つか)い[分](わ)ける[人](ひと)が[増](ふ)えており、[紙](かみ)の[書籍](しょせき)が[完全](かんぜん)に[消](き)えてしまうことはないと[考](かんが)えられる。","sentence_vi":"Thực tế, số người dùng cả hai tùy môi trường đọc và sở thích đang tăng, nên có thể cho rằng sách giấy sẽ không biến mất hoàn toàn."},{"no":24,"options":["このように","このまま","これほど","これくらい"],"answer":0,"grammar":"このように","grammar_vi":"Như vậy, theo cách này (tổng kết điều vừa nói)","sentence":"**このように**、デジタル[化](か)が[進](すす)む[現代](げんだい)においても、[紙](かみ)の[文化](ぶんか)は[根強](ねづよ)く[残](のこ)っていくに[違](ちが)いない。","sentence_vi":"Như vậy, ngay cả trong thời đại số hóa tiến triển, văn hóa giấy chắc chắn sẽ vẫn còn bền bỉ."},{"no":25,"options":["[違](ちが)いない","ほかならない","すぎない","かぎらない"],"answer":0,"grammar":"Vる+に違いない","grammar_vi":"Chắc chắn là ~","sentence":"このように、デジタル[化](か)が[進](すす)む[現代](げんだい)においても、[紙](かみ)の[文化](ぶんか)は[根強](ねづよ)く[残](のこ)っていくに**[違](ちが)いない**。","sentence_vi":"Như vậy, ngay cả trong thời đại số hóa tiến triển, văn hóa giấy chắc chắn sẽ vẫn còn bền bỉ."}],"translation_vi":"Sách điện tử đã phổ biến nhanh chóng những năm gần đây, nhưng nếu hỏi liệu nó có thay sách giấy để trở thành xu hướng chủ đạo hay không thì không hẳn có thể nói như vậy. Quả thật sách điện tử có nhiều ưu điểm như \\"dễ mang theo\\", \\"không chiếm chỗ\\". Tuy nhiên, sách giấy có những sức hấp dẫn mà sách điện tử không có, như \\"cảm giác lật trang\\" và \\"niềm vui xếp lên giá sách\\". Thực tế, số người dùng cả hai tùy môi trường đọc và sở thích đang tăng, nên có thể cho rằng sách giấy sẽ không biến mất hoàn toàn. Như vậy, ngay cả trong thời đại số hóa tiến triển, văn hóa giấy chắc chắn sẽ vẫn còn bền bỉ."},{"paragraphs":["コミュニケーションにおいて、[言葉](ことば)だけでなく「[非](ひ)[言語](げんご)コミュニケーション」も[重要](じゅうよう)な[役割](やくわり)を[果](は)たしている。（21）、[表情](ひょうじょう)や[視線](しせん)、[身振](みぶ)り[手振](てぶ)りなどの[動作](どうさ)である。[人間](にんげん)は[感情](かんじょう)の[多](おお)くを[非](ひ)[言語](げんご)[的](てき)な[合図](あいず)で[表現](ひょうげん)しており、（22）[言葉](ことば)で「[大丈夫](だいじょうぶ)」と[言](い)っていても、[表情](ひょうじょう)が[暗](くら)ければ[相手](あいて)は[心配](しんぱい)になるものだ。[言葉](ことば)と[非](ひ)[言語](げんご)メッセージが[矛盾](むじゅん)する[場合](ばあい)、[人々](ひとびと)は[非](ひ)[言語](げんご)の[方](ほう)を[信用](しんよう)する[傾向](けいこう)があるという。したがって、[自分](じぶん)の[気持](きも)ちを[正確](せいかく)に[伝](つた)えるためには、[言葉](ことば)[選](えら)びだけに（23）、[立](た)ち[振](ふ)る[舞](ま)いにも[気](き)を[配](くば)る（24）。[相手](あいて)との[円滑](えんかつ)な[関係](かんけい)を[築](きず)くうえで、[視線](しせん)や[態度](たいど)の[重要](じゅうよう)[性](せい)を[再](さい)[認識](にんしき)すべき（25）。"],"questions":[{"no":21,"options":["たとえば","つまり","なぜなら","それに[対](たい)して"],"answer":1,"grammar":"つまり","grammar_vi":"Tức là, nói cách khác","sentence":"**つまり**、[表情](ひょうじょう)や[視線](しせん)、[身振](みぶ)り[手振](てぶ)りなどの[動作](どうさ)である。","sentence_vi":"Tức là những cử chỉ như nét mặt, ánh mắt, động tác tay chân."},{"no":22,"options":["たとえ","まるで","もしくは","どうせ"],"answer":0,"grammar":"たとえ~ても","grammar_vi":"Dù cho ~ đi nữa cũng ~","sentence":"[人間](にんげん)は[感情](かんじょう)の[多](おお)くを[非](ひ)[言語](げんご)[的](てき)な[合図](あいず)で[表現](ひょうげん)しており、**たとえ**[言葉](ことば)で「[大丈夫](だいじょうぶ)」と[言](い)っていても、[表情](ひょうじょう)が[暗](くら)ければ[相手](あいて)は[心配](しんぱい)になるものだ。","sentence_vi":"Con người biểu đạt phần lớn cảm xúc bằng tín hiệu phi ngôn ngữ, nên dù miệng nói \\"không sao\\" mà nét mặt u ám thì đối phương vẫn lo lắng."},{"no":23,"options":["とどまらず","[限](かぎ)り","こだわらず","かかわらず"],"answer":0,"grammar":"Nにとどまらず","grammar_vi":"Không chỉ dừng lại ở ~","sentence":"したがって、[自分](じぶん)の[気持](きも)ちを[正確](せいかく)に[伝](つた)えるためには、[言葉](ことば)[選](えら)びだけに**とどまらず**、[立](た)ち[振](ふ)る[舞](ま)いにも[気](き)を[配](くば)るべきである。","sentence_vi":"Để truyền đạt chính xác cảm xúc của mình, nên không chỉ dừng lại ở việc chọn lời mà còn chú ý cả cách cư xử."},{"no":24,"options":["べきである","わけではない","にすぎない","にほかならない"],"answer":0,"grammar":"Vる+べきだ","grammar_vi":"Nên ~, phải ~","sentence":"したがって、[自分](じぶん)の[気持](きも)ちを[正確](せいかく)に[伝](つた)えるためには、[言葉](ことば)[選](えら)びだけにとどまらず、[立](た)ち[振](ふ)る[舞](ま)いにも[気](き)を[配](くば)る**べきである**。","sentence_vi":"Để truyền đạt chính xác cảm xúc của mình, nên không chỉ dừng lại ở việc chọn lời mà còn chú ý cả cách cư xử."},{"no":25,"options":["でなかろう","であろうか","ではなかろうか","であろうと"],"answer":2,"grammar":"~ではなかろうか","grammar_vi":"Chẳng phải là ~ sao? (nhận định nhẹ nhàng)","sentence":"[相手](あいて)との[円滑](えんかつ)な[関係](かんけい)を[築](きず)くうえで、[視線](しせん)や[態度](たいど)の[重要](じゅうよう)[性](せい)を[再](さい)[認識](にんしき)すべき**ではなかろうか**。","sentence_vi":"Khi xây dựng mối quan hệ trơn tru với đối phương, chẳng phải ta nên nhận thức lại tầm quan trọng của ánh mắt và thái độ sao?"}],"translation_vi":"Trong giao tiếp, không chỉ lời nói mà \\"giao tiếp phi ngôn ngữ\\" cũng đóng vai trò quan trọng. Tức là những cử chỉ như nét mặt, ánh mắt, động tác tay chân. Con người biểu đạt phần lớn cảm xúc bằng tín hiệu phi ngôn ngữ, nên dù miệng nói \\"không sao\\" mà nét mặt u ám thì đối phương vẫn lo lắng. Khi lời nói và thông điệp phi ngôn ngữ mâu thuẫn, người ta có xu hướng tin vào phần phi ngôn ngữ. Vì vậy, để truyền đạt chính xác cảm xúc của mình, nên không chỉ dừng lại ở việc chọn lời mà còn chú ý cả cách cư xử. Khi xây dựng mối quan hệ trơn tru với đối phương, chẳng phải ta nên nhận thức lại tầm quan trọng của ánh mắt và thái độ sao?"},{"paragraphs":["[近年](きんねん)、[若者](わかもの)の[睡眠](すいみん)[不足](ふそく)が[社会](しゃかい)[問題](もんだい)となっている。[夜](よる)[遅](おそ)くまでスマートフォンを[使用](しよう)することが[主](おも)な[原因](げんいん)とされているが、（21）[画面](がめん)から[出](で)るブルーライトが[脳](のう)を[刺激](しげき)し、[眠気](ねむけ)を[妨](さまた)げるからだ。[睡眠](すいみん)が[不足](ふそく)すると、[集中](しゅうちゅう)[力](りょく)が[低下](ていか)して[学習](がくしゅう)[効率](こうりつ)が[落](お)ちる（22）、[体調](たいちょう)を[崩](くず)しやすくなるという[悪影響](あくえいきょう)が[生](しょう)じる。[成長](せいちょう)[期](き)にある[学生](がくせい)にとって、[適切](てきせつ)な[睡眠](すいみん)[時間](じかん)を[確保](かくほ)することは[健康](けんこう)[維持](いじ)に（23）。[夜間](やかん)はスマホの[使用](しよう)を[控](ひか)えるなど、[生活](せいかつ)[習慣](しゅうかん)を[見直](みなお)す（24）。[一人](ひとり)ひとりが[睡眠](すいみん)の[大切](たいせつ)さを[自覚](じかく)することが[求](もと)められているのではないかと[考](かんが)えられる。"],"questions":[{"no":21,"options":["というのは","というと","といっても","といえば"],"answer":0,"grammar":"~というのは~からだ","grammar_vi":"Sở dĩ như vậy là vì ~ (giải thích lý do)","sentence":"[夜](よる)[遅](おそ)くまでスマートフォンを[使用](しよう)することが[主](おも)な[原因](げんいん)とされているが、**というのは**[画面](がめん)から[出](で)るブルーライトが[脳](のう)を[刺激](しげき)し、[眠気](ねむけ)を[妨](さまた)げるからだ。","sentence_vi":"Việc dùng điện thoại thông minh đến khuya được cho là nguyên nhân chính, vì ánh sáng xanh phát ra từ màn hình kích thích não và cản trở cơn buồn ngủ."},{"no":22,"options":["ばかりか","[反面](はんめん)","たびに","くせに"],"answer":0,"grammar":"Thể thường+ばかりか","grammar_vi":"Không chỉ ~ mà còn ~","sentence":"[睡眠](すいみん)が[不足](ふそく)すると、[集中](しゅうちゅう)[力](りょく)が[低下](ていか)して[学習](がくしゅう)[効率](こうりつ)が[落](お)ちる**ばかりか**、[体調](たいちょう)を[崩](くず)しやすくなるという[悪影響](あくえいきょう)が[生](しょう)じる。","sentence_vi":"Khi thiếu ngủ, không chỉ khả năng tập trung giảm và hiệu quả học tập kém đi mà còn nảy sinh tác hại là dễ suy giảm sức khỏe."},{"no":23,"options":["[欠](か)かせない","[違](ちが)いない","[過](す)ぎない","[限](かぎ)らない"],"answer":0,"grammar":"Nに欠かせない","grammar_vi":"Không thể thiếu đối với ~","sentence":"[成長](せいちょう)[期](き)にある[学生](がくせい)にとって、[適切](てきせつ)な[睡眠](すいみん)[時間](じかん)を[確保](かくほ)することは[健康](けんこう)[維持](いじ)に**[欠](か)かせない**。","sentence_vi":"Với học sinh đang tuổi lớn, đảm bảo thời gian ngủ phù hợp là điều không thể thiếu để duy trì sức khỏe."},{"no":24,"options":["べきである","わけがない","はずがない","に[決](き)まっている"],"answer":0,"grammar":"Vる+べきだ","grammar_vi":"Nên ~, phải ~","sentence":"[夜間](やかん)はスマホの[使用](しよう)を[控](ひか)えるなど、[生活](せいかつ)[習慣](しゅうかん)を[見直](みなお)す**べきである**。","sentence_vi":"Nên xem lại thói quen sinh hoạt, chẳng hạn hạn chế dùng điện thoại vào ban đêm."}],"translation_vi":"Những năm gần đây, tình trạng thiếu ngủ ở giới trẻ đã trở thành vấn đề xã hội. Việc dùng điện thoại thông minh đến khuya được cho là nguyên nhân chính, vì ánh sáng xanh phát ra từ màn hình kích thích não và cản trở cơn buồn ngủ. Khi thiếu ngủ, không chỉ khả năng tập trung giảm và hiệu quả học tập kém đi mà còn nảy sinh tác hại là dễ suy giảm sức khỏe. Với học sinh đang tuổi lớn, đảm bảo thời gian ngủ phù hợp là điều không thể thiếu để duy trì sức khỏe. Nên xem lại thói quen sinh hoạt, chẳng hạn hạn chế dùng điện thoại vào ban đêm. Có thể cho rằng mỗi người cần nhận thức được tầm quan trọng của giấc ngủ."},{"paragraphs":["[環境](かんきょう)[問題](もんだい)への[関心](かんしん)が[高](たか)まる[中](なか)、[多](おお)くの[企業](きぎょう)がSDGs（[持続](じぞく)[可能](かのう)な[開発](かいはつ)[目標](もくひょう)）に[取](と)り[組](く)んでいる。[消費](しょうひ)[者](しゃ)の[側](がわ)も、[単](たん)に[価格](かかく)や[品質](ひんしつ)だけでなく、[環境](かんきょう)に[配慮](はいりょ)された[商品](しょうひん)であるか（21）[重視](じゅうし)して[購入](こうにゅう)を[決定](けってい)する[傾向](けいこう)が[強](つよ)まっている。（22）、[企業](きぎょう)にとっては[環境](かんきょう)[保護](ほご)への[取](と)り[組](く)みがブランドイメージの[向上](こうじょう)に[直結](ちょっけつ)する[時代](じだい)となった。[環境](かんきょう)[対策](たいさく)を[怠](おこた)る[企業](きぎょう)は、[社会](しゃかい)からの[信頼](しんらい)を[失](うしな)い（23）。[持続](じぞく)[可能](かのう)な[社会](しゃかい)の[実現](じつげん)に[向](む)けて、[企業](きぎょう)と[消費](しょうひ)[者](しゃ)が[一体](いったい)となって[取](と)り[組](く)んでいくことが（24）[重要](じゅうよう)になってくる（25）。"],"questions":[{"no":21,"options":["かどうかを","かどうかで","かどうかは","かどうか"],"answer":0,"grammar":"Thể thường+かどうか","grammar_vi":"~ hay không (câu hỏi lồng)","sentence":"[消費](しょうひ)[者](しゃ)の[側](がわ)も、[単](たん)に[価格](かかく)や[品質](ひんしつ)だけでなく、[環境](かんきょう)に[配慮](はいりょ)された[商品](しょうひん)であるか**かどうかを**[重視](じゅうし)して[購入](こうにゅう)を[決定](けってい)する[傾向](けいこう)が[強](つよ)まっている。","sentence_vi":"Về phía người tiêu dùng, xu hướng quyết định mua hàng với việc coi trọng sản phẩm có được quan tâm đến môi trường hay không, chứ không chỉ giá cả và chất lượng, cũng đang mạnh lên."},{"no":22,"options":["その[結果](けっか)","その[反面](はんめん)","そのかわり","そのうえ"],"answer":0,"grammar":"その結果","grammar_vi":"Kết quả là","sentence":"**その[結果](けっか)**、[企業](きぎょう)にとっては[環境](かんきょう)[保護](ほご)への[取](と)り[組](く)みがブランドイメージの[向上](こうじょう)に[直結](ちょっけつ)する[時代](じだい)となった。","sentence_vi":"Kết quả là, đối với doanh nghiệp, đã đến thời đại mà nỗ lực bảo vệ môi trường gắn thẳng với việc nâng cao hình ảnh thương hiệu."},{"no":23,"options":["かねない","がちだ","っこない","きれない"],"answer":0,"grammar":"V_ます_+かねない","grammar_vi":"Có thể dẫn đến ~ (điều xấu)","sentence":"[環境](かんきょう)[対策](たいさく)を[怠](おこた)る[企業](きぎょう)は、[社会](しゃかい)からの[信頼](しんらい)を[失](うしな)い**かねない**。","sentence_vi":"Doanh nghiệp lơ là biện pháp môi trường có thể mất lòng tin của xã hội."},{"no":24,"options":["ますます","たとえ","まったく","けっして"],"answer":0,"grammar":"ますます","grammar_vi":"Ngày càng, càng thêm","sentence":"[持続](じぞく)[可能](かのう)な[社会](しゃかい)の[実現](じつげん)に[向](む)けて、[企業](きぎょう)と[消費](しょうひ)[者](しゃ)が[一体](いったい)となって[取](と)り[組](く)んでいくことが**ますます**[重要](じゅうよう)になってくるに[違](ちが)いない。","sentence_vi":"Việc doanh nghiệp và người tiêu dùng cùng chung sức thực hiện chắc chắn sẽ ngày càng quan trọng."},{"no":25,"options":["に[違](ちが)いない","にほかならない","にすぎない","にすぎないと[言](い)える"],"answer":0,"grammar":"Vる+に違いない","grammar_vi":"Chắc chắn là ~","sentence":"[持続](じぞく)[可能](かのう)な[社会](しゃかい)の[実現](じつげん)に[向](む)けて、[企業](きぎょう)と[消費](しょうひ)[者](しゃ)が[一体](いったい)となって[取](と)り[組](く)んでいくことがますます[重要](じゅうよう)になってくる**に[違](ちが)いない**。","sentence_vi":"Việc doanh nghiệp và người tiêu dùng cùng chung sức thực hiện chắc chắn sẽ ngày càng quan trọng."}],"translation_vi":"Trong bối cảnh quan tâm đến vấn đề môi trường tăng lên, nhiều doanh nghiệp đang thực hiện SDGs (Mục tiêu phát triển bền vững). Về phía người tiêu dùng, xu hướng quyết định mua hàng với việc coi trọng sản phẩm có được quan tâm đến môi trường hay không, chứ không chỉ giá cả và chất lượng, cũng đang mạnh lên. Kết quả là, đối với doanh nghiệp, đã đến thời đại mà nỗ lực bảo vệ môi trường gắn thẳng với việc nâng cao hình ảnh thương hiệu. Doanh nghiệp lơ là biện pháp môi trường có thể mất lòng tin của xã hội. Để hiện thực hóa xã hội bền vững, việc doanh nghiệp và người tiêu dùng cùng chung sức thực hiện chắc chắn sẽ ngày càng quan trọng."},{"paragraphs":["[人工](じんこう)[知能](ちのう)（AI）[技術](ぎじゅつ)の[進化](しんか)は[目覚](めざ)ましく、[医療](いりょう)や[交通](こうつう)など[多様](たよう)な[分野](ぶんや)で[活用](かつよう)が[進](すす)んでいる。AIは[膨大](ぼうだい)なデータを[瞬時](しゅんじ)に[処理](しょり)できる（21）、[人間](にんげん)の[仕事](しごと)を[奪](うば)うのではないかという[懸念](けねん)も[存在](そんざい)する。（22）、AIは[過去](かこ)のデータに[基](もと)づいた[判断](はんだん)が[得意](とくい)である[一方](いっぽう)で、[創造](そうぞう)[性](せい)や[共感](きょうかん)[力](りょく)が[必要](ひつよう)な[分野](ぶんや)では[人間](にんげん)には[及](およ)ばない。[大切](たいせつ)なのはAIを[排除](はいじょ)することではなく、[人間](にんげん)とAIがそれぞれの[強](つよ)みを[活](い)かして[共存](きょうぞん)していくことだ。テクノロジーの[発展](はってん)を[恐](おそ)れる（24）、[上手](じょうず)に[活用](かつよう)する[道](みち)を[模索](もさく)すべき（25）。"],"questions":[{"no":21,"options":["[反面](はんめん)","うえで","からには","に[際](さい)して"],"answer":0,"grammar":"Thể thường+反面","grammar_vi":"Mặt khác, trái lại ~","sentence":"AIは[膨大](ぼうだい)なデータを[瞬時](しゅんじ)に[処理](しょり)できる**[反面](はんめん)**、[人間](にんげん)の[仕事](しごと)を[奪](うば)うのではないかという[懸念](けねん)も[存在](そんざい)する。","sentence_vi":"AI có thể xử lý lượng dữ liệu khổng lồ ngay lập tức, nhưng mặt khác cũng có mối lo ngại rằng nó sẽ cướp mất việc làm của con người."},{"no":22,"options":["しかし","つまり","ところで","したがって"],"answer":0,"grammar":"しかし","grammar_vi":"Nhưng, tuy nhiên (nối hai câu đối lập)","sentence":"**しかし**、AIは[過去](かこ)のデータに[基](もと)づいた[判断](はんだん)が[得意](とくい)である[一方](いっぽう)で、[創造](そうぞう)[性](せい)や[共感](きょうかん)[力](りょく)が[必要](ひつよう)な[分野](ぶんや)では[人間](にんげん)には[及](およ)ばない。","sentence_vi":"Tuy nhiên, AI giỏi đưa ra phán đoán dựa trên dữ liệu quá khứ, nhưng trong những lĩnh vực cần sự sáng tạo và đồng cảm thì không bằng con người."},{"no":24,"options":["ことなく","ことから","ことには","ことにして"],"answer":0,"grammar":"Vる+ことなく","grammar_vi":"Mà không ~","sentence":"テクノロジーの[発展](はってん)を[恐](おそ)れる**ことなく**、[上手](じょうず)に[活用](かつよう)する[道](みち)を[模索](もさく)すべきである。","sentence_vi":"Chúng ta nên tìm con đường tận dụng khéo léo mà không sợ hãi sự phát triển của công nghệ."},{"no":25,"options":["である","ではない","にほかならない","のではないだろうか"],"answer":0,"grammar":"Vる+べきだ","grammar_vi":"Nên ~, phải ~","sentence":"テクノロジーの[発展](はってん)を[恐](おそ)れることなく、[上手](じょうず)に[活用](かつよう)する[道](みち)を[模索](もさく)すべき**である**。","sentence_vi":"Chúng ta nên tìm con đường tận dụng khéo léo mà không sợ hãi sự phát triển của công nghệ."}],"translation_vi":"Công nghệ trí tuệ nhân tạo (AI) tiến hóa vượt bậc, việc ứng dụng đang tiến triển ở nhiều lĩnh vực như y tế và giao thông. AI có thể xử lý lượng dữ liệu khổng lồ ngay lập tức, nhưng mặt khác cũng có mối lo ngại rằng nó sẽ cướp mất việc làm của con người. Tuy nhiên, AI giỏi đưa ra phán đoán dựa trên dữ liệu quá khứ, nhưng trong những lĩnh vực cần sự sáng tạo và đồng cảm thì không bằng con người. Điều quan trọng không phải là loại bỏ AI mà là con người và AI phát huy thế mạnh của mỗi bên để cùng tồn tại. Chúng ta nên tìm con đường tận dụng khéo léo mà không sợ hãi sự phát triển của công nghệ."},{"paragraphs":["[日本](にほん)の[伝統](でんとう)[工芸](こうげい)[品](ひん)が[今](いま)、[若者](わかもの)の[間](ま)で[見直](みなお)されている。[職人](しょくにん)がひとつひとつ[手作](てづく)りで[仕上](しあ)げた[品々](しなじな)には、[量産](りょうさん)[品](ひん)にはない[温](あたた)かみや[味](あじ)わいがある。（21）、[若者](わかもの)のライフスタイルに[合](あ)わせたデザインや[現代](げんだい)[的](てき)なアレンジを[加](くわ)えた[商品](しょうひん)も[増](ふ)えており、[海外](かいがい)からの[注目](ちゅうもく)も[集](あつ)めている。（22）、[後継](こうけい)[者](しゃ)[不足](ふそく)などの[課題](かだい)も[深刻](しんこく)であり、[伝統](でんとう)を[継承](けいしょう)していくためには（23）[支援](しえん)が[必要](ひつよう)である。[伝統](でんとう)を[守](まも)り（24）[新](あたら)しい[挑戦](ちょうせん)を[続](つづ)ける[職人](しょくにん)たちの[姿](すがた)は、[多](おお)くの[人々](ひとびと)に[感動](かんどう)を[与](あた)えている（25）。"],"questions":[{"no":21,"options":["さらに","しかし","なぜなら","つまり"],"answer":0,"grammar":"さらに","grammar_vi":"Hơn nữa, thêm vào đó","sentence":"**さらに**、[若者](わかもの)のライフスタイルに[合](あ)わせたデザインや[現代](げんだい)[的](てき)なアレンジを[加](くわ)えた[商品](しょうひん)も[増](ふ)えており、[海外](かいがい)からの[注目](ちゅうもく)も[集](あつ)めている。","sentence_vi":"Hơn nữa, những sản phẩm có thiết kế hợp với phong cách sống của giới trẻ hay thêm cách biến tấu hiện đại cũng đang tăng, thu hút cả sự chú ý từ nước ngoài."},{"no":22,"options":["[一方](いっぽう)で","その[結果](けっか)","したがって","たとえば"],"answer":0,"grammar":"一方で","grammar_vi":"Mặt khác, trong khi đó","sentence":"**[一方](いっぽう)で**、[後継](こうけい)[者](しゃ)[不足](ふそく)などの[課題](かだい)も[深刻](しんこく)であり、[伝統](でんとう)を[継承](けいしょう)していくためにはさらなる[支援](しえん)が[必要](ひつよう)である。","sentence_vi":"Mặt khác, các vấn đề như thiếu người kế nghiệp cũng nghiêm trọng, và để kế thừa truyền thống thì cần sự hỗ trợ hơn nữa."},{"no":23,"options":["さらなる","さらにの","さらには","さらにも"],"answer":0,"grammar":"さらなる+N","grammar_vi":"N hơn nữa, N thêm nữa","sentence":"[一方](いっぽう)で、[後継](こうけい)[者](しゃ)[不足](ふそく)などの[課題](かだい)も[深刻](しんこく)であり、[伝統](でんとう)を[継承](けいしょう)していくためには**さらなる**[支援](しえん)が[必要](ひつよう)である。","sentence_vi":"Mặt khác, các vấn đề như thiếu người kế nghiệp cũng nghiêm trọng, và để kế thừa truyền thống thì cần sự hỗ trợ hơn nữa."},{"no":24,"options":["つつ","ばかり","からには","に[際](さい)して"],"answer":0,"grammar":"V_ます_+つつ","grammar_vi":"Vừa ~ vừa (dù biết ~)","sentence":"[伝統](でんとう)を[守](まも)り**つつ**[新](あたら)しい[挑戦](ちょうせん)を[続](つづ)ける[職人](しょくにん)たちの[姿](すがた)は、[多](おお)くの[人々](ひとびと)に[感動](かんどう)を[与](あた)えているに[違](ちが)いない。","sentence_vi":"Hình ảnh những người thợ vừa giữ gìn truyền thống vừa tiếp tục thử thách mới chắc chắn đang mang lại cảm động cho nhiều người."},{"no":25,"options":["に[違](ちが)いない","にすぎない","にほかならない","ものではない"],"answer":0,"grammar":"Vる+に違いない","grammar_vi":"Chắc chắn là ~","sentence":"[伝統](でんとう)を[守](まも)りつつ[新](あたら)しい[挑戦](ちょうせん)を[続](つづ)ける[職人](しょくにん)たちの[姿](すがた)は、[多](おお)くの[人々](ひとびと)に[感動](かんどう)を[与](あた)えている**に[違](ちが)いない**。","sentence_vi":"Hình ảnh những người thợ vừa giữ gìn truyền thống vừa tiếp tục thử thách mới chắc chắn đang mang lại cảm động cho nhiều người."}],"translation_vi":"Đồ thủ công truyền thống của Nhật Bản hiện đang được giới trẻ đánh giá lại. Những sản phẩm do thợ thủ công làm từng chiếc bằng tay có sự ấm áp và nét đặc sắc mà hàng sản xuất hàng loạt không có. Hơn nữa, những sản phẩm có thiết kế hợp với phong cách sống của giới trẻ hay thêm cách biến tấu hiện đại cũng đang tăng, thu hút cả sự chú ý từ nước ngoài. Mặt khác, các vấn đề như thiếu người kế nghiệp cũng nghiêm trọng, và để kế thừa truyền thống thì cần sự hỗ trợ hơn nữa. Hình ảnh những người thợ vừa giữ gìn truyền thống vừa tiếp tục thử thách mới chắc chắn đang mang lại cảm động cho nhiều người."},{"paragraphs":["[異](い)[文化](ぶんか)[理解](りかい)を[進](すす)めるためには、[単](たん)に[相手](あいて)の[国](くに)の[文化](ぶんか)や[習慣](しゅうかん)を[知識](ちしき)として[学](まな)ぶだけでは（21）。[実際](じっさい)にその[文化](ぶんか)で[育](そだ)った[人](ひと)と[接](せっ)し、[互](たが)いの[違](ちが)いを[実感](じっかん)することが[不可欠](ふかけつ)である。（22）、[自分](じぶん)たちの「[当](あ)たり[前](まえ)」が[相手](あいて)にとってはそうではないと[気](き)づいたとき、[本当](ほんとう)の[異](い)[文化](ぶんか)[理解](りかい)が[始](はじ)まるからだ。[自分](じぶん)の[価値](かち)[観](かん)を[押](お)し[付](つ)ける（23）、[違](ちが)いを[尊重](そんちょう)し[受](う)け[入](い)れる[姿勢](しせい)が[必要](ひつよう)だ。[多](た)[文化](ぶんか)[共生](きょうせい)[社会](しゃかい)を[実現](じつげん)する（24）、[一人](ひとり)ひとりが[柔軟](じゅうなん)な[思考](しこう)を[持](も)つことが（25）。"],"questions":[{"no":21,"options":["[不十分](ふじゅうぶん)である","[十分](じゅうぶん)である","[不可欠](ふかけつ)である","[当然](とうぜん)である"],"answer":0,"grammar":"Nだけでは不十分だ","grammar_vi":"Chỉ ~ thôi thì chưa đủ","sentence":"[異](い)[文化](ぶんか)[理解](りかい)を[進](すす)めるためには、[単](たん)に[相手](あいて)の[国](くに)の[文化](ぶんか)や[習慣](しゅうかん)を[知識](ちしき)として[学](まな)ぶだけでは**[不十分](ふじゅうぶん)である**。","sentence_vi":"Để thúc đẩy sự thấu hiểu đa văn hóa thì chỉ học văn hóa, phong tục của nước đối phương như kiến thức là chưa đủ."},{"no":22,"options":["なぜなら","ただし","つまり","したがって"],"answer":0,"grammar":"なぜなら","grammar_vi":"Bởi vì, sở dĩ là vì","sentence":"**なぜなら**、[自分](じぶん)たちの「[当](あ)たり[前](まえ)」が[相手](あいて)にとってはそうではないと[気](き)づいたとき、[本当](ほんとう)の[異](い)[文化](ぶんか)[理解](りかい)が[始](はじ)まるからだ。","sentence_vi":"Bởi vì khi nhận ra điều \\"hiển nhiên\\" của mình không phải là hiển nhiên với đối phương, sự thấu hiểu đa văn hóa thực sự mới bắt đầu."},{"no":23,"options":["ことなく","ことから","ことにして","ことには"],"answer":0,"grammar":"Vる+ことなく","grammar_vi":"Mà không ~","sentence":"[自分](じぶん)の[価値](かち)[観](かん)を[押](お)し[付](つ)ける**ことなく**、[違](ちが)いを[尊重](そんちょう)し[受](う)け[入](い)れる[姿勢](しせい)が[必要](ひつよう)だ。","sentence_vi":"Cần có thái độ tôn trọng và chấp nhận sự khác biệt mà không áp đặt giá trị quan của mình."},{"no":24,"options":["うえで","[際](さい)して","にともなって","をめぐって"],"answer":0,"grammar":"Vる+うえで","grammar_vi":"Khi ~, trong việc ~","sentence":"[多](た)[文化](ぶんか)[共生](きょうせい)[社会](しゃかい)を[実現](じつげん)する**うえで**、[一人](ひとり)ひとりが[柔軟](じゅうなん)な[思考](しこう)を[持](も)つことが[求](もと)められている。","sentence_vi":"Khi hiện thực hóa xã hội cộng sinh đa văn hóa, việc mỗi người có tư duy linh hoạt đang được đòi hỏi."},{"no":25,"options":["[求](もと)められている","[求](もと)めている","[求](もと)めたがっている","[求](もと)めさせている"],"answer":0,"grammar":"Vられている(được yêu cầu)","grammar_vi":"Đang được ~ (đòi hỏi, yêu cầu)","sentence":"[多](た)[文化](ぶんか)[共生](きょうせい)[社会](しゃかい)を[実現](じつげん)するうえで、[一人](ひとり)ひとりが[柔軟](じゅうなん)な[思考](しこう)を[持](も)つことが**[求](もと)められている**。","sentence_vi":"Khi hiện thực hóa xã hội cộng sinh đa văn hóa, việc mỗi người có tư duy linh hoạt đang được đòi hỏi."}],"translation_vi":"Để thúc đẩy sự thấu hiểu đa văn hóa thì chỉ học văn hóa, phong tục của nước đối phương như kiến thức là chưa đủ. Việc tiếp xúc với người lớn lên trong nền văn hóa đó và cảm nhận sự khác biệt của nhau là không thể thiếu. Bởi vì khi nhận ra điều \\"hiển nhiên\\" của mình không phải là hiển nhiên với đối phương, sự thấu hiểu đa văn hóa thực sự mới bắt đầu. Cần có thái độ tôn trọng và chấp nhận sự khác biệt mà không áp đặt giá trị quan của mình. Khi hiện thực hóa xã hội cộng sinh đa văn hóa, việc mỗi người có tư duy linh hoạt đang được đòi hỏi."}]`);export{n as default};
